CREATE OR REPLACE FUNCTION pos.h101_ensure_reference_family()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if new.record_model = 'v2' and new.reference_family_id is null then
    new.reference_family_id := gen_random_uuid();
  elsif new.record_model = 'v1' then
    new.reference_family_id := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_reference_family_batch_h101_internal(p_operation_id uuid, p_reference_family_id uuid, p_rows jsonb, p_protocol_version integer, p_data_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare
  v_hash text := md5(jsonb_build_object('family',p_reference_family_id,'rows',p_rows)::text);
  v_prior jsonb; v_before jsonb; v_after jsonb; v_ids text[];
begin
  perform pos.assert_sync_write_context(p_protocol_version,p_data_epoch);
  perform pos.require_current_capability('inventory.adjust');
  if p_operation_id is null or p_reference_family_id is null
     or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)=0 then
    raise exception 'INVALID_REFERENCE_FAMILY_BATCH' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_array_elements(p_rows) r
      where coalesce(r->>'record_model','')<>'v2'
         or nullif(r->>'id','') is null
         or (r->>'reference_family_id')::uuid<>p_reference_family_id) then
    raise exception 'REFERENCE_FAMILY_SCOPE_MISMATCH' using errcode='22023';
  end if;
  select array_agg(r->>'id' order by r->>'id') into v_ids from jsonb_array_elements(p_rows) r;
  if cardinality(v_ids)<>jsonb_array_length(p_rows)
     or cardinality(v_ids)<>cardinality(array(select distinct unnest(v_ids))) then
    raise exception 'PRODUCT_SCOPE_INVALID' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_operation_id::text));
  select result into v_prior from pos.capability_operation_audit
   where operation_id=p_operation_id and capability_key='inventory.adjust' and payload_hash=v_hash;
  if found then return v_prior; end if;
  if exists(select 1 from pos.capability_operation_audit where operation_id=p_operation_id) then
    raise exception 'INVENTORY_OPERATION_CONFLICT' using errcode='40001';
  end if;

  perform 1 from pos.products where id=any(v_ids) order by id for update;
  select coalesce(jsonb_agg(to_jsonb(p) order by p.id),'[]'::jsonb) into v_before
    from pos.products p where p.id=any(v_ids);

  insert into pos.products(
    id,cat,manga,tela,color,cuello,modelo,nombre,orn,orn_colors,precio,costo,pop,
    stock,imagen,sku,barcode_urls,attrs,precios_talla,sync_base_version,sync_device_id,
    record_model,size_category_id,size_code,size_scale,stock_quantity,barcode_code,
    ornament_color_codes,physical_signature,reference_family_id,barcode_contract
  )
  select x.id,x.cat,x.manga,x.tela,x.color,coalesce(x.cuello,'NOR'),x.modelo,x.nombre,
    coalesce(x.orn,'—'),coalesce(x.orn_colors,'[]'),coalesce(x.precio,0),coalesce(x.costo,0),
    coalesce(x.pop,false),coalesce(x.stock,'[]'),x.imagen,x.sku,coalesce(x.barcode_urls,'{}'),
    coalesce(x.attrs,'{}'),coalesce(x.precios_talla,'{}'),x.sync_base_version,x.sync_device_id,
    'v2',x.size_category_id,x.size_code,x.size_scale,x.stock_quantity,x.barcode_code,
    coalesce(x.ornament_color_codes,'[]'),x.physical_signature,x.reference_family_id,x.barcode_contract
  from jsonb_to_recordset(p_rows) as x(
    id text,cat text,manga text,tela text,color text,cuello text,modelo text,nombre text,
    orn text,orn_colors jsonb,precio numeric,costo numeric,pop boolean,stock jsonb,imagen text,
    sku text,barcode_urls jsonb,attrs jsonb,precios_talla jsonb,sync_base_version bigint,
    sync_device_id text,record_model text,size_category_id text,size_code text,size_scale text,
    stock_quantity integer,barcode_code text,ornament_color_codes jsonb,physical_signature text,
    reference_family_id uuid,barcode_contract smallint
  )
  on conflict(id) do update set
    cat=excluded.cat,manga=excluded.manga,tela=excluded.tela,color=excluded.color,
    cuello=excluded.cuello,modelo=excluded.modelo,nombre=excluded.nombre,orn=excluded.orn,
    orn_colors=excluded.orn_colors,precio=excluded.precio,costo=excluded.costo,pop=excluded.pop,
    stock=excluded.stock,imagen=excluded.imagen,sku=excluded.sku,barcode_urls=excluded.barcode_urls,
    attrs=excluded.attrs,precios_talla=excluded.precios_talla,
    sync_base_version=(select source_row.sync_base_version
      from jsonb_to_recordset(p_rows) as source_row(id text,sync_base_version bigint)
      where source_row.id=excluded.id),sync_device_id=excluded.sync_device_id,
    size_category_id=excluded.size_category_id,size_code=excluded.size_code,size_scale=excluded.size_scale,
    stock_quantity=excluded.stock_quantity,ornament_color_codes=excluded.ornament_color_codes,
    physical_signature=excluded.physical_signature,reference_family_id=excluded.reference_family_id;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.id),'[]'::jsonb) into v_after
    from pos.products p where p.id=any(v_ids);
  v_prior := jsonb_build_object('ok',true,'operationId',p_operation_id,
    'referenceFamilyId',p_reference_family_id,'productIds',to_jsonb(v_ids),
    'before',v_before,'rows',v_after);
  insert into pos.capability_operation_audit(
    operation_id,capability_key,actor_user_id,subject_key,payload_hash,result
  ) values(p_operation_id,'inventory.adjust',auth.uid(),p_reference_family_id::text,v_hash,v_prior);
  return v_prior;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_reference_family_batch(p_operation_id uuid, p_reference_family_id uuid, p_rows jsonb, p_protocol_version integer, p_data_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text]::text[]);
  perform pos.assert_device_recovery_write(x->>'sync_device_id',array[p_operation_id::text]::text[]) from jsonb_array_elements(p_rows) x;
  perform set_config('pos.h149_rpc','on',true);
  if p_operation_id is null or p_reference_family_id is null
     or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'INVALID_REFERENCE_FAMILY_BATCH' using errcode='22023';
  end if;

  -- Un ID ya persistido sólo puede editarse dentro de su familia V2 actual.
  -- Los IDs nuevos no hacen match y pueden nacer en la familia solicitada.
  if exists (
    select 1
      from jsonb_array_elements(p_rows) r
      join pos.products p on p.id = r->>'id'
     where p.record_model <> 'v2'
        or p.reference_family_id is distinct from p_reference_family_id
  ) then
    raise exception 'REFERENCE_FAMILY_EXISTING_SCOPE_MISMATCH' using errcode='22023';
  end if;

  return pos.commit_reference_family_batch_h101_internal(
    p_operation_id, p_reference_family_id, p_rows,
    p_protocol_version, p_data_epoch
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.reserve_sale_stock(p_operation_id text, p_folio text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  prior pos.stock_reservations%rowtype;
  shortages jsonb;
  rec record;
  updated_row jsonb;
  updated_products jsonb := '[]'::jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para reservar inventario'
      using errcode = '42501';
  end if;

  if nullif(trim(p_operation_id), '') is null
     or nullif(trim(p_folio), '') is null
     or jsonb_typeof(p_lines) <> 'array'
     or jsonb_array_length(p_lines) = 0 then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;

  if exists (
    select 1
      from jsonb_to_recordset(p_lines)
        as x(product_id text, talla text, qty integer)
     where nullif(trim(x.product_id), '') is null
        or nullif(trim(x.talla), '') is null
        or x.qty is null
        or x.qty <= 0
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_lines');
  end if;

  -- Serializa reintentos de la misma operación antes de consultar idempotencia.
  perform pg_advisory_xact_lock(hashtext(p_operation_id));

  select * into prior
    from pos.stock_reservations
   where operation_id = p_operation_id;

  if found then
    if prior.folio <> p_folio or prior.lines <> p_lines then
      return jsonb_build_object('ok', false, 'error', 'operation_mismatch');
    end if;
    select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
      into updated_products
      from pos.products p
     where p.id in (
       select distinct x.product_id
         from jsonb_to_recordset(p_lines)
           as x(product_id text, talla text, qty integer)
     );
    return jsonb_build_object(
      'ok', true, 'idempotent', true, 'operation_id', p_operation_id,
      'products', updated_products
    );
  end if;

  -- El orden estable evita deadlocks cuando dos ventas incluyen varios modelos.
  perform p.id
    from pos.products p
   where p.id in (
     select distinct x.product_id
       from jsonb_to_recordset(p_lines)
         as x(product_id text, talla text, qty integer)
   )
   order by p.id
   for update;

  with requested as (
    select x.product_id, x.talla, sum(x.qty)::integer as qty
      from jsonb_to_recordset(p_lines)
        as x(product_id text, talla text, qty integer)
     group by x.product_id, x.talla
  ),
  availability as (
    select r.*,
           p.id is not null as product_exists,
           coalesce((
             select (elem ->> 'stock')::integer
               from jsonb_array_elements(p.stock) elem
              where elem ->> 'talla' = r.talla
              limit 1
           ), 0) as available
      from requested r
      left join pos.products p
        on p.id = r.product_id and p.deleted_at is null
  )
  select jsonb_agg(jsonb_build_object(
           'product_id', product_id,
           'talla', talla,
           'requested', qty,
           'available', available,
           'reason', case when not product_exists then 'product_not_found'
                          else 'insufficient_stock' end
         ) order by product_id, talla)
    into shortages
    from availability
   where not product_exists or available < qty;

  if shortages is not null then
    return jsonb_build_object(
      'ok', false, 'error', 'insufficient_stock', 'shortages', shortages
    );
  end if;

  for rec in
    with requested as (
      select x.product_id, x.talla, sum(x.qty)::integer as qty
        from jsonb_to_recordset(p_lines)
          as x(product_id text, talla text, qty integer)
       group by x.product_id, x.talla
    )
    select r.product_id, r.talla, r.qty,
           (elem.value ->> 'stock')::integer as available,
           elem.ordinality::integer - 1 as stock_index
      from requested r
      join pos.products p on p.id = r.product_id
      cross join lateral jsonb_array_elements(p.stock)
        with ordinality as elem(value, ordinality)
     where elem.value ->> 'talla' = r.talla
     order by r.product_id, r.talla
  loop
    update pos.products p
       set stock = jsonb_set(
             p.stock,
             array[rec.stock_index::text, 'stock'],
             to_jsonb(rec.available - rec.qty),
             false
           ),
           sync_base_version = p.sync_version,
           sync_device_id = 'sale:' || p_operation_id
     where p.id = rec.product_id
     returning to_jsonb(p.*) into updated_row;

  end loop;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
    into updated_products
    from pos.products p
   where p.id in (
     select distinct x.product_id
       from jsonb_to_recordset(p_lines)
         as x(product_id text, talla text, qty integer)
   );

  insert into pos.stock_reservations (
    operation_id, folio, lines, actor_email
  ) values (
    p_operation_id, p_folio, p_lines, auth.jwt() ->> 'email'
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'operation_id', p_operation_id,
    'products', updated_products
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.test_data_cleanup_plan(p_preset text DEFAULT 'operations'::text, p_selection jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos', 'extensions'
AS $function$
declare
  v_preset text := lower(trim(coalesce(p_preset,'operations')));
  v_requested jsonb;
  v_normalized jsonb;
  v_forced jsonb := '[]'::jsonb;
  v_documents jsonb;
  v_stock jsonb;
  v_issues jsonb;
  v_counts jsonb;
  v_reasons jsonb := '[]'::jsonb;
  v_epoch bigint;
  v_mode text;
  v_queue bigint;
  v_blocked bigint;
  v_unsynchronized bigint;
  v_incompatible bigint;
  v_core jsonb;
  v_hash text;
  v_sales boolean;
  v_returns boolean;
  v_orphan_return_evidence boolean;
  v_exchanges boolean;
  v_loans boolean;
  v_commissions boolean;
  v_reclassifications boolean;
  v_customers boolean;
  v_inventory boolean;
begin
  if v_preset not in ('operations','custom') then
    raise exception 'cleanup_invalid_preset' using errcode='22023';
  end if;
  if jsonb_typeof(coalesce(p_selection,'{}'::jsonb)) <> 'object' then
    raise exception 'cleanup_invalid_selection' using errcode='22023';
  end if;

  v_requested := case when v_preset='operations' then jsonb_build_object(
    'sales',true,'returns',true,'orphan_return_evidence',false,'exchanges',true,'loans',true,'commissions',true,
    'reclassifications',false,'customers',false,'inventory_products',false)
  else jsonb_build_object(
    'sales',coalesce((p_selection->>'sales')::boolean,false),
    'returns',coalesce((p_selection->>'returns')::boolean,false),
    'orphan_return_evidence',coalesce((p_selection->>'orphan_return_evidence')::boolean,false),
    'exchanges',coalesce((p_selection->>'exchanges')::boolean,false),
    'loans',coalesce((p_selection->>'loans')::boolean,false),
    'commissions',coalesce((p_selection->>'commissions')::boolean,false),
    'reclassifications',coalesce((p_selection->>'reclassifications')::boolean,false),
    'customers',coalesce((p_selection->>'customers')::boolean,false),
    'inventory_products',coalesce((p_selection->>'inventory_products')::boolean,false)) end;

  v_sales := (v_requested->>'sales')::boolean;
  v_returns := (v_requested->>'returns')::boolean;
  v_orphan_return_evidence := (v_requested->>'orphan_return_evidence')::boolean;
  v_exchanges := (v_requested->>'exchanges')::boolean;
  v_loans := (v_requested->>'loans')::boolean;
  v_commissions := (v_requested->>'commissions')::boolean;
  v_reclassifications := (v_requested->>'reclassifications')::boolean;
  v_customers := (v_requested->>'customers')::boolean;
  v_inventory := (v_requested->>'inventory_products')::boolean;

  -- Una venta no puede sobrevivir sin sus efectos posventa dependientes.
  if v_sales and not v_returns and exists(
    select 1 from pos.returns r join pos.sales s on s.folio=r.folio) then
    v_returns := true; v_forced := v_forced || jsonb_build_array('returns:dependent_on_sales');
  end if;
  if v_sales and not v_exchanges and exists(
    select 1 from pos.exchanges e join pos.sales s on s.folio=e.origen_folio or s.folio=e.folio) then
    v_exchanges := true; v_forced := v_forced || jsonb_build_array('exchanges:dependent_on_sales');
  end if;
  v_normalized := jsonb_build_object(
    'sales',v_sales,'returns',v_returns,
    'orphan_return_evidence',v_orphan_return_evidence,'exchanges',v_exchanges,'loans',v_loans,
    'commissions',v_commissions,'reclassifications',v_reclassifications,
    'customers',v_customers,'inventory_products',v_inventory);

  select system_mode,data_epoch into strict v_mode,v_epoch from pos.system_manifest where singleton;
  select coalesce(sum(queue_pending),0),coalesce(sum(queue_blocked),0)
    into v_queue,v_blocked from pos.sync_devices;
  select count(*) into v_unsynchronized from pos.sync_devices d
   where d.data_epoch<>v_epoch or d.queue_pending<>0 or d.queue_blocked<>0
      or d.status<>'online' or d.last_seen_at<now()-interval '2 minutes';
  select count(*) into v_incompatible from pos.sync_devices d
   where d.status<>'revoked' and coalesce(d.schema_version,0)<20260817014900;

  select jsonb_build_object(
    'sale_folios',coalesce((select jsonb_agg(s.folio order by s.folio) from pos.sales s where v_sales),'[]'::jsonb),
    'sale_operation_ids',coalesce((select jsonb_agg(s.operation_id order by s.operation_id) from pos.sales s where v_sales and s.operation_id is not null),'[]'::jsonb),
    'return_ids',coalesce((select jsonb_agg(r.id order by r.id) from pos.returns r where v_returns),'[]'::jsonb),
    'exchange_ids',coalesce((select jsonb_agg(e.id order by e.id) from pos.exchanges e where v_exchanges),'[]'::jsonb),
    'loan_ids',coalesce((select jsonb_agg(l.id order by l.id) from pos.loan_documents l where v_loans),'[]'::jsonb),
    'liquidation_ids',coalesce((select jsonb_agg(l.id order by l.id) from pos.liquidations l where v_commissions),'[]'::jsonb),
    'commission_adjustment_ids',coalesce((select jsonb_agg(a.operation_id order by a.operation_id) from pos.commission_adjustments a where v_commissions),'[]'::jsonb),
    'reclassification_ids',coalesce((select jsonb_agg(r.operation_id order by r.operation_id) from pos.reference_reclassifications r where v_reclassifications),'[]'::jsonb),
    'customer_ids',coalesce((select jsonb_agg(c.id order by c.id) from pos.clients c
      where v_customers and c.generic is not true and c.deleted_at is null
        and not exists(select 1 from pos.sales s where s.cliente_id=c.id and not v_sales)),'[]'::jsonb),
    'customer_referenced',coalesce((select jsonb_agg(c.id order by c.id) from pos.clients c
      where v_customers and c.generic is not true and c.deleted_at is null
        and exists(select 1 from pos.sales s where s.cliente_id=c.id and not v_sales)),'[]'::jsonb)
  ) into v_documents;

  -- H152: freeze the monetary dependents by their own identities. Exchange
  -- payments use the exchange folio, which differs from the original sale.
  select v_documents||jsonb_build_object(
    'payment_ids',coalesce(jsonb_agg(p.id order by p.id),'[]'::jsonb),
    'payment_hash',pos.point_zero_sha256(coalesce(jsonb_agg(to_jsonb(p) order by p.id),'[]'::jsonb))
  ) into v_documents
  from pos.sale_payments p
  where p.folio in(select jsonb_array_elements_text(v_documents->'sale_folios'))
    or (p.tipo='cambio' and exists(
      select 1 from pos.exchanges e
      where e.id in(select jsonb_array_elements_text(v_documents->'exchange_ids'))
        and e.folio=p.folio));

  v_documents:=v_documents||jsonb_build_object(
    'sale_state_restorations',coalesce((
      select jsonb_agg(jsonb_build_object(
        'folio',x.folio,'prior_state',x.prior_state,
        'evidence_count',x.evidence_count,'distinct_states',x.distinct_states)
        order by x.folio)
      from (
        select r.folio,min(r.prior_sale_state) as prior_state,
          count(*) filter(where r.prior_sale_state is not null) as evidence_count,
          count(distinct r.prior_sale_state) filter(where r.prior_sale_state is not null) as distinct_states
        from pos.returns r
        where v_returns and not v_sales
          and r.id in(select jsonb_array_elements_text(v_documents->'return_ids'))
        group by r.folio
      ) x
    ),'[]'::jsonb),
    'orphan_return_commits',coalesce((
      select jsonb_agg(jsonb_build_object(
        'commit_id',c.commit_id,'return_id',c.return_id,'folio',c.folio,
        'created_at',c.created_at) order by c.created_at,c.commit_id)
      from pos.return_commits c left join pos.returns r on r.id=c.return_id
      where (v_returns or v_orphan_return_evidence) and r.id is null
    ),'[]'::jsonb),
    'orphan_return_commit_ids',coalesce((
      select jsonb_agg(c.commit_id order by c.commit_id)
      from pos.return_commits c left join pos.returns r on r.id=c.return_id
      where v_orphan_return_evidence and r.id is null
    ),'[]'::jsonb),
    'orphan_return_ids',coalesce((
      select jsonb_agg(c.return_id order by c.commit_id)
      from pos.return_commits c left join pos.returns r on r.id=c.return_id
      where v_orphan_return_evidence and r.id is null
    ),'[]'::jsonb)
  );

  -- Líneas de inversión. Los préstamos están ausentes a propósito: no tocan stock.
  with sku_candidates as (
    select p.sku,min(p.id) as product_id,count(*) as n,
      count(*) filter(where p.record_model='v1') as v1_n
    from pos.products p where p.deleted_at is null and p.sku is not null group by p.sku
  ), doc_lines as (
    select 'sale'::text origin,r.folio ref,x.product_id raw_id,null::text sku,x.talla,
      x.qty::bigint delta
    from pos.stock_reservations r cross join lateral jsonb_to_recordset(r.lines)
      as x(product_id text,talla text,qty integer) where v_sales
    union all
    select 'sale',s.folio,i.product_id,i.sku,i.talla,i.qty::bigint
    from pos.sales s join pos.sale_items i on i.folio=s.folio
    where v_sales and s.estado not in ('Apartado','Cancelado')
      and not exists(select 1 from pos.stock_reservations r where r.folio=s.folio)
    union all
    select 'return',r.id,i.product_id,i.sku,i.talla,-i.qty::bigint
    from pos.returns r join pos.return_items i on i.return_id=r.id where v_returns
    union all
    select 'exchange',e.id,i.product_id,i.sku,i.talla,
      case when i.lado='devuelto' then -i.qty::bigint else i.qty::bigint end
    from pos.exchanges e join pos.exchange_items i on i.exchange_id=e.id where v_exchanges
    union all
    select 'reclassification',r.operation_id,r.source_product_id,null,p.size_code,r.quantity::bigint
    from pos.reference_reclassifications r join pos.products p on p.id=r.source_product_id where v_reclassifications
    union all
    select 'reclassification',r.operation_id,r.target_product_id,null,p.size_code,-r.quantity::bigint
    from pos.reference_reclassifications r join pos.products p on p.id=r.target_product_id where v_reclassifications
  ), resolved as (
    select d.*,p.id product_id,p.record_model,p.size_code,p.stock_quantity,p.stock,
      case
        when d.raw_id is not null and p.id is null then 'missing_product_id'
        when d.raw_id is null and coalesce(sc.n,0)>1 then 'identity_ambiguous'
        when d.raw_id is null and (coalesce(sc.n,0)=0 or coalesce(sc.v1_n,0)<>1) then 'identity_missing'
        when p.record_model='v2' and nullif(trim(coalesce(d.talla,'')),'') is null then 'size_missing'
        when p.record_model='v2' and d.talla<>p.size_code then 'size_mismatch'
        when p.record_model='v1' and (select count(*) from jsonb_array_elements(coalesce(p.stock,'[]'::jsonb)) z where z->>'talla'=d.talla)<>1 then 'size_ambiguous'
        else null end issue
    from doc_lines d left join sku_candidates sc on sc.sku=d.sku
    left join pos.products p on p.id=case when d.raw_id is not null then d.raw_id
      when sc.n=1 and sc.v1_n=1 then sc.product_id else null end
  ), deltas as (
    select product_id,talla,sum(delta)::bigint delta from resolved
    where issue is null group by product_id,talla having sum(delta)<>0
  ), targets as (
    select d.product_id,d.talla,p.record_model,d.delta,
      case when p.record_model='v2' then p.stock_quantity::bigint
        else (select (z->>'stock')::bigint from jsonb_array_elements(p.stock) z where z->>'talla'=d.talla) end current_stock
    from deltas d join pos.products p on p.id=d.product_id
  )
  select coalesce((select jsonb_agg(jsonb_build_object(
      'product_id',t.product_id,'talla',t.talla,'record_model',t.record_model,
      'current_stock',t.current_stock,'delta',t.delta,'target_stock',t.current_stock+t.delta)
      order by t.product_id,t.talla) from targets t),'[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object('origin',r.origin,'ref',r.ref,
      'sku',r.sku,'product_id',r.raw_id,'talla',r.talla,'code',r.issue)
      order by r.origin,r.ref) from resolved r where r.issue is not null),'[]'::jsonb)
  into v_stock,v_issues;

  if v_mode='production' then v_reasons:=v_reasons||jsonb_build_array('cleanup_production_locked'); end if;
  if v_queue<>0 or v_blocked<>0 or v_unsynchronized<>0 then
    v_reasons:=v_reasons||jsonb_build_array('cleanup_not_synchronized');
  end if;
  if v_incompatible<>0 then
    v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object(
      'code','client_schema_incompatible','devices',v_incompatible,
      'minimum_schema',20260817014900));
  end if;
  if v_inventory then v_reasons:=v_reasons||jsonb_build_array('inventory_products_requires_point_zero'); end if;
  if not (v_sales or v_returns or v_orphan_return_evidence or v_exchanges or v_loans or v_commissions or v_reclassifications or v_customers) then
    v_reasons:=v_reasons||jsonb_build_array('cleanup_empty_selection');
  end if;
  if jsonb_array_length(v_issues)>0 then v_reasons:=v_reasons||v_issues; end if;
  -- El saldo se reconstruye desde lo que SOBREVIVE. La evidencia incompleta de
  -- un documento seleccionado para borrado no participa en el saldo final.
  if pos.test_data_cleanup_affects_financials(jsonb_build_object('selection_normalized',v_normalized)) and not v_returns and exists(select 1 from pos.returns r where r.comisiones is null) then
    v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('code','commission_evidence_missing','document','return'));
  end if;
  if pos.test_data_cleanup_affects_financials(jsonb_build_object('selection_normalized',v_normalized)) and not v_sales and exists(select 1 from pos.sales s where s.comisiones is null) then
    v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('code','commission_evidence_missing','document','sale'));
  end if;
  if pos.test_data_cleanup_affects_financials(jsonb_build_object('selection_normalized',v_normalized)) and not v_sales and exists(select 1 from pos.sales s where s.estado='Cancelado'
      and jsonb_array_length(coalesce(s.comisiones,'[]'::jsonb))>0 and s.comisiones_revertidas is null) then
    v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('code','commission_evidence_missing','document','cancelled_sale'));
  end if;
  if pos.test_data_cleanup_affects_financials(jsonb_build_object('selection_normalized',v_normalized)) and not v_commissions and exists(select 1 from pos.commission_adjustments a
      where jsonb_typeof(a.detalle)<>'array' or exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(a.detalle)='array' then a.detalle else '[]'::jsonb end) j
        where nullif(j->>'seller_id','') is null or nullif(j->>'monto','') is null)) then
    v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('code','commission_evidence_missing','document','commission_adjustment'));
  end if;
  if exists(select 1 from jsonb_to_recordset(v_stock) x(target_stock bigint) where x.target_stock<0) then
    v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('code','negative_stock'));
  end if;
  if jsonb_array_length(v_documents->'customer_referenced')>0 then
    v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('code','customer_referenced',
      'ids',v_documents->'customer_referenced'));
  end if;

  v_counts:=jsonb_build_object(
    'ventas',jsonb_array_length(v_documents->'sale_folios'),
    'devoluciones',jsonb_array_length(v_documents->'return_ids'),
    'evidencias_huerfanas_devolucion',jsonb_array_length(v_documents->'orphan_return_commit_ids'),
    'cambios',jsonb_array_length(v_documents->'exchange_ids'),
    'prestamos',jsonb_array_length(v_documents->'loan_ids'),
    'comisiones',jsonb_array_length(v_documents->'liquidation_ids')+jsonb_array_length(v_documents->'commission_adjustment_ids'),
    'reclasificaciones',jsonb_array_length(v_documents->'reclassification_ids'),
    'clientes',jsonb_array_length(v_documents->'customer_ids'));
  if (v_sales or v_returns or v_orphan_return_evidence or v_exchanges or v_loans or v_commissions
      or v_reclassifications or v_customers)
     and (select coalesce(sum(value::bigint),0) from jsonb_each_text(v_counts))=0 then
    -- Es la causa accionable de esta selección. Se conserva el diagnóstico
    -- técnico restante, pero no se antepone una guarda de otro dominio.
    v_reasons:=jsonb_build_array('cleanup_no_matching_data')||v_reasons;
  end if;
  if v_returns and not v_sales and exists(
    select 1 from jsonb_to_recordset(v_documents->'sale_state_restorations')
      as x(folio text,prior_state text,evidence_count integer,distinct_states integer)
    where x.evidence_count=0 or x.distinct_states<>1
       or x.prior_state not in('Pagado','Entregado','Enviado')
  ) then
    v_reasons:=jsonb_build_array(jsonb_build_object(
      'code','return_state_evidence_missing',
      'folios',(select coalesce(jsonb_agg(x.folio order by x.folio),'[]'::jsonb)
        from jsonb_to_recordset(v_documents->'sale_state_restorations')
          as x(folio text,prior_state text,evidence_count integer,distinct_states integer)
        where x.evidence_count=0 or x.distinct_states<>1
           or x.prior_state not in('Pagado','Entregado','Enviado'))
    ))||v_reasons;
  end if;
  if v_returns and not v_orphan_return_evidence
     and jsonb_array_length(v_documents->'orphan_return_commits')>0 then
    v_reasons:=jsonb_build_array(jsonb_build_object(
      'code','orphan_return_evidence',
      'documents',v_documents->'orphan_return_commits'
    ))||v_reasons;
  end if;
  v_core:=jsonb_build_object('protocol_version',5,'minimum_client_protocol',5,
    'preset_requested',v_preset,'selection_requested',v_requested,
    'selection_normalized',v_normalized,'forced_dependencies',v_forced,
    'counts',v_counts,'documents',v_documents,'stock',v_stock,
    'blocked_reasons',v_reasons,'data_epoch',v_epoch,'system_mode',v_mode);
  v_hash:=pos.point_zero_sha256(v_core);
  return v_core||jsonb_build_object('ok',true,'plan_hash',v_hash,
    'executable',jsonb_array_length(v_reasons)=0,'queue_pending',v_queue,
    'active_locks',v_blocked,'unsynchronized_devices',v_unsynchronized,
    'incompatible_devices',v_incompatible);
end;
$function$

CREATE OR REPLACE FUNCTION pos.preview_test_data_cleanup(p_preset text DEFAULT 'operations'::text, p_selection jsonb DEFAULT '{}'::jsonb, p_client_protocol integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_plan jsonb;
begin
  if not pos.is_active_admin() or not pos.current_has_capability('settings.manage') then
    raise exception using errcode='42501',message='cleanup_requires_admin';
  end if;
  v_plan:=pos.test_data_cleanup_fleet_risk(pos.test_data_cleanup_plan(p_preset,p_selection));
  if coalesce(p_client_protocol,0)<(v_plan->>'minimum_client_protocol')::integer then
    return jsonb_set(jsonb_set(v_plan,'{executable}','false'::jsonb),'{blocked_reasons}',
      (v_plan->'blocked_reasons')||jsonb_build_array('minimum_client_protocol'));
  end if;
  return v_plan;
end;
$function$

CREATE OR REPLACE FUNCTION pos.execute_test_data_cleanup(p_cleanup_id text, p_preset text, p_selection jsonb, p_plan_hash text, p_backup_id uuid, p_confirmation text, p_client_protocol integer DEFAULT 2, p_client_build text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos', 'auth'
AS $function$
declare
  v_plan jsonb;v_backup pos.test_data_cleanup_backups%rowtype;
  v_prior pos.test_data_cleanup_operations%rowtype;v_epoch bigint;v_result jsonb;
  v_stock record;v_orphan record;v_orphan_deleted integer;
  v_idx integer;v_now timestamptz:=statement_timestamp();
begin
  if not pos.is_active_admin() or not pos.current_has_capability('settings.manage') then
    raise exception using errcode='42501',message='cleanup_requires_admin';
  end if;
  if nullif(trim(coalesce(p_cleanup_id,'')),'') is null then raise exception 'cleanup_invalid_id'; end if;
  if p_confirmation is distinct from 'LIMPIAR OPERACIONES' then raise exception 'cleanup_confirmation_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('pos.execute-test-data-cleanup',0));
  -- Serialize with legacy RPC writes and quarantine approval/reporting.
  perform pg_advisory_xact_lock(hashtextextended('pos.h149.recovery-fence',0));
  select * into v_prior from pos.test_data_cleanup_operations where cleanup_id=p_cleanup_id;
  if found then return v_prior.result||jsonb_build_object('idempotent',true); end if;
  v_plan:=pos.preview_test_data_cleanup(p_preset,p_selection,p_client_protocol);
  if v_plan->>'system_mode'='production' then raise exception 'cleanup_production_locked'; end if;
  if not coalesce((v_plan->>'executable')::boolean,false) then raise exception 'cleanup_plan_not_executable'; end if;
  if v_plan->>'plan_hash'<>coalesce(p_plan_hash,'') then raise exception 'cleanup_preview_changed'; end if;
  select * into v_backup from pos.test_data_cleanup_backups where backup_id=p_backup_id and created_by=auth.uid();
  if not found or v_backup.plan_hash<>p_plan_hash or v_backup.data_epoch<>(v_plan->>'data_epoch')::bigint
     or v_backup.selection_normalized<>v_plan->'selection_normalized'
     or v_backup.payload_hash<>pos.point_zero_sha256(v_backup.payload) then
    raise exception 'cleanup_backup_mismatch';
  end if;
  insert into pos.test_data_cleanup_operations(cleanup_id,backup_id,status,actor_user_id,
    actor_email,device_id,client_build,protocol_version,data_epoch_before,preset,
    selection_normalized,plan_hash)
  values(p_cleanup_id,p_backup_id,'running',auth.uid(),auth.jwt()->>'email',p_device_id,
    p_client_build,p_client_protocol,(v_plan->>'data_epoch')::bigint,p_preset,
    v_plan->'selection_normalized',p_plan_hash);

  -- Inventario primero, bajo el mismo lock/transacción. Nunca se recorta a cero.
  for v_stock in select * from jsonb_to_recordset(v_plan->'stock') as x(
    product_id text,talla text,record_model text,current_stock bigint,delta bigint,target_stock bigint)
  loop
    if v_stock.target_stock<0 then raise exception 'negative_stock'; end if;
    if v_stock.record_model='v2' then
      update pos.products set stock_quantity=v_stock.target_stock::integer,
        sync_base_version=null,sync_device_id='cleanup:'||p_cleanup_id
      where id=v_stock.product_id and record_model='v2' and stock_quantity=v_stock.current_stock;
      if not found then raise exception 'cleanup_preview_changed'; end if;
    else
      select (z.ordinality-1)::integer into strict v_idx from pos.products p
        cross join lateral jsonb_array_elements(p.stock) with ordinality z(value,ordinality)
        where p.id=v_stock.product_id and p.record_model='v1'
          and z.value->>'talla'=v_stock.talla and (z.value->>'stock')::bigint=v_stock.current_stock;
      update pos.products set stock=jsonb_set(stock,array[v_idx::text,'stock'],to_jsonb(v_stock.target_stock),false),
        sync_base_version=null,sync_device_id='cleanup:'||p_cleanup_id where id=v_stock.product_id;
      if not found then raise exception 'cleanup_preview_changed'; end if;
    end if;
  end loop;

  insert into pos.purged_documents(kind,identity,purge_id)
    select 'sale',x,p_cleanup_id from jsonb_array_elements_text(v_plan->'documents'->'sale_operation_ids') x
    on conflict(kind,identity) do nothing;
  insert into pos.purged_documents(kind,identity,purge_id)
    select 'return',x,p_cleanup_id from (
      select jsonb_array_elements_text(v_plan->'documents'->'return_ids') x
      union
      select jsonb_array_elements_text(v_plan->'documents'->'orphan_return_ids') x
    ) selected_returns
    on conflict(kind,identity) do nothing;
  insert into pos.purged_documents(kind,identity,purge_id)
    select 'exchange',x,p_cleanup_id from jsonb_array_elements_text(v_plan->'documents'->'exchange_ids') x
    on conflict(kind,identity) do nothing;
  insert into pos.purged_documents(kind,identity,purge_id)
    select 'loan',x,p_cleanup_id from jsonb_array_elements_text(v_plan->'documents'->'loan_ids') x
    on conflict(kind,identity) do nothing;

  -- Hijos, evidencias transaccionales y kardex se eliminan sólo por identidad.
  delete from pos.physical_card_redemptions c where c.sale_folio in(select jsonb_array_elements_text(v_plan->'documents'->'sale_folios'));
  -- H123: evidencia técnica exacta; no toca stock, dinero ni documentos.
  for v_orphan in
    select c.commit_id from pos.return_commits c
    where c.commit_id in(select jsonb_array_elements_text(v_plan->'documents'->'orphan_return_commit_ids'))
    order by c.commit_id
  loop
    perform pg_advisory_xact_lock(hashtext(v_orphan.commit_id));
  end loop;
  if exists(
    select 1
    from jsonb_array_elements_text(v_plan->'documents'->'orphan_return_commit_ids') x(commit_id)
    left join pos.return_commits c on c.commit_id=x.commit_id
    left join pos.returns r on r.id=c.return_id
    where c.commit_id is null or r.id is not null
  ) then
    raise exception 'cleanup_preview_changed';
  end if;
  delete from pos.return_commits c
  where c.commit_id in(select jsonb_array_elements_text(v_plan->'documents'->'orphan_return_commit_ids'))
    and not exists(select 1 from pos.returns r where r.id=c.return_id);
  get diagnostics v_orphan_deleted = row_count;
  if v_orphan_deleted<>jsonb_array_length(v_plan->'documents'->'orphan_return_commit_ids') then
    raise exception 'cleanup_preview_changed';
  end if;

  -- H120: restore retained sale state from exact forward evidence.
  update pos.sales s set estado=x.prior_state
  from jsonb_to_recordset(v_plan->'documents'->'sale_state_restorations')
    as x(folio text,prior_state text,evidence_count integer,distinct_states integer)
  where s.folio=x.folio
    and s.folio not in(select jsonb_array_elements_text(v_plan->'documents'->'sale_folios'));
  delete from pos.return_commits c where c.return_id in(select jsonb_array_elements_text(v_plan->'documents'->'return_ids'));
  delete from pos.exchange_commits c where c.exchange_id in(select jsonb_array_elements_text(v_plan->'documents'->'exchange_ids'));
  delete from pos.layaway_liquidation_commits c where c.folio in(select jsonb_array_elements_text(v_plan->'documents'->'sale_folios'));
  delete from pos.sale_commits c where c.folio in(select jsonb_array_elements_text(v_plan->'documents'->'sale_folios'));
  delete from pos.stock_reservations r where r.folio in(select jsonb_array_elements_text(v_plan->'documents'->'sale_folios'));
  delete from pos.movements m where m.ref in(
    select jsonb_array_elements_text(v_plan->'documents'->'sale_folios') union

    select e.folio from pos.exchanges e where e.id in(select jsonb_array_elements_text(v_plan->'documents'->'exchange_ids')))
    or m.return_id in(select jsonb_array_elements_text(v_plan->'documents'->'return_ids'))
    or (m.return_id is null and m.tipo='Devolución' and m.ref in(
      select r.folio from pos.returns r where r.id in(select jsonb_array_elements_text(v_plan->'documents'->'return_ids'))))
    or m.operation_id in(select jsonb_array_elements_text(v_plan->'documents'->'reclassification_ids'));
  delete from pos.sale_payments p where p.id in(select jsonb_array_elements_text(v_plan->'documents'->'payment_ids'));
  delete from pos.return_items i where i.return_id in(select jsonb_array_elements_text(v_plan->'documents'->'return_ids'));
  delete from pos.exchange_items i where i.exchange_id in(select jsonb_array_elements_text(v_plan->'documents'->'exchange_ids'));
  delete from pos.sale_items i where i.folio in(select jsonb_array_elements_text(v_plan->'documents'->'sale_folios'));
  delete from pos.returns r where r.id in(select jsonb_array_elements_text(v_plan->'documents'->'return_ids'));
  delete from pos.exchanges e where e.id in(select jsonb_array_elements_text(v_plan->'documents'->'exchange_ids'));
  delete from pos.sales s where s.folio in(select jsonb_array_elements_text(v_plan->'documents'->'sale_folios'));
  delete from pos.loan_documents l where l.id in(select jsonb_array_elements_text(v_plan->'documents'->'loan_ids'));
  delete from pos.liquidations l where l.id in(select jsonb_array_elements_text(v_plan->'documents'->'liquidation_ids'));
  delete from pos.commission_adjustments a where a.operation_id::text in(select jsonb_array_elements_text(v_plan->'documents'->'commission_adjustment_ids'));
  update pos.reference_reclassifications set reversed_by=null,reversal_of=null
    where operation_id in(select jsonb_array_elements_text(v_plan->'documents'->'reclassification_ids'));
  delete from pos.reference_reclassifications r where r.operation_id in(select jsonb_array_elements_text(v_plan->'documents'->'reclassification_ids'));
  update pos.clients c set deleted_at=v_now,sync_base_version=null,sync_device_id='cleanup:'||p_cleanup_id
    where c.id in(select jsonb_array_elements_text(v_plan->'documents'->'customer_ids'));

  -- H-122: préstamos, reclasificaciones y clientes no cambian esta autoridad.
  if pos.test_data_cleanup_affects_financials(v_plan) then
  -- Autoridad H-69: saldo derivado de documentos CONGELADOS conservados.
  with generated as (
    select j->>'sellerId' seller_id,sum(coalesce((j->>'monto')::numeric,0)) amount
      from pos.sales s cross join lateral jsonb_array_elements(coalesce(s.comisiones,'[]'::jsonb)) j group by j->>'sellerId'
    union all select e.vendedor_id,sum(case when e.comision_revertida is null then coalesce(e.comision_monto,0) else 0 end) from pos.exchanges e group by e.vendedor_id
    union all select j->>'sellerId',-sum(coalesce((j->>'monto')::numeric,0)) from pos.returns r cross join lateral jsonb_array_elements(coalesce(r.comisiones,'[]'::jsonb)) j group by j->>'sellerId'
    union all select j->>'sellerId',-sum(coalesce((j->>'monto')::numeric,0)) from pos.sales s cross join lateral jsonb_array_elements(coalesce(s.comisiones_revertidas,'[]'::jsonb)) j where s.estado='Cancelado' group by j->>'sellerId'
    union all select j->>'seller_id',sum(coalesce((j->>'monto')::numeric,0)) from pos.commission_adjustments a cross join lateral jsonb_array_elements(a.detalle) j group by j->>'seller_id'
    union all select l.seller_id,-sum(l.monto) from pos.liquidations l where coalesce(l.tipo,'liquidacion')<>'ajuste' group by l.seller_id
  ), totals as (select seller_id,sum(amount) amount from generated where seller_id is not null group by seller_id)
  update pos.sellers s set comision_acum=coalesce(t.amount,0),sync_base_version=null,
    sync_device_id='cleanup:'||p_cleanup_id from (select s2.id,coalesce(t2.amount,0) amount
      from pos.sellers s2 left join totals t2 on t2.seller_id=s2.id) t where s.id=t.id;

  end if;

  -- H-122: sólo borrar ventas cambia ventas_mes/ventas_num.
  if coalesce((v_plan->'selection_normalized'->>'sales')::boolean,false) then
  with sale_volume as (
    select seller_id,sum(total/parts)::numeric amount,count(*)::integer documents from (
      select jsonb_array_elements_text(s.vendedores) seller_id,s.total,
        case when jsonb_array_length(s.vendedores)>0 then jsonb_array_length(s.vendedores) else 1 end parts
      from pos.sales s where s.estado<>'Cancelado' and jsonb_typeof(s.vendedores)='array') x
    group by seller_id)
  update pos.sellers s set ventas_mes=coalesce(v.amount,0),ventas_num=coalesce(v.documents,0),
    sync_base_version=null,sync_device_id='cleanup:'||p_cleanup_id
    from (select s2.id,coalesce(x.amount,0) amount,coalesce(x.documents,0) documents
      from pos.sellers s2 left join sale_volume x on x.seller_id=s2.id) v where s.id=v.id;
  end if;

  update pos.system_manifest set data_epoch=data_epoch+1,
    sync_protocol_min=greatest(sync_protocol_min,2),
    sync_protocol_current=greatest(sync_protocol_current,2),
    schema_version=case when schema_version<20260817014900 then 20260817014900 else schema_version end,
    updated_at=now() where singleton returning data_epoch into v_epoch;
  -- Cliente anterior al protocolo 2 falla cerrado y debe rebootstrap, nunca purga total.
  update pos.sync_devices set status='must_rebootstrap' where device_id is not null and status <> 'revoked';
  perform pos.bump_sync_domain('products','selective-cleanup:'||p_cleanup_id);
  perform pos.bump_sync_domain('clients','selective-cleanup:'||p_cleanup_id);
  perform pos.bump_sync_domain('sellers','selective-cleanup:'||p_cleanup_id);
  perform pos.bump_sync_domain('sales','selective-cleanup:'||p_cleanup_id);
  perform pos.bump_sync_domain('movements','selective-cleanup:'||p_cleanup_id);

  -- H150 follow-up: retire confirmed rows before fencing their archived retry.
  -- The same exclusive lock and transaction cover both stages; no replay gap.
  -- Rejection is atomic with cleanup, and retains the forensic backup.
  update pos.sync_quarantine_cases q set status='rejected',
    discarded_by_cleanup=p_cleanup_id, decision_by=auth.uid(),decision_at=v_now,
    decision_note='Descartada con la limpieza de datos de prueba',updated_at=v_now
  from jsonb_array_elements(coalesce(v_plan->'quarantine_discard','[]'::jsonb)) x
  where q.device_id=x->>'device_id' and q.operation_id=x->>'operation_id'
    and q.remote_epoch=(x->>'remote_epoch')::bigint and q.payload_hash=x->>'payload_hash'
    and q.status in ('pending_review','failed') and q.discarded_by_cleanup is null;
  if (select count(*) from pos.sync_quarantine_cases where discarded_by_cleanup=p_cleanup_id)
    <>jsonb_array_length(coalesce(v_plan->'quarantine_discard','[]'::jsonb)) then
    raise exception 'cleanup_preview_changed';
  end if;

  v_result:=jsonb_build_object('ok',true,'status','completed','cleanup_id',p_cleanup_id,
    'backup_id',p_backup_id,'protocol_version',5,'minimum_client_protocol',5,
    'preset',p_preset,'selection_normalized',v_plan->'selection_normalized',
    'forced_dependencies',v_plan->'forced_dependencies','plan_hash',p_plan_hash,
    'data_epoch',v_epoch,'purged_at',v_now,'counts',v_plan->'counts',
    'identities',v_plan->'documents','stock',v_plan->'stock',
    'quarantine_discard',coalesce(v_plan->'quarantine_discard','[]'::jsonb),
    'sale_states',v_plan->'documents'->'sale_state_restorations');
  insert into pos.selective_cleanup_events(cleanup_id,protocol_version,minimum_client_protocol,
    preset,selection_normalized,plan_hash,data_epoch,purged_at,identities)
  values(p_cleanup_id,5,5,p_preset,v_plan->'selection_normalized',p_plan_hash,v_epoch,v_now,v_plan->'documents');
  -- `test_data_purges` se conserva como auditoría H-68, pero NO recibe este
  -- evento: un cliente antiguo lo leería como purga total. La evidencia de esta
  -- operación vive en selective_cleanup_events y en las dos tablas de auditoría.
  update pos.test_data_cleanup_operations set status='completed',completed_at=now(),
    data_epoch_after=v_epoch,result=v_result where cleanup_id=p_cleanup_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.create_test_data_cleanup_backup(p_preset text, p_selection jsonb, p_plan_hash text, p_client_protocol integer DEFAULT 2, p_client_build text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos', 'auth'
AS $function$
declare v_plan jsonb;v_payload jsonb;v_id uuid;v_payload_hash text;v_document jsonb;
begin
  v_plan:=pos.preview_test_data_cleanup(p_preset,p_selection,p_client_protocol);
  if not coalesce((v_plan->>'executable')::boolean,false) then raise exception 'cleanup_plan_not_executable'; end if;
  if v_plan->>'plan_hash'<>coalesce(p_plan_hash,'') then raise exception 'cleanup_preview_changed'; end if;
  v_payload:=pos.test_data_cleanup_payload(v_plan);
  v_payload_hash:=pos.point_zero_sha256(v_payload);
  insert into pos.test_data_cleanup_backups(created_by,actor_email,device_id,client_build,
    protocol_version,data_epoch,preset,selection_normalized,plan_hash,payload_hash,payload)
  values(auth.uid(),auth.jwt()->>'email',p_device_id,p_client_build,p_client_protocol,
    (v_plan->>'data_epoch')::bigint,p_preset,v_plan->'selection_normalized',p_plan_hash,v_payload_hash,v_payload)
  returning backup_id into v_id;
  v_document:=jsonb_build_object('format','balam-selective-cleanup-backup-v2','backup_id',v_id,
    'created_at',statement_timestamp(),'user',auth.jwt()->>'email','protocol_version',p_client_protocol,
    'data_epoch',v_plan->'data_epoch','preset',p_preset,'selection_normalized',v_plan->'selection_normalized',
    'plan_hash',p_plan_hash,'payload_hash',v_payload_hash,'payload',v_payload);
  return jsonb_build_object('ok',true,'backup_id',v_id,'plan_hash',p_plan_hash,
    'payload_hash',v_payload_hash,'document',v_document);
end;
$function$

CREATE OR REPLACE FUNCTION pos.test_data_cleanup_receipt(p_cleanup_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_row pos.test_data_cleanup_operations%rowtype;
begin
  if not pos.is_active_admin() or not pos.current_has_capability('settings.manage') then
    raise exception using errcode='42501',message='cleanup_requires_admin';
  end if;
  select * into strict v_row from pos.test_data_cleanup_operations where cleanup_id=p_cleanup_id;
  return jsonb_build_object('format','balam-selective-cleanup-receipt-v2','cleanup_id',v_row.cleanup_id,
    'backup_id',v_row.backup_id,'status',v_row.status,'started_at',v_row.started_at,
    'completed_at',v_row.completed_at,'plan_hash',v_row.plan_hash,'result',v_row.result);
end;
$function$

CREATE OR REPLACE FUNCTION pos.delete_products_checked_v2(p_operation_id uuid, p_scope text, p_reference_family_id uuid, p_targets jsonb, p_device_id text, p_protocol_version integer, p_data_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_ids text[];
  v_count integer;
  v_hash text;
  v_result jsonb;
begin
  perform pos.assert_device_recovery_write(p_device_id,array[p_operation_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  perform pos.require_current_capability('inventory.delete');
  perform pos.assert_sync_write_context(p_protocol_version,p_data_epoch);
  if p_operation_id is null or p_scope is null or p_scope not in ('reference','family')
     or jsonb_typeof(p_targets) <> 'array' or jsonb_array_length(p_targets)=0
     or nullif(trim(coalesce(p_device_id,'')),'') is null then
    raise exception 'INVALID_INVENTORY_DELETE_SCOPE' using errcode='22023';
  end if;

  select array_agg(t.id order by t.id),count(*) into v_ids,v_count
  from (
    select nullif(trim(x->>'id'),'') id
    from jsonb_array_elements(p_targets) x
  ) t;
  if v_ids is null or array_position(v_ids,null) is not null
     or v_count <> (select count(distinct x->>'id') from jsonb_array_elements(p_targets) x)
     or exists(select 1 from jsonb_array_elements(p_targets) x
               where coalesce(x->>'baseVersion',x->>'base_version') is null) then
    raise exception 'INVALID_INVENTORY_DELETE_TARGETS' using errcode='22023';
  end if;

  v_hash := md5(jsonb_build_array(p_scope,p_reference_family_id,p_targets,p_device_id,
                                   p_protocol_version,p_data_epoch)::text);
  perform pg_advisory_xact_lock(hashtext(coalesce(p_reference_family_id::text,p_operation_id::text)));
  select result into v_result from pos.capability_operation_audit
   where operation_id=p_operation_id and capability_key='inventory.delete' and payload_hash=v_hash;
  if found then return v_result; end if;
  if exists(select 1 from pos.capability_operation_audit where operation_id=p_operation_id) then
    raise exception 'INVENTORY_OPERATION_CONFLICT' using errcode='40001';
  end if;

  perform 1 from pos.products p where p.id=any(v_ids) for update;
  if (select count(*) from pos.products p where p.id=any(v_ids) and p.deleted_at is null) <> v_count then
    raise exception 'PRODUCT_NOT_FOUND' using errcode='P0002';
  end if;
  if exists(
    select 1 from pos.products p
    join jsonb_array_elements(p_targets) x on x->>'id'=p.id
    where p.sync_version <> coalesce(x->>'baseVersion',x->>'base_version')::bigint
  ) then raise exception 'PRODUCT_VERSION_CONFLICT' using errcode='40001'; end if;

  if p_scope='reference' then
    if v_count<>1 or (p_reference_family_id is not null and exists(
      select 1 from pos.products p where p.id=any(v_ids)
       and p.reference_family_id is distinct from p_reference_family_id
    )) then raise exception 'REFERENCE_FAMILY_SCOPE_MISMATCH' using errcode='22023'; end if;
  else
    if p_reference_family_id is null
       or exists(select 1 from pos.products p where p.id=any(v_ids)
                 and (p.record_model<>'v2' or p.reference_family_id is distinct from p_reference_family_id))
       or exists(select 1 from pos.products p where p.deleted_at is null
                 and p.record_model='v2' and p.reference_family_id=p_reference_family_id
                 and not(p.id=any(v_ids))) then
      raise exception 'REFERENCE_FAMILY_SCOPE_MISMATCH' using errcode='22023';
    end if;
  end if;

  if exists(
    select 1 from pos.sales s join pos.sale_items i on i.folio=s.folio
     where i.product_id=any(v_ids) and s.estado='Apartado'
  ) then raise exception 'PRODUCT_ACTIVE_LAYAWAY' using errcode='23514'; end if;

  if exists(
    select 1 from pos.loan_documents l
    cross join lateral jsonb_array_elements(coalesce(l.document->'lineas','[]'::jsonb)) line
    where l.deleted_at is null and l.state='pendiente'
      and coalesce(line->>'productId',line->>'product_id')=any(v_ids)
      and greatest(0,coalesce((line->>'qty')::integer,0)-coalesce((line->>'devueltas')::integer,0))>0
  ) then raise exception 'PRODUCT_OPEN_LOAN' using errcode='23514'; end if;

  -- La identidad posventa es line_id/source_sale_line_id (H-94), nunca SKU.
  if exists(
    with eligible_sales as (
      select s.folio from pos.sales s
       where s.estado in('Pagado','Entregado','Enviado','Devolución parcial')
         and (s.return_limit_days is null or s.return_expires_at is null or s.return_expires_at>=current_date)
    ), supplied as (
      select si.folio,si.line_id,si.product_id,si.qty
        from pos.sale_items si join eligible_sales s on s.folio=si.folio
       where si.product_id=any(v_ids)
      union all
      select e.origen_folio,ei.line_id,ei.product_id,ei.qty
        from pos.exchange_items ei join pos.exchanges e on e.id=ei.exchange_id
        join eligible_sales s on s.folio=e.origen_folio
       where ei.lado='entregado' and ei.product_id=any(v_ids)
    )
    select 1 from supplied src
     where src.line_id is not null and src.qty >
       coalesce((select sum(ri.qty) from pos.return_items ri
                 where ri.source_sale_line_id=src.line_id and ri.product_id=src.product_id),0)
       + coalesce((select sum(ei.qty) from pos.exchange_items ei
                   where ei.lado='devuelto' and ei.source_sale_line_id=src.line_id
                     and ei.product_id=src.product_id),0)
  ) then raise exception 'PRODUCT_RETURNABLE_HISTORY' using errcode='23514'; end if;

  with requested as (
    select x->>'id' id,coalesce(x->>'baseVersion',x->>'base_version')::bigint base_version
      from jsonb_array_elements(p_targets) x
  ), updated as (
    update pos.products p set deleted_at=now(),sync_base_version=requested.base_version,
      sync_device_id=p_device_id from requested
     where p.id=requested.id and p.deleted_at is null returning p.*
  ) select jsonb_build_object('ok',true,'scope',p_scope,
      'rows',coalesce(jsonb_agg(to_jsonb(updated) order by updated.id),'[]'::jsonb))
    into v_result from updated;
  insert into pos.capability_operation_audit(
    operation_id,capability_key,actor_user_id,subject_key,payload_hash,result
  ) values(p_operation_id,'inventory.delete',v_actor,
           coalesce(p_reference_family_id::text,v_ids[1]),v_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.test_data_cleanup_fleet_risk(p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare
  v_plan jsonb := coalesce(p_plan, '{}'::jsonb);
  v_selection jsonb := coalesce(p_plan->'selection_normalized', '{}'::jsonb);
  v_reasons jsonb;
  v_devices jsonb := '[]'::jsonb;
  v_summary jsonb := jsonb_build_object(
    'ready', 0, 'compatible_offline', 0, 'update_on_return', 0,
    'attention', 0, 'retired', 0, 'unsafe_legacy', 0,
    'historical_incidents', 0
  );
  v_domains text[];
  v_manifest_epoch bigint;
  v_device record;
  v_all_activity jsonb;
  v_selected_activity jsonb;
  v_current_activity jsonb;
  v_historical_activity jsonb;
  v_quarantine jsonb;
  v_discard jsonb := '[]'::jsonb;
  v_projected_count integer;
  v_current_pending integer;
  v_unknown integer;
  v_conflicts integer;
  v_historical_count integer;
  v_recent boolean;
  v_fenceable boolean;
  v_requires_update boolean;
  v_state text;
  v_blocking boolean;
  v_reason text;
  v_core jsonb;
begin
  if jsonb_typeof(v_plan) <> 'object' then
    raise exception 'cleanup_invalid_plan' using errcode = '22023';
  end if;

  select data_epoch into strict v_manifest_epoch
  from pos.system_manifest where singleton;

  v_domains := array_remove(array[
    case when coalesce((v_selection->>'sales')::boolean, false) then 'sales' end,
    case when coalesce((v_selection->>'sales')::boolean, false) then 'payments' end,
    case when coalesce((v_selection->>'sales')::boolean, false)
           or coalesce((v_selection->>'returns')::boolean, false)
           or coalesce((v_selection->>'orphan_return_evidence')::boolean, false) then 'returns' end,
    case when coalesce((v_selection->>'sales')::boolean, false)
           or coalesce((v_selection->>'exchanges')::boolean, false) then 'exchanges' end,
    case when coalesce((v_selection->>'loans')::boolean, false) then 'loans' end,
    case when coalesce((v_selection->>'commissions')::boolean, false) then 'liquidations' end,
    case when coalesce((v_selection->>'reclassifications')::boolean, false) then 'products' end,
    case when coalesce((v_selection->>'customers')::boolean, false) then 'clients' end
  ], null);

  select coalesce(jsonb_agg(e.value), '[]'::jsonb) into v_reasons
  from jsonb_array_elements(coalesce(v_plan->'blocked_reasons', '[]'::jsonb)) e(value)
  where not (jsonb_typeof(e.value) = 'string'
             and e.value #>> '{}' = 'cleanup_not_synchronized')
    and not (jsonb_typeof(e.value) = 'object'
             and e.value->>'code' = 'client_schema_incompatible');

  for v_device in
    select * from pos.sync_devices order by coalesce(display_name, device_id), device_id
  loop
    select count(*),
      coalesce(jsonb_agg(jsonb_build_object(
        'operation_id', a.operation_id,
        'operation_type', a.operation_type,
        'domain', a.domain,
        'reference', a.reference,
        'summary', a.summary,
        'status', a.status,
        'diagnostic', to_jsonb(a)->'diagnostic',
        'updated_at', a.updated_at
      ) order by a.updated_at desc), '[]'::jsonb),
      coalesce(jsonb_agg(jsonb_build_object(
        'operation_id', a.operation_id,
        'operation_type', a.operation_type,
        'domain', a.domain,
        'reference', a.reference,
        'summary', a.summary,
        'status', a.status,
        'diagnostic', to_jsonb(a)->'diagnostic',
        'updated_at', a.updated_at
      ) order by a.updated_at desc) filter (where a.domain = any(v_domains)), '[]'::jsonb)
    into v_projected_count, v_all_activity, v_selected_activity
    from pos.sync_activity a
    where a.device_id = v_device.device_id
      and a.status in ('pending', 'retrying', 'blocked', 'quarantined');

    -- queue_pending=0 es una declaraciÃ³n autoritativa de que STORE no tiene
    -- payload ejecutable. Las proyecciones activas sobreviven como evidencia
    -- administrativa, pero no pueden reproducirse desde sync_activity.
    if coalesce(v_device.queue_pending, 0) = 0 then
      v_current_activity := '[]'::jsonb;
      v_historical_activity := v_selected_activity;
      v_current_pending := 0;
      v_unknown := 0;
    else
      v_current_activity := v_selected_activity;
      v_historical_activity := '[]'::jsonb;
      v_current_pending := least(coalesce(v_device.queue_pending, 0), v_projected_count);
      -- Sin una correspondencia 1:1 no se adivina quÃ© proyecciÃ³n es actual.
      v_unknown := case
        when v_projected_count = coalesce(v_device.queue_pending, 0) then 0
        else coalesce(v_device.queue_pending, 0)
      end;
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
      'operation_id', q.operation_id,
      'operation_type', q.operation_type,
      'domain', q.domain,
      'reference', q.reference,
      'summary', q.summary,
      'status', q.status,
      'updated_at', q.updated_at
    ) order by q.updated_at desc), '[]'::jsonb)
    into v_quarantine
    from pos.sync_quarantine_cases q
    where q.device_id = v_device.device_id
      and (q.status in ('approved', 'delivered')
        or (q.status in ('pending_review','failed') and not coalesce((q.operation_type not in ('referenceReclassification','commissionSettle','commissionClose')
            or (jsonb_typeof(q.payload_summary->'operationIds')='array'
              and jsonb_array_length(q.payload_summary->'operationIds')>0)),false)))
      and q.domain = any(v_domains);

    -- Archived, unapproved intents cannot execute. Their explicit rejection
    -- belongs to this plan, including product edits that affect retained stock.
    if v_device.status <> 'revoked' then
      v_discard := v_discard || coalesce((select jsonb_agg(to_jsonb(q)
        || jsonb_build_object('device_name',coalesce(nullif(v_device.display_name,''),
          'Equipo '||upper(right(v_device.device_id,6))))
        order by q.operation_id,q.remote_epoch)
        from pos.sync_quarantine_cases q where q.device_id=v_device.device_id
          and q.status in ('pending_review','failed') and q.discarded_by_cleanup is null
          and q.domain=any(v_domains) and (q.operation_type not in ('referenceReclassification','commissionSettle','commissionClose')
            or (jsonb_typeof(q.payload_summary->'operationIds')='array'
              and jsonb_array_length(q.payload_summary->'operationIds')>0))), '[]'::jsonb);
    end if;

    v_conflicts := jsonb_array_length(v_current_activity)
      + jsonb_array_length(v_quarantine);
    v_historical_count := jsonb_array_length(v_historical_activity);
    v_recent := v_device.last_seen_at >= statement_timestamp() - interval '2 minutes';
    v_fenceable := coalesce(v_device.protocol_version, 0) >= 1
      and coalesce(v_device.schema_version, 0) >= 20260806011500;
    v_requires_update := coalesce(v_device.protocol_version, 0) < 2
      or coalesce(v_device.schema_version, 0) < 20260820016500
      or coalesce(v_device.data_epoch, 0) <> v_manifest_epoch
      or v_device.status in ('must_rebootstrap', 'quarantined');
    v_blocking := false;
    v_reason := null;

    if v_device.status = 'revoked' then
      v_state := 'retired';
    elsif not v_fenceable then
      v_state := 'unsafe_legacy';
      v_blocking := true;
      v_reason := 'client_cannot_be_fenced';
    elsif v_conflicts > 0 then
      v_state := 'attention';
      v_blocking := true;
      v_reason := 'pending_operation_intersects_cleanup';
    elsif v_unknown > 0 then
      v_state := 'attention';
      v_blocking := true;
      v_reason := 'pending_scope_unknown';
    elsif v_requires_update then
      v_state := 'update_on_return';
    elsif not v_recent or v_device.status = 'offline' then
      v_state := 'compatible_offline';
    else
      v_state := 'ready';
    end if;

    if v_blocking then
      v_reasons := v_reasons || jsonb_build_array(jsonb_build_object(
        'code', v_reason,
        'device_id', v_device.device_id,
        'device_name', coalesce(nullif(v_device.display_name, ''),
          'Equipo ' || upper(right(v_device.device_id, 6))),
        'operations', v_current_activity || v_quarantine,
        'unknown_operations', v_unknown
      ));
    end if;

    v_summary := jsonb_set(v_summary, array[v_state],
      to_jsonb(coalesce((v_summary->>v_state)::integer, 0) + 1));
    v_summary := jsonb_set(v_summary, '{historical_incidents}',
      to_jsonb(coalesce((v_summary->>'historical_incidents')::integer, 0)
        + v_historical_count));
    v_devices := v_devices || jsonb_build_array(jsonb_build_object(
      'device_id', v_device.device_id,
      'display_name', coalesce(nullif(v_device.display_name, ''),
        'Equipo ' || upper(right(v_device.device_id, 6))),
      'state', v_state,
      'blocking', v_blocking,
      'reason', v_reason,
      'known_pending', v_current_pending,
      'current_pending', coalesce(v_device.queue_pending, 0),
      'current_operations', v_current_activity,
      'unknown_pending', v_unknown,
      'conflicts', v_current_activity || v_quarantine,
      'replayable_incidents', v_quarantine,
      'historical_incident_count', v_historical_count,
      'historical_incidents', v_historical_activity,
      'historical_projection_count', case when coalesce(v_device.queue_pending, 0) = 0
        then v_projected_count else 0 end,
      'last_seen_at', v_device.last_seen_at,
      'protocol_version', v_device.protocol_version,
      'schema_version', v_device.schema_version,
      'data_epoch', v_device.data_epoch,
      'status', v_device.status,
      'fenceable', v_fenceable
    ));
  end loop;

  if jsonb_array_length(v_discard)>0 then
    select coalesce(jsonb_agg(e),'[]'::jsonb) into v_reasons
    from jsonb_array_elements(v_reasons) e where e <> '"cleanup_no_matching_data"'::jsonb;
  end if;
  v_core := (v_plan - 'ok' - 'plan_hash' - 'executable' - 'queue_pending'
    - 'active_locks' - 'unsynchronized_devices' - 'incompatible_devices')
    || jsonb_build_object(
      'protocol_version', 6,
      'minimum_client_protocol', case when jsonb_array_length(v_discard)>0 then 6 else 5 end,
      'quarantine_discard',v_discard,
      'counts',coalesce(v_plan->'counts','{}'::jsonb)||jsonb_build_object('operaciones_archivadas',jsonb_array_length(v_discard)),
      'blocked_reasons', v_reasons,
      'fleet', jsonb_build_object('summary', v_summary, 'devices', v_devices)
    );
  return v_core || jsonb_build_object(
    'ok', true,
    'plan_hash', pos.test_data_cleanup_plan_hash(v_core),
    'executable', jsonb_array_length(v_reasons) = 0,
    'queue_pending', coalesce((select sum(queue_pending) from pos.sync_devices
      where status <> 'revoked'), 0),
    'active_locks', coalesce((select sum(queue_blocked) from pos.sync_devices
      where status <> 'revoked'), 0),
    'unsynchronized_devices', coalesce((v_summary->>'attention')::integer, 0)
      + coalesce((v_summary->>'unsafe_legacy')::integer, 0),
    'incompatible_devices', coalesce((v_summary->>'update_on_return')::integer, 0)
      + coalesce((v_summary->>'unsafe_legacy')::integer, 0)
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_sale(p_commit_id text, p_operation_id text, p_sale jsonb, p_items jsonb, p_moves jsonb, p_payments jsonb, p_stock_lines jsonb, p_reserve_stock boolean, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_folio text := p_sale ->> 'folio';
  v_payload_hash text;
  v_prior pos.sale_commits%rowtype;
  v_stock jsonb := jsonb_build_object('ok', true, 'products', '[]'::jsonb);
  v_products jsonb := '[]'::jsonb;
  v_clients jsonb := '[]'::jsonb;
  v_sellers jsonb := '[]'::jsonb;
  v_client_id text;
  v_client_compras integer;
  v_client_total numeric;
  v_client_ultima date;
  v_client_base bigint;
  v_client_after_compras integer;
  v_client_after_total numeric;
  v_effect record;
begin
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para registrar ventas'
      using errcode = '42501';
  end if;

  if nullif(trim(p_commit_id), '') is null
     or nullif(trim(p_operation_id), '') is null
     or nullif(trim(v_folio), '') is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_typeof(p_moves) <> 'array'
     or jsonb_typeof(p_payments) <> 'array'
     or jsonb_typeof(p_stock_lines) <> 'array'
     or jsonb_typeof(p_seller_effects) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;

  v_payload_hash := md5(jsonb_build_object(
    'operation_id', p_operation_id,
    'sale', p_sale,
    'items', p_items,
    'moves', p_moves,
    'payments', p_payments,
    'stock_lines', p_stock_lines,
    'reserve_stock', coalesce(p_reserve_stock, false),
    'client_effect', p_client_effect,
    'seller_effects', p_seller_effects
  )::text);

  perform pg_advisory_xact_lock(hashtext(p_commit_id));

  select * into v_prior
    from pos.sale_commits
   where commit_id = p_commit_id;

  if found then
    if v_prior.payload_hash <> v_payload_hash
       or v_prior.operation_id <> p_operation_id
       or v_prior.folio <> v_folio then
      return jsonb_build_object('ok', false, 'error', 'commit_mismatch');
    end if;

    select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
      into v_products
      from pos.products p
     where p.id in (
       select distinct x.product_id
         from jsonb_to_recordset(p_stock_lines)
           as x(product_id text, talla text, qty integer)
     );
    if p_client_effect is not null then
      select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
        into v_clients from pos.clients c
       where c.id = p_client_effect ->> 'id';
    end if;
    select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
      into v_sellers from pos.sellers s
     where s.id in (
       select x.id
         from jsonb_to_recordset(p_seller_effects)
           as x(id text, ventas_mes_delta numeric, ventas_num_delta integer, comision_acum_delta numeric)
     );
    return jsonb_build_object(
      'ok', true, 'idempotent', true, 'products', v_products,
      'clients', v_clients, 'sellers', v_sellers
    );
  end if;

  if exists (
    select 1 from pos.sales
     where folio = v_folio
       and operation_id is distinct from p_operation_id
  ) then
    return jsonb_build_object('ok', false, 'error', 'folio_conflict');
  end if;

  if coalesce(p_reserve_stock, false) then
    v_stock := pos.reserve_sale_stock(p_operation_id, v_folio, p_stock_lines);
    if not coalesce((v_stock ->> 'ok')::boolean, false) then
      return v_stock;
    end if;
    v_products := coalesce(v_stock -> 'products', '[]'::jsonb);
  end if;

  insert into pos.sales (
    folio, operation_id, fecha, cliente_id, cliente, vendedores, metodo, estado,
    items, subtotal, iva, total, iva_pct, iva_included, anticipo, saldo,
    pago_efectivo, pago_otro, descuento, valor_regalado,
    return_limit_days, return_expires_at
  ) values (
    v_folio, p_operation_id, (p_sale ->> 'fecha')::timestamptz,
    nullif(p_sale ->> 'cliente_id', ''), p_sale ->> 'cliente',
    coalesce(p_sale -> 'vendedores', '[]'::jsonb), p_sale ->> 'metodo',
    p_sale ->> 'estado', coalesce((p_sale ->> 'items')::integer, 0),
    (p_sale ->> 'subtotal')::numeric, (p_sale ->> 'iva')::numeric,
    coalesce((p_sale ->> 'total')::numeric, 0), (p_sale ->> 'iva_pct')::numeric,
    (p_sale ->> 'iva_included')::boolean, (p_sale ->> 'anticipo')::numeric,
    (p_sale ->> 'saldo')::numeric, (p_sale ->> 'pago_efectivo')::numeric,
    (p_sale ->> 'pago_otro')::numeric, (p_sale ->> 'descuento')::numeric,
    coalesce((p_sale ->> 'valor_regalado')::numeric, 0),
    -- H-34: la AUSENCIA de la clave significa venta sin límite. Un cliente
    -- anterior a esta migración nunca la envía y obtiene NULL, es decir el
    -- mismo resultado que producía la versión previa de esta función.
    nullif(p_sale ->> 'return_limit_days', '')::integer,
    nullif(p_sale ->> 'return_expires_at', '')::date
  )
  on conflict (folio) do update set
    operation_id = excluded.operation_id,
    fecha = excluded.fecha,
    cliente_id = excluded.cliente_id,
    cliente = excluded.cliente,
    vendedores = excluded.vendedores,
    metodo = excluded.metodo,
    estado = excluded.estado,
    items = excluded.items,
    subtotal = excluded.subtotal,
    iva = excluded.iva,
    total = excluded.total,
    iva_pct = excluded.iva_pct,
    iva_included = excluded.iva_included,
    anticipo = excluded.anticipo,
    saldo = excluded.saldo,
    pago_efectivo = excluded.pago_efectivo,
    pago_otro = excluded.pago_otro,
    descuento = excluded.descuento,
    valor_regalado = excluded.valor_regalado,
    -- Un reintento que no traiga el plazo NO lo borra: sólo avanza cuando el
    -- cliente envía un valor. Protege la venta ya registrada con plazo.
    return_limit_days = coalesce(excluded.return_limit_days, pos.sales.return_limit_days),
    return_expires_at = coalesce(excluded.return_expires_at, pos.sales.return_expires_at),
    updated_at = now();

  delete from pos.sale_items where folio = v_folio;
  insert into pos.sale_items (
    folio, product_id, sku, nombre, talla, qty, precio, precio_base, precio_original, promos
  )
  select v_folio, x.product_id, x.sku, x.nombre, x.talla, x.qty,
         x.precio, x.precio_base, x.precio_original, x.promos
    from jsonb_to_recordset(p_items) as x(
      folio text, product_id text, sku text, nombre text, talla text,
      qty integer, precio numeric, precio_base numeric, precio_original numeric,
      promos jsonb
    );

  delete from pos.movements where ref = v_folio and tipo = 'Venta';
  insert into pos.movements (fecha, tipo, producto, product_id, sku, talla, cant, ref)
  select x.fecha::timestamptz, x.tipo, x.producto, x.product_id, x.sku, x.talla, x.cant, v_folio
    from jsonb_to_recordset(p_moves)
      as x(fecha text, tipo text, producto text, product_id text, sku text, talla text, cant integer, ref text);

  delete from pos.sale_payments where folio = v_folio;
  insert into pos.sale_payments (
    id, folio, fecha, tipo, metodo, monto, efectivo, tarjeta, transferencia, otro
  )
  select x.id, v_folio, x.fecha, x.tipo, x.metodo, x.monto,
         x.efectivo, x.tarjeta, x.transferencia, x.otro
    from jsonb_to_recordset(p_payments) as x(
      id text, folio text, fecha text, tipo text, metodo text, monto numeric,
      efectivo numeric, tarjeta numeric, transferencia numeric, otro numeric
    );

  if p_client_effect is not null then
    v_client_id := p_client_effect ->> 'id';
    v_client_compras := coalesce((p_client_effect ->> 'compras_delta')::integer, 0);
    v_client_total := coalesce((p_client_effect ->> 'total_delta')::numeric, 0);
    v_client_ultima := (p_client_effect ->> 'ultima')::date;
    v_client_base := coalesce((p_client_effect ->> 'base_version')::bigint, 0);
    v_client_after_compras := (p_client_effect ->> 'after_compras')::integer;
    v_client_after_total := (p_client_effect ->> 'after_total')::numeric;
    update pos.clients
       set compras = case
             when sync_version = v_client_base + 1
              and compras = v_client_after_compras
              and total = v_client_after_total
             then compras else compras + v_client_compras end,
           total = case
             when sync_version = v_client_base + 1
              and compras = v_client_after_compras
              and total = v_client_after_total
             then total else total + v_client_total end,
           ultima = coalesce(v_client_ultima, ultima),
           sync_base_version = sync_version,
           sync_device_id = 'sale:' || p_commit_id
     where id = v_client_id and deleted_at is null;
    if not found then
      raise exception 'Cliente de la venta no existe'
        using errcode = 'P0001';
    end if;
    select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
      into v_clients from pos.clients c where c.id = v_client_id;
  end if;

  for v_effect in
    select *
      from jsonb_to_recordset(p_seller_effects) as x(
        id text, ventas_mes_delta numeric, ventas_num_delta integer,
        comision_acum_delta numeric, base_version bigint,
        after_ventas_mes numeric, after_ventas_num integer,
        after_comision_acum numeric
      )
  loop
    update pos.sellers
       set ventas_mes = case
             when sync_version = coalesce(v_effect.base_version, 0) + 1
              and ventas_mes = v_effect.after_ventas_mes
              and ventas_num = v_effect.after_ventas_num
              and comision_acum = v_effect.after_comision_acum
             then ventas_mes else ventas_mes + coalesce(v_effect.ventas_mes_delta, 0) end,
           ventas_num = case
             when sync_version = coalesce(v_effect.base_version, 0) + 1
              and ventas_mes = v_effect.after_ventas_mes
              and ventas_num = v_effect.after_ventas_num
              and comision_acum = v_effect.after_comision_acum
             then ventas_num else ventas_num + coalesce(v_effect.ventas_num_delta, 0) end,
           comision_acum = case
             when sync_version = coalesce(v_effect.base_version, 0) + 1
              and ventas_mes = v_effect.after_ventas_mes
              and ventas_num = v_effect.after_ventas_num
              and comision_acum = v_effect.after_comision_acum
             then comision_acum else comision_acum + coalesce(v_effect.comision_acum_delta, 0) end,
           sync_base_version = sync_version,
           sync_device_id = 'sale:' || p_commit_id
     where id = v_effect.id and active = true and deleted_at is null;
    if not found then
      raise exception 'Vendedor de la venta no existe o está inactivo'
        using errcode = 'P0001';
    end if;
  end loop;

  select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
    into v_sellers from pos.sellers s
   where s.id in (
     select x.id
       from jsonb_to_recordset(p_seller_effects)
         as x(id text, ventas_mes_delta numeric, ventas_num_delta integer, comision_acum_delta numeric)
   );

  insert into pos.sale_commits (
    commit_id, operation_id, folio, payload_hash, actor_email
  ) values (
    p_commit_id, p_operation_id, v_folio, v_payload_hash, auth.jwt() ->> 'email'
  );

  return jsonb_build_object(
    'ok', true, 'idempotent', false, 'products', v_products,
    'clients', v_clients, 'sellers', v_sellers
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_set_sync_device_retired(p_device_id text, p_retired boolean, p_note text DEFAULT NULL::text)
 RETURNS pos.sync_devices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_row pos.sync_devices;
begin
  if not pos.is_active_admin() then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  update pos.sync_devices set
    status = case when p_retired then 'revoked' else 'must_rebootstrap' end,
    metadata = metadata || jsonb_build_object(
      case when p_retired then 'retired_at' else 'reactivated_at' end, now(),
      case when p_retired then 'retired_by' else 'reactivated_by' end, auth.uid(),
      'reactivation_requires_sync', not p_retired,
      'retirement_note', nullif(left(btrim(coalesce(p_note, '')), 500), '')
    )
  where device_id = p_device_id
  returning * into v_row;
  if not found then raise exception 'device_not_found'; end if;
  perform pos.bump_sync_domain('devices', p_device_id);
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_exchange(p_commit_id text, p_exchange jsonb, p_items jsonb, p_moves jsonb DEFAULT '[]'::jsonb, p_payment jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_id           text := p_exchange ->> 'id';
  v_folio        text := p_exchange ->> 'folio';
  v_origen       text := p_exchange ->> 'origen_folio';
  v_hash         text;
  v_prior        pos.exchange_commits%rowtype;
  v_expira       date;
  v_hoy          date := coalesce(nullif(left(p_exchange ->> 'fecha', 10), '')::date, current_date);
  v_shortages    jsonb;
  v_reconocido   numeric := 0;
  v_entregado    numeric := 0;
  v_diferencia   numeric := 0;
  v_no_aprov     numeric := 0;
  v_base_com     numeric := 0;
  v_rec          record;
  v_products     jsonb := '[]'::jsonb;
  v_pago_monto   numeric := 0;
  v_effect       record;
  v_sellers      jsonb := '[]'::jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_commit_id::text,p_exchange->>'id']::text[]);
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para registrar cambios' using errcode = '42501';
  end if;

  -- 1) Forma
  if nullif(trim(p_commit_id), '') is null
     or nullif(trim(coalesce(v_id, '')), '') is null
     or nullif(trim(coalesce(v_folio, '')), '') is null
     or nullif(trim(coalesce(v_origen, '')), '') is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_typeof(coalesce(p_moves, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_seller_effects, '[]'::jsonb)) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;

  if exists (
    select 1 from jsonb_to_recordset(p_items)
      as x(lado text, product_id text, sku text, talla text, qty integer)
     where coalesce(x.lado, '') not in ('devuelto', 'entregado')
        or nullif(trim(coalesce(x.sku, '')), '') is null
        or nullif(trim(coalesce(x.talla, '')), '') is null
        or nullif(trim(coalesce(x.product_id, '')), '') is null
        or coalesce(x.qty, 0) <= 0
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;

  -- Un cambio exige las dos mitades: sin ellas es una devolución o una venta.
  if not exists (select 1 from jsonb_to_recordset(p_items) as x(lado text) where x.lado = 'devuelto')
     or not exists (select 1 from jsonb_to_recordset(p_items) as x(lado text) where x.lado = 'entregado') then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;

  v_hash := md5(jsonb_build_object(
    'exchange', p_exchange, 'items', p_items, 'moves', coalesce(p_moves, '[]'::jsonb),
    'payment', coalesce(p_payment, 'null'::jsonb),
    'seller_effects', coalesce(p_seller_effects, '[]'::jsonb)
  )::text);

  perform pg_advisory_xact_lock(hashtext(p_commit_id));

  -- 2) Idempotencia
  select * into v_prior from pos.exchange_commits where commit_id = p_commit_id;
  if found then
    if v_prior.payload_hash <> v_hash or v_prior.exchange_id <> v_id or v_prior.folio <> v_folio then
      return jsonb_build_object('ok', false, 'error', 'commit_mismatch');
    end if;
    return jsonb_build_object('ok', true, 'idempotent', true,
      'exchange', (select to_jsonb(e) from pos.exchanges e where e.id = v_id));
  end if;

  -- 3) Serializa todos los documentos de la misma venta
  perform 1 from pos.sales where folio = v_origen for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'sale_not_found');
  end if;

  if exists (select 1 from pos.exchanges where id = v_id) then
    return jsonb_build_object('ok', false, 'error', 'exchange_id_conflict');
  end if;

  -- 4) Plazo de posventa (H-34). El derecho a cambiar está sujeto al plazo de la
  --    venta origen; nulo significa sin límite, igual que en devoluciones.
  select return_expires_at into v_expira from pos.sales where folio = v_origen;
  if v_expira is not null and v_hoy > v_expira then
    return jsonb_build_object('ok', false, 'error', 'exchange_window_closed',
      'expires_at', v_expira);
  end if;

  -- 5) Saldo disponible (H-35/H-37). La autoridad ya suma el suministro de
  --    cambios anteriores, así que una pieza recibida antes puede recambiarse.
  with pedido as (
    select x.sku, x.talla, sum(x.qty)::integer as qty
      from jsonb_to_recordset(p_items) as x(lado text, sku text, talla text, qty integer)
     where x.lado = 'devuelto'
     group by x.sku, x.talla
  ),
  saldo as (
    select b.sku, b.talla, b.disponible as qty
      from pos.sale_line_balance(v_origen, v_id) b
  )
  select jsonb_agg(jsonb_build_object(
           'sku', p.sku, 'talla', p.talla,
           'requested', p.qty, 'available', coalesce(s.qty, 0)
         ) order by p.sku, p.talla)
    into v_shortages
    from pedido p
    left join saldo s on s.sku = p.sku and s.talla is not distinct from p.talla
   where p.qty > coalesce(s.qty, 0);

  if v_shortages is not null then
    return jsonb_build_object('ok', false, 'error', 'invalid_exchange_quantity',
      'items', v_shortages);
  end if;

  -- 6) Valoración. SIEMPRE en el servidor (Contrato §3).
  select coalesce(sum(x.qty * pos.line_recognized_value(v_origen, x.sku, x.talla)), 0)
    into v_reconocido
    from jsonb_to_recordset(p_items) as x(lado text, sku text, talla text, qty integer)
   where x.lado = 'devuelto';

  select coalesce(sum(x.qty * pos.list_price(x.product_id, x.talla)), 0)
    into v_entregado
    from jsonb_to_recordset(p_items)
      as x(lado text, product_id text, talla text, qty integer)
   where x.lado = 'entregado';

  if v_entregado >= v_reconocido then
    v_diferencia := round(v_entregado - v_reconocido, 2);
    v_no_aprov := 0;
  else
    -- El sobrante se pierde: nunca sale efectivo (Contrato §4).
    v_diferencia := 0;
    v_no_aprov := round(v_reconocido - v_entregado, 2);
  end if;
  v_base_com := v_diferencia;   -- §7: sólo el excedente genera comisión

  -- 6b) El cobro se valida ANTES de escribir nada. En 20260728005700 estas dos
  --     salidas ocurrian despues de insertar cabecera, renglones y movimientos:
  --     un `return` de plpgsql no aborta la transaccion, asi que un cobro mal
  --     formado dejaba el documento a medias. Es el defecto que H-04 existe para
  --     impedir. Ahora no se escribe una sola fila hasta que el dinero cuadra.
  if v_diferencia > 0 then
    if p_payment is null then
      return jsonb_build_object('ok', false, 'error', 'payment_required',
        'expected', v_diferencia);
    end if;
    v_pago_monto := coalesce((p_payment ->> 'monto')::numeric, 0);
    if round(v_pago_monto, 2) <> v_diferencia then
      return jsonb_build_object('ok', false, 'error', 'payment_mismatch',
        'expected', v_diferencia, 'received', v_pago_monto);
    end if;
  end if;

  -- 7) Inventario. Bloqueo estable de TODOS los productos implicados, en un solo
  --    orden, para evitar deadlocks entre cambios concurrentes.
  perform p.id from pos.products p
   where p.id in (select distinct x.product_id from jsonb_to_recordset(p_items)
                    as x(product_id text))
   order by p.id
   for update;

  -- Toda talla implicada debe existir en su producto.
  with lineas as (
    select x.product_id, x.talla from jsonb_to_recordset(p_items)
      as x(product_id text, talla text) group by x.product_id, x.talla
  )
  select jsonb_agg(jsonb_build_object('product_id', l.product_id, 'talla', l.talla,
           'reason', case when p.id is null then 'product_not_found' else 'size_not_found' end)
         order by l.product_id, l.talla)
    into v_shortages
    from lineas l
    left join pos.products p on p.id = l.product_id and p.deleted_at is null
   where p.id is null
      or not exists (select 1 from jsonb_array_elements(p.stock) e where e ->> 'talla' = l.talla);

  if v_shortages is not null then
    return jsonb_build_object('ok', false, 'error', 'invalid_stock_target', 'items', v_shortages);
  end if;

  -- Reserva de lo ENTREGADO: se valida ANTES de escribir, dentro del mismo
  -- bloqueo, así que dos terminales no pueden entregar la última pieza (H-01).
  with pedido as (
    select x.product_id, x.talla, sum(x.qty)::integer as qty
      from jsonb_to_recordset(p_items)
        as x(lado text, product_id text, talla text, qty integer)
     where x.lado = 'entregado'
     group by x.product_id, x.talla
  )
  select jsonb_agg(jsonb_build_object('product_id', pe.product_id, 'talla', pe.talla,
           'requested', pe.qty, 'available', (e.value ->> 'stock')::integer)
         order by pe.product_id, pe.talla)
    into v_shortages
    from pedido pe
    join pos.products p on p.id = pe.product_id
    cross join lateral jsonb_array_elements(p.stock) e
   where e.value ->> 'talla' = pe.talla
     and (e.value ->> 'stock')::integer < pe.qty;

  if v_shortages is not null then
    return jsonb_build_object('ok', false, 'error', 'insufficient_stock', 'items', v_shortages);
  end if;

  -- Movimiento neto por (producto, talla): + lo devuelto, − lo entregado.
  for v_rec in
    with delta as (
      select x.product_id, x.talla,
             sum(case when x.lado = 'devuelto' then x.qty else -x.qty end)::integer as qty
        from jsonb_to_recordset(p_items)
          as x(lado text, product_id text, talla text, qty integer)
       group by x.product_id, x.talla
    )
    select d.product_id, d.talla, d.qty,
           (e.value ->> 'stock')::integer as available,
           e.ordinality::integer - 1 as stock_index
      from delta d
      join pos.products p on p.id = d.product_id
      cross join lateral jsonb_array_elements(p.stock) with ordinality as e(value, ordinality)
     where e.value ->> 'talla' = d.talla and d.qty <> 0
     order by d.product_id, d.talla
  loop
    update pos.products p
       set stock = jsonb_set(p.stock, array[v_rec.stock_index::text, 'stock'],
             to_jsonb(greatest(v_rec.available + v_rec.qty, 0)), false),
           sync_base_version = p.sync_version,
           sync_device_id = 'exchange:' || p_commit_id
     where p.id = v_rec.product_id;
  end loop;

  -- 8) Documento
  insert into pos.exchanges (
    id, folio, origen_folio, fecha, usuario, vendedor_id, revisado_por,
    valor_reconocido, valor_entregado, diferencia, valor_no_aprovechado,
    base_comision, comision_monto, comision_base, comision_pct, notas
  ) values (
    v_id, v_folio, v_origen, p_exchange ->> 'fecha', p_exchange ->> 'usuario',
    p_exchange ->> 'vendedor_id', p_exchange ->> 'revisado_por',
    v_reconocido, v_entregado, v_diferencia, v_no_aprov, v_base_com,
    coalesce((p_exchange ->> 'comision_monto')::numeric, 0),
    nullif(p_exchange ->> 'comision_base', ''),
    coalesce((p_exchange ->> 'comision_pct')::numeric, 0),
    p_exchange ->> 'notas'
  );

  insert into pos.exchange_items (exchange_id, lado, product_id, sku, nombre, talla, qty, precio, motivo, condicion)
  select v_id, x.lado, x.product_id, x.sku, x.nombre, x.talla, x.qty,
         case when x.lado = 'entregado'
              then pos.list_price(x.product_id, x.talla)
              else pos.line_recognized_value(v_origen, x.sku, x.talla) end,
         x.motivo, x.condicion
    from jsonb_to_recordset(p_items)
      as x(lado text, product_id text, sku text, nombre text, talla text, qty integer,
           motivo text, condicion text);

  -- 9) Movimientos de inventario (historial de sólo lectura para el cliente)
  if jsonb_array_length(coalesce(p_moves, '[]'::jsonb)) > 0 then
    insert into pos.movements (fecha, tipo, producto, product_id, sku, talla, cant, ref)
    select x.fecha, x.tipo, x.producto, x.product_id, x.sku, x.talla, x.cant, coalesce(x.ref, v_folio)
      from jsonb_to_recordset(p_moves)
        as x(fecha timestamptz, tipo text, producto text, product_id text, sku text, talla text, cant integer, ref text);
  end if;

  -- 10) Cobro de la diferencia. Ledger único, con el folio PROPIO del cambio:
  --     usar el de la venta origen violaria §8 y ademas commit_sale borra por
  --     folio antes de reinsertar. Nunca se emite un pago negativo.
  if v_diferencia > 0 then
    insert into pos.sale_payments (id, folio, fecha, tipo, metodo, monto,
                                   efectivo, tarjeta, transferencia, otro)
    values (
      p_payment ->> 'id', v_folio, p_payment ->> 'fecha', 'cambio',
      coalesce(p_payment ->> 'metodo', 'Efectivo'), v_diferencia,
      coalesce((p_payment ->> 'efectivo')::numeric, 0),
      coalesce((p_payment ->> 'tarjeta')::numeric, 0),
      coalesce((p_payment ->> 'transferencia')::numeric, 0),
      coalesce((p_payment ->> 'otro')::numeric, 0)
    );
  end if;

  -- 10) Comision del excedente. Mismo criterio de reintento que `commit_sale`:
  -- si la version del vendedor ya avanzo UNO sobre la base leida y el valor final
  -- coincide, este efecto ya se aplico y es un reenvio de la cola; se deja como
  -- esta en vez de sumarlo dos veces.
  --
  -- Un cambio NO es un pedido: aqui no se tocan `ventas_mes` ni `ventas_num`, de
  -- modo que el conteo de ventas, el ticket promedio y las metas del equipo no se
  -- mueven. Solo el acumulado de comision.
  for v_effect in
    select *
      from jsonb_to_recordset(coalesce(p_seller_effects, '[]'::jsonb)) as x(
        id text, comision_acum_delta numeric, base_version bigint,
        after_comision_acum numeric
      )
  loop
    update pos.sellers
       set comision_acum = case
             when sync_version = coalesce(v_effect.base_version, 0) + 1
              and comision_acum = v_effect.after_comision_acum
             then comision_acum
             else greatest(0, comision_acum + coalesce(v_effect.comision_acum_delta, 0)) end,
           sync_base_version = sync_version,
           sync_device_id = 'exchange:' || p_commit_id
     where id = v_effect.id and active = true and deleted_at is null;
    if not found then
      raise exception 'Vendedor del cambio no existe o esta inactivo' using errcode = 'P0001';
    end if;
  end loop;

  select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
    into v_sellers from pos.sellers s
   where s.id in (
     select x.id from jsonb_to_recordset(coalesce(p_seller_effects, '[]'::jsonb))
       as x(id text, comision_acum_delta numeric)
   );

  insert into pos.exchange_commits (commit_id, exchange_id, folio, payload_hash, actor_email)
  values (p_commit_id, v_id, v_folio, v_hash, auth.jwt() ->> 'email');

  select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
    into v_products
    from pos.products p
   where p.id in (select distinct x.product_id from jsonb_to_recordset(p_items)
                    as x(product_id text));

  return jsonb_build_object(
    'ok', true, 'idempotent', false,
    'exchange', (select to_jsonb(e) from pos.exchanges e where e.id = v_id),
    'products', v_products, 'sellers', v_sellers
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_return(p_commit_id text, p_return jsonb, p_items jsonb, p_moves jsonb, p_stock_lines jsonb, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb, p_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_return_id text := p_return ->> 'id';
  v_folio text := p_return ->> 'folio';
  v_payload_hash text;
  v_prior pos.return_commits%rowtype;
  v_sale_state text;
  v_products jsonb := '[]'::jsonb;
  v_clients jsonb := '[]'::jsonb;
  v_sellers jsonb := '[]'::jsonb;
  v_shortages jsonb;
  v_rec record;
  v_stock_row jsonb;
  v_client_id text;
  v_client_base bigint;
  v_client_delta numeric;
  v_client_after numeric;
  v_effect record;
begin
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para registrar devoluciones'
      using errcode = '42501';
  end if;

  if nullif(trim(p_commit_id), '') is null
     or nullif(trim(v_return_id), '') is null
     or nullif(trim(v_folio), '') is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_typeof(p_moves) <> 'array'
     or jsonb_typeof(p_stock_lines) <> 'array'
     or jsonb_typeof(p_seller_effects) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;

  if exists (
    select 1
      from jsonb_to_recordset(p_items)
        as x(return_id text, product_id text, sku text, talla text, qty integer)
     where x.return_id is distinct from v_return_id
        or nullif(trim(x.sku), '') is null
        or nullif(trim(x.talla), '') is null
        or x.qty is null
        or x.qty <= 0
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;

  v_payload_hash := md5(jsonb_build_object(
    'return', p_return, 'items', p_items, 'moves', p_moves,
    'stock_lines', p_stock_lines, 'client_effect', p_client_effect,
    'seller_effects', p_seller_effects, 'legacy', coalesce(p_legacy, false)
  )::text);

  perform pg_advisory_xact_lock(hashtext(p_commit_id));

  select * into v_prior
    from pos.return_commits
   where commit_id = p_commit_id;

  if found then
    if v_prior.payload_hash <> v_payload_hash
       or v_prior.return_id <> v_return_id
       or v_prior.folio <> v_folio then
      return jsonb_build_object('ok', false, 'error', 'commit_mismatch');
    end if;
    select estado into v_sale_state from pos.sales where folio = v_folio;
    select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
      into v_products from pos.products p
     where p.id in (
       select x.product_id from jsonb_to_recordset(p_stock_lines)
         as x(product_id text, talla text, qty integer)
     );
    if p_client_effect is not null then
      select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
        into v_clients from pos.clients c
       where c.id = p_client_effect ->> 'id';
    end if;
    select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
      into v_sellers from pos.sellers s
     where s.id in (
       select x.id from jsonb_to_recordset(p_seller_effects)
         as x(id text, ventas_mes_delta numeric, comision_acum_delta numeric)
     );
    return jsonb_build_object(
      'ok', true, 'idempotent', true, 'sale_state', v_sale_state,
      'products', v_products, 'clients', v_clients, 'sellers', v_sellers
    );
  end if;

  -- Serializa todas las devoluciones del mismo folio.
  perform 1 from pos.sales where folio = v_folio for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'sale_not_found');
  end if;

  if exists (select 1 from pos.returns where id = v_return_id)
     and not coalesce(p_legacy, false) then
    return jsonb_build_object('ok', false, 'error', 'return_id_conflict');
  end if;

  -- H-35: la autoridad de cantidades es pos.sale_line_balance(), que suma
  -- TODAS las fuentes de consumo de la venta —devoluciones hoy, cambios cuando
  -- existan— y excluye esta misma devolución para permitir su reescritura.
  -- Antes de H-35 esta consulta agrupaba pos.return_items en línea, por lo que
  -- ninguna otra clase de documento podía participar del saldo.
  with requested as (
    select x.sku, x.talla, sum(x.qty)::integer as qty
      from jsonb_to_recordset(p_items)
        as x(return_id text, product_id text, sku text, talla text, qty integer)
     group by x.sku, x.talla
  ),
  disponible as (
    select b.sku, b.talla, b.disponible as qty
      from pos.sale_line_balance(v_folio, v_return_id) b
  )
  select jsonb_agg(jsonb_build_object(
           'sku', q.sku, 'talla', q.talla, 'requested', q.qty,
           'available', coalesce(d.qty, 0)
         ) order by q.sku, q.talla)
    into v_shortages
    from requested q
    left join disponible d using (sku, talla)
   where q.qty > coalesce(d.qty, 0);


  if v_shortages is not null then
    return jsonb_build_object(
      'ok', false, 'error', 'invalid_return_quantity',
      'items', v_shortages
    );
  end if;

  if coalesce((p_return ->> 'total')::numeric, 0)
     + coalesce((
       select sum(total) from pos.returns
        where folio = v_folio and id <> v_return_id
     ), 0)
     > coalesce((select total from pos.sales where folio = v_folio), 0) + 0.01 then
    return jsonb_build_object('ok', false, 'error', 'refund_exceeds_sale');
  end if;

  if not coalesce(p_legacy, false) then
    if jsonb_array_length(p_stock_lines) = 0
       or (select coalesce(sum(x.qty), 0) from jsonb_to_recordset(p_stock_lines)
             as x(product_id text, talla text, qty integer))
          <> (select coalesce(sum(x.qty), 0) from jsonb_to_recordset(p_items)
                as x(return_id text, product_id text, sku text, talla text, qty integer)) then
      return jsonb_build_object('ok', false, 'error', 'invalid_stock_lines');
    end if;

    perform p.id
      from pos.products p
     where p.id in (
       select distinct x.product_id
         from jsonb_to_recordset(p_stock_lines)
           as x(product_id text, talla text, qty integer)
     )
     order by p.id
     for update;

    with lines as (
      select x.product_id, x.talla, sum(x.qty)::integer as qty
        from jsonb_to_recordset(p_stock_lines)
          as x(product_id text, talla text, qty integer)
       group by x.product_id, x.talla
    )
    select jsonb_agg(jsonb_build_object(
             'product_id', l.product_id, 'talla', l.talla,
             'reason', case when p.id is null then 'product_not_found'
                            else 'size_not_found' end
           ) order by l.product_id, l.talla)
      into v_shortages
      from lines l
      left join pos.products p
        on p.id = l.product_id and p.deleted_at is null
     where p.id is null
        or not exists (
          select 1 from jsonb_array_elements(p.stock) e
           where e ->> 'talla' = l.talla
        );

    if v_shortages is not null then
      return jsonb_build_object(
        'ok', false, 'error', 'invalid_stock_target', 'items', v_shortages
      );
    end if;

    for v_rec in
      with lines as (
        select x.product_id, x.talla, sum(x.qty)::integer as qty
          from jsonb_to_recordset(p_stock_lines)
            as x(product_id text, talla text, qty integer)
         group by x.product_id, x.talla
      )
      select l.product_id, l.talla, l.qty,
             (e.value ->> 'stock')::integer as available,
             e.ordinality::integer - 1 as stock_index
        from lines l
        join pos.products p on p.id = l.product_id
        cross join lateral jsonb_array_elements(p.stock)
          with ordinality as e(value, ordinality)
       where e.value ->> 'talla' = l.talla
       order by l.product_id, l.talla
    loop
      update pos.products p
         set stock = jsonb_set(
               p.stock, array[v_rec.stock_index::text, 'stock'],
               to_jsonb(v_rec.available + v_rec.qty), false
             ),
             sync_base_version = p.sync_version,
             sync_device_id = 'return:' || p_commit_id
       where p.id = v_rec.product_id
       returning to_jsonb(p.*) into v_stock_row;
    end loop;
  end if;

  insert into pos.returns (
    id, folio, cliente, vendedores, metodo, total, notas, fecha
  ) values (
    v_return_id, v_folio, p_return ->> 'cliente',
    coalesce(p_return -> 'vendedores', '[]'::jsonb),
    p_return ->> 'metodo', coalesce((p_return ->> 'total')::numeric, 0),
    p_return ->> 'notas', p_return ->> 'fecha'
  )
  on conflict (id) do update set
    folio = excluded.folio,
    cliente = excluded.cliente,
    vendedores = excluded.vendedores,
    metodo = excluded.metodo,
    total = excluded.total,
    notas = excluded.notas,
    fecha = excluded.fecha,
    updated_at = now();

  delete from pos.return_items where return_id = v_return_id;
  insert into pos.return_items (
    return_id, product_id, sku, nombre, talla, qty, motivo, precio
  )
  select v_return_id, x.product_id, x.sku, x.nombre, x.talla,
         x.qty, x.motivo, x.precio
    from jsonb_to_recordset(p_items) as x(
      return_id text, product_id text, sku text, nombre text, talla text,
      qty integer, motivo text, precio numeric
    );

  if coalesce(p_legacy, false) then
    delete from pos.movements where ref = v_folio and tipo = 'Devolución';
  else
    delete from pos.movements where return_id = v_return_id;
  end if;
  insert into pos.movements (
    return_id, fecha, tipo, producto, product_id, sku, talla, cant, ref
  )
  select case when coalesce(p_legacy, false) then null else v_return_id end,
         x.fecha::timestamptz, 'Devolución', x.producto, x.product_id, x.sku, x.talla, x.cant, v_folio
    from jsonb_to_recordset(p_moves)
      as x(return_id text, fecha text, tipo text, producto text, product_id text, sku text, talla text, cant integer, ref text);

  -- H-35: el estado también sale de la autoridad única. Equivale al cálculo
  -- anterior: disponible = greatest(vendida - consumida, 0) y toda fila del
  -- balance tiene vendida > 0, así que "queda algo por consumir" es idéntico a
  -- "existe un renglón vendido con menos consumo que unidades".
  select case when exists (
    select 1 from pos.sale_line_balance(v_folio) b where b.disponible > 0
  ) then 'Devolución parcial' else 'Devuelto' end
    into v_sale_state;

  update pos.sales
     set estado = v_sale_state, updated_at = now()
   where folio = v_folio;

  if not coalesce(p_legacy, false) and p_client_effect is not null then
    v_client_id := p_client_effect ->> 'id';
    v_client_base := coalesce((p_client_effect ->> 'base_version')::bigint, 0);
    v_client_delta := coalesce((p_client_effect ->> 'total_delta')::numeric, 0);
    v_client_after := (p_client_effect ->> 'after_total')::numeric;
    update pos.clients
       set total = case
             when sync_version = v_client_base + 1 and total = v_client_after
             then total else greatest(0, total + v_client_delta) end,
           sync_base_version = sync_version,
           sync_device_id = 'return:' || p_commit_id
     where id = v_client_id and deleted_at is null;
    if not found then
      raise exception 'Cliente de la devolución no existe'
        using errcode = 'P0001';
    end if;
  end if;

  if not coalesce(p_legacy, false) then
    for v_effect in
      select * from jsonb_to_recordset(p_seller_effects) as x(
        id text, base_version bigint, ventas_mes_delta numeric,
        comision_acum_delta numeric, after_ventas_mes numeric,
        after_comision_acum numeric
      )
    loop
      update pos.sellers
         set ventas_mes = case
               when sync_version = coalesce(v_effect.base_version, 0) + 1
                and ventas_mes = v_effect.after_ventas_mes
                and comision_acum = v_effect.after_comision_acum
               then ventas_mes else greatest(0, ventas_mes + coalesce(v_effect.ventas_mes_delta, 0)) end,
             comision_acum = case
               when sync_version = coalesce(v_effect.base_version, 0) + 1
                and ventas_mes = v_effect.after_ventas_mes
                and comision_acum = v_effect.after_comision_acum
               then comision_acum else greatest(0, comision_acum + coalesce(v_effect.comision_acum_delta, 0)) end,
             sync_base_version = sync_version,
             sync_device_id = 'return:' || p_commit_id
       where id = v_effect.id and active = true and deleted_at is null;
      if not found then
        raise exception 'Vendedor de la devolución no existe o está inactivo'
          using errcode = 'P0001';
      end if;
    end loop;
  end if;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
    into v_products from pos.products p
   where p.id in (
     select x.product_id from jsonb_to_recordset(p_stock_lines)
       as x(product_id text, talla text, qty integer)
   );
  if p_client_effect is not null then
    select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
      into v_clients from pos.clients c
     where c.id = p_client_effect ->> 'id';
  end if;
  select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
    into v_sellers from pos.sellers s
   where s.id in (
     select x.id from jsonb_to_recordset(p_seller_effects)
       as x(id text, ventas_mes_delta numeric, comision_acum_delta numeric)
   );

  insert into pos.return_commits (
    commit_id, return_id, folio, payload_hash, actor_email
  ) values (
    p_commit_id, v_return_id, v_folio, v_payload_hash, auth.jwt() ->> 'email'
  );

  return jsonb_build_object(
    'ok', true, 'idempotent', false, 'sale_state', v_sale_state,
    'products', v_products, 'clients', v_clients, 'sellers', v_sellers
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.claim_physical_card(p_folio text, p_claim_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_folio text := upper(trim(p_folio));
  v_token text := trim(p_claim_token);
  v_existing pos.physical_card_redemptions%rowtype;
begin
  perform pos.assert_device_recovery_write(null::text,array[]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para validar tarjetas' using errcode = '42501';
  end if;
  if nullif(v_folio, '') is null or nullif(v_token, '') is null then return false; end if;
  perform pg_advisory_xact_lock(hashtext('physical-card:' || v_folio));
  select * into v_existing from pos.physical_card_redemptions where folio = v_folio;
  if found and v_existing.sale_folio is not null then return false; end if;
  if found and v_existing.claim_token = v_token then return true; end if;
  if found and v_existing.claimed_at > now() - interval '15 minutes' then return false; end if;
  delete from pos.physical_card_redemptions where folio = v_folio;
  insert into pos.physical_card_redemptions(folio, claim_token, claimed_by)
  values (v_folio, v_token, auth.uid());
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION pos.physical_card_available(p_folio text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_folio text := upper(trim(p_folio));
begin
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para validar tarjetas' using errcode = '42501';
  end if;
  if nullif(v_folio, '') is null then return false; end if;
  return not exists (
    select 1 from pos.physical_card_redemptions
    where folio = v_folio
      and (sale_folio is not null or claimed_at > now() - interval '15 minutes')
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_decide_sync_quarantine(p_device_id text, p_operation_id text, p_remote_epoch bigint, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock_shared(hashtextextended('pos.h149.recovery-fence',0));
  if not pos.is_active_admin() then raise exception 'admin_required' using errcode='42501'; end if;
  if p_decision not in ('approve','reject') then raise exception 'invalid_decision'; end if;
  update pos.sync_quarantine_cases set
    status=case when p_decision='approve' then 'approved' else 'rejected' end,
    decision_note=nullif(left(btrim(coalesce(p_note,'')),500),''),
    decision_by=auth.uid(), decision_at=now(), updated_at=now(),
    execution_message=null
  where device_id=p_device_id and operation_id=p_operation_id
    and remote_epoch=p_remote_epoch and status in ('pending_review','failed')
    and discarded_by_cleanup is null;
  if not found then raise exception 'quarantine_case_not_actionable'; end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_sale_with_additional_discount(p_commit_id text, p_operation_id text, p_sale jsonb, p_items jsonb, p_moves jsonb, p_payments jsonb, p_stock_lines jsonb, p_reserve_stock boolean, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_result jsonb;
  v_folio text := p_sale ->> 'folio';
  v_app record;
  v_card text;
  v_prior text;
  v_claim text;
begin
  if jsonb_typeof(p_sale -> 'descuentos_adicionales') <> 'array'
     or coalesce((p_sale ->> 'descuento_adicional')::numeric, -1) < 0
     or coalesce((p_sale ->> 'total_antes_descuento_adicional')::numeric, -1) < 0
     or round(coalesce((p_sale ->> 'total_antes_descuento_adicional')::numeric, 0)
            - coalesce((p_sale ->> 'descuento_adicional')::numeric, 0), 2)
        <> round(coalesce((p_sale ->> 'total')::numeric, 0), 2) then
    return jsonb_build_object('ok', false, 'error', 'invalid_additional_discount');
  end if;

  if abs(
    coalesce((select sum(coalesce((x ->> 'descuento_adicional')::numeric, 0))
      from jsonb_array_elements(p_items) x), 0)
    - coalesce((p_sale ->> 'descuento_adicional')::numeric, 0)
  ) > 0.01 then
    return jsonb_build_object('ok', false, 'error', 'additional_discount_lines_mismatch');
  end if;

  -- La autoridad vigente realiza venta, inventario, pagos, cliente y vendedores.
  -- Una excepción posterior revierte también esos efectos: es una sola transacción.
  v_result := pos.commit_sale(
    p_commit_id, p_operation_id, p_sale, p_items, p_moves, p_payments,
    p_stock_lines, p_reserve_stock, p_client_effect, p_seller_effects
  );
  if not coalesce((v_result ->> 'ok')::boolean, false) then return v_result; end if;

  update pos.sales set
    descuento_adicional = (p_sale ->> 'descuento_adicional')::numeric,
    total_antes_descuento_adicional = (p_sale ->> 'total_antes_descuento_adicional')::numeric,
    descuentos_adicionales = p_sale -> 'descuentos_adicionales'
  where folio = v_folio;

  update pos.sale_items si set
    descuento_adicional = x.descuento_adicional
  from jsonb_to_recordset(p_items) as x(
    folio text, product_id text, sku text, nombre text, talla text,
    qty integer, precio numeric, precio_base numeric, precio_original numeric,
    promos jsonb, descuento_adicional numeric
  )
  where si.folio = v_folio and si.sku = x.sku and si.talla is not distinct from x.talla;

  for v_app in
    select value as app from jsonb_array_elements(p_sale -> 'descuentos_adicionales')
  loop
    if v_app.app ->> 'origin' = 'Tarjeta física' then
      v_card := upper(trim(v_app.app ->> 'cardFolio'));
      v_claim := trim(v_app.app ->> 'claimToken');
      if nullif(v_card, '') is null or nullif(v_claim, '') is null
         or coalesce((v_app.app ->> 'onlineVerified')::boolean, false) is not true then
        raise exception 'Tarjeta física sin validación en línea' using errcode = 'P0001';
      end if;
      perform pg_advisory_xact_lock(hashtext('physical-card:' || v_card));
      update pos.physical_card_redemptions set
        sale_folio = v_folio,
        benefit_code = v_app.app ->> 'benefitCode',
        benefit_name = v_app.app ->> 'benefitName',
        redeemed_by = v_app.app ->> 'appliedBy',
        redeemed_at = now()
      where folio = v_card and claim_token = v_claim
        and sale_folio is null and claimed_at > now() - interval '15 minutes';
      if not found then
        raise exception 'El folio de tarjeta física ya fue utilizado o la reserva expiró' using errcode = '23505';
      end if;
    end if;
  end loop;
  return v_result || jsonb_build_object('additional_discount', true);
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_mark_sync_activity_reviewed(p_device_id text, p_operation_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if not pos.is_active_admin() then
    raise exception 'admin_required' using errcode='42501';
  end if;
  update pos.sync_activity set
    requires_action=false, admin_action='review', action_status='completed',
    action_by=auth.uid(), action_at=now(), updated_at=now()
  where device_id=p_device_id and operation_id=p_operation_id;
  if not found then raise exception 'sync_activity_not_found'; end if;
  perform pos.bump_sync_domain('devices', p_device_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_alias_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if pos.h133_internal_enabled() then return case when tg_op='DELETE' then old else new end; end if;
  raise exception 'BARCODE_ALIAS_IMMUTABLE';
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_barcode_v3_from_id(p_id text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_hex text; v_value numeric := 0; v_i integer; v_digit integer; v_char text;
begin
  if p_id !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' then
    raise exception 'BARCODE_V3_UUID_REQUIRED' using errcode='22023';
  end if;
  v_hex := lower(replace(p_id, '-', ''));
  for v_i in 13..32 loop
    v_char := substr(v_hex, v_i, 1);
    v_digit := strpos('0123456789abcdef', v_char) - 1;
    if v_digit < 0 then raise exception 'BARCODE_V3_UUID_REQUIRED' using errcode='22023'; end if;
    v_value := v_value * 16 + v_digit;
  end loop;
  return '3' || lpad(trunc(v_value)::text, 25, '0');
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_guard_operational_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare v_enforced boolean;
begin
  if pos.h133_internal_enabled() then return new; end if;
  select enforced into v_enforced from pos.inventory_contract_state where singleton;
  if not coalesce(v_enforced,false) then return new; end if;
  if new.deleted_at is null and new.record_model='v1' then raise exception 'V1_OPERATIONAL_FORBIDDEN'; end if;
  if new.deleted_at is null and new.record_model='v2' then
    if new.barcode_contract is distinct from 3 or new.barcode_code is distinct from pos.h133_barcode_v3_from_id(new.id)
       or jsonb_typeof(new.barcode_aliases)<>'array' then
      raise exception 'BARCODE_CONTRACT_V3_REQUIRED';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_operational_items(p_items jsonb, p_exchange boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_result jsonb;
begin
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' then raise exception 'INVALID_REFERENCE_ITEMS'; end if;
  if exists(
    select 1 from jsonb_array_elements(p_items)i join pos.products p on p.id=i->>'product_id'
    where p.record_model='v1' and p_exchange and coalesce(i->>'lado','')<>'devuelto'
  ) then raise exception 'V1_OPERATIONAL_FORBIDDEN'; end if;
  if exists(
    select 1 from jsonb_array_elements(p_items)i join pos.products p on p.id=i->>'product_id'
    left join pos.inventory_v1_v2_map m on m.source_v1_product_id=p.id
      and m.raw_size_value=i->>'talla'
      and (m.size_scale=coalesce(i->>'size_scale',m.size_scale))
    where p.record_model='v1' and m.target_v2_product_id is null
  ) then raise exception 'HISTORICAL_REFERENCE_MAP_MISSING'; end if;
  select coalesce(jsonb_agg(
    case when p.record_model='v1' then i||jsonb_build_object(
      'source_product_id',p.id,'product_id',m.target_v2_product_id,
      'barcode_code',target.barcode_code,'size_scale',m.size_scale)
    else i end order by ordinality),'[]'::jsonb) into v_result
  from jsonb_array_elements(p_items) with ordinality x(i,ordinality)
  left join pos.products p on p.id=i->>'product_id'
  left join pos.inventory_v1_v2_map m on m.source_v1_product_id=p.id and m.raw_size_value=i->>'talla'
  left join pos.products target on target.id=m.target_v2_product_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_exchange_checked(p_commit_id text, p_exchange jsonb, p_items jsonb, p_moves jsonb DEFAULT '[]'::jsonb, p_payment jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare v_prior jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_commit_id::text,p_exchange->>'id']::text[]);
  perform set_config('pos.h149_rpc','on',true);
  perform 1 from pos.exchange_commits where commit_id=p_commit_id for share;
  if found then
    v_prior:=pos.h94_commit_exchange_delegate(p_commit_id,p_exchange,p_items,
      p_moves,p_payment,p_seller_effects);
    if v_prior->>'error' is distinct from 'commit_mismatch' then return v_prior; end if;
  end if;
  return pos.h133_commit_exchange_delegate(p_commit_id,p_exchange,
    pos.h133_operational_items(p_items,true,p_exchange->>'origen_folio'),p_moves,p_payment,p_seller_effects);
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_return_checked(p_commit_id text, p_return jsonb, p_items jsonb, p_moves jsonb, p_stock_lines jsonb, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb, p_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare v_items jsonb;v_stock jsonb;v_prior jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_commit_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  -- Already confirmed historical payloads retain their original idempotency hash.
  perform 1 from pos.return_commits where commit_id=p_commit_id for share;
  if found then
    v_prior:=pos.h94_commit_return_delegate(p_commit_id,p_return,p_items,p_moves,
      p_stock_lines,p_client_effect,p_seller_effects,p_legacy);
    if v_prior->>'error' is distinct from 'commit_mismatch' then return v_prior; end if;
  end if;
  v_items:=pos.h133_operational_items(p_items,false,p_return->>'folio');
  v_stock:=pos.h133_operational_items(p_stock_lines,false);
  return pos.h133_commit_return_delegate(p_commit_id,p_return,v_items,p_moves,v_stock,
    p_client_effect,p_seller_effects,p_legacy);
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_execute_inventory_v3(p_operation_id uuid, p_manifest jsonb, p_existing jsonb, p_manifest_hash text, p_expected_v1_products integer, p_expected_v1_references integer, p_expected_v1_pieces integer, p_expected_v2_products integer, p_expected_v2_pieces integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos', 'auth'
AS $function$
declare
  v_plan jsonb; v_hash text; v_payload jsonb; v_payload_hash text; v_backup_id uuid;
  v_before_epoch bigint; v_after_epoch bigint; v_result jsonb; v_now timestamptz:=statement_timestamp();
  v_row record; v_count integer; v_pieces bigint;
begin
  if p_operation_id is null or jsonb_typeof(p_manifest)<>'array' or jsonb_typeof(p_existing)<>'array' then
    raise exception 'INVENTORY_V3_MANIFEST_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pos.h133-inventory-v3',0));
  lock table pos.products in share row exclusive mode;
  if exists(select 1 from pos.inventory_v3_operations where operation_id=p_operation_id) then
    return (select result||jsonb_build_object('idempotent',true) from pos.inventory_v3_operations where operation_id=p_operation_id);
  end if;
  v_plan:=jsonb_build_object('existing',p_existing,'migrated',p_manifest);
  v_hash:=pos.h133_payload_hash(v_plan);
  if v_hash<>coalesce(p_manifest_hash,'') then raise exception 'INVENTORY_V3_MANIFEST_HASH_MISMATCH'; end if;
  if jsonb_array_length(p_manifest)<>p_expected_v1_references
     or jsonb_array_length(p_existing)<>p_expected_v2_products then raise exception 'INVENTORY_V3_MANIFEST_COUNT_MISMATCH'; end if;
  if (select coalesce(sum(queue_pending),0)+coalesce(sum(queue_blocked),0) from pos.sync_devices)<>0 then
    raise exception 'INVENTORY_V3_QUEUE_NOT_DRAINED';
  end if;
  if exists(select 1 from pos.sales where estado='Apartado')
     or exists(select 1 from pos.loan_documents) then raise exception 'INVENTORY_V3_OPEN_OPERATION'; end if;
  select data_epoch into strict v_before_epoch from pos.system_manifest where singleton for update;
  if (select count(*) from pos.products where deleted_at is null and record_model='v1')<>p_expected_v1_products then
    raise exception 'INVENTORY_V3_V1_PRODUCT_CENSUS_CHANGED';
  end if;
  select count(*),coalesce(sum((e->>'stock')::integer),0) into v_count,v_pieces
  from pos.products p cross join lateral jsonb_array_elements(p.stock)e
  where p.deleted_at is null and p.record_model='v1' and (e->>'stock')::integer>0;
  if v_count<>(select count(*) from jsonb_array_elements(p_manifest)m where (m->>'stock')::integer>0)
     or v_pieces<>p_expected_v1_pieces then raise exception 'INVENTORY_V3_V1_STOCK_CENSUS_CHANGED'; end if;
  if (select count(*) from pos.products where deleted_at is null and record_model='v2')<>p_expected_v2_products
     or (select coalesce(sum(stock_quantity),0) from pos.products where deleted_at is null and record_model='v2')<>p_expected_v2_pieces then
    raise exception 'INVENTORY_V3_V2_CENSUS_CHANGED';
  end if;
  if exists(
    select 1 from jsonb_to_recordset(p_manifest) m(sourceProductId text,sizeScale text,rawSizeValue text,
      sourceSyncVersion bigint,stock integer,targetProductId text,barcodeCode text,physicalSignature text,
      sizeCategoryId text,visibleSku text,referenceFamilyId uuid)
    left join pos.products p on p.id=m.sourceProductId and p.deleted_at is null and p.record_model='v1'
    left join lateral(select e from jsonb_array_elements(p.stock)e where e->>'talla'=m.rawSizeValue
      and coalesce(e->>'escala','')=coalesce(m.sizeScale,'') limit 1)s on true
    where p.id is null or p.sync_version<>m.sourceSyncVersion or s.e is null
       or (s.e->>'stock')::integer<>m.stock or m.targetProductId !~* '^[a-f0-9-]{36}$'
       or m.barcodeCode<>pos.h133_barcode_v3_from_id(m.targetProductId)
       or nullif(m.physicalSignature,'') is null or nullif(m.sizeCategoryId,'') is null
  ) then raise exception 'INVENTORY_V3_SOURCE_OR_TARGET_CHANGED'; end if;
  if exists(
    select 1 from jsonb_to_recordset(p_existing)e(productId text,sourceSyncVersion bigint,oldBarcode text,
      newBarcode text,stock integer,physicalSignature text)
    left join pos.products p on p.id=e.productId and p.deleted_at is null and p.record_model='v2'
    where p.id is null or p.sync_version<>e.sourceSyncVersion or p.barcode_code<>e.oldBarcode
       or p.stock_quantity<>e.stock or p.physical_signature<>e.physicalSignature
       or e.newBarcode<>pos.h133_barcode_v3_from_id(e.productId)
  ) then raise exception 'INVENTORY_V3_EXISTING_V2_CHANGED'; end if;
  if (select count(*) from (select m->>'targetProductId' id from jsonb_array_elements(p_manifest)m
      union select e->>'productId' from jsonb_array_elements(p_existing)e)x)
     <>jsonb_array_length(p_manifest)+jsonb_array_length(p_existing)
     or exists(select 1 from pos.products p where p.id in(select m->>'targetProductId' from jsonb_array_elements(p_manifest)m)) then
    raise exception 'INVENTORY_V3_ID_COLLISION';
  end if;
  if (select count(*) from (select m->>'barcodeCode' code from jsonb_array_elements(p_manifest)m
      union select e->>'newBarcode' from jsonb_array_elements(p_existing)e)x)
     <>jsonb_array_length(p_manifest)+jsonb_array_length(p_existing) then raise exception 'INVENTORY_V3_BARCODE_COLLISION'; end if;

  v_payload:=jsonb_build_object(
    'format','balam-inventory-v3-backup-v1','operation_id',p_operation_id,'manifest_hash',v_hash,
    'products',(select jsonb_agg(to_jsonb(p) order by p.id) from pos.products p where p.deleted_at is null),
    'target_product_ids',(select jsonb_agg(m->>'targetProductId' order by m->>'targetProductId') from jsonb_array_elements(p_manifest)m),
    'system_manifest',(select to_jsonb(s) from pos.system_manifest s where singleton),
    'sync_devices',(select coalesce(jsonb_agg(to_jsonb(d) order by d.device_id),'[]'::jsonb) from pos.sync_devices d),
    'plan',v_plan);
  v_payload_hash:=pos.h133_payload_hash(v_payload);
  insert into pos.inventory_v3_backups(operation_id,manifest_hash,payload_hash,payload,verified_restorable)
  values(p_operation_id,v_hash,v_payload_hash,v_payload,
    jsonb_array_length(v_payload->'products')=p_expected_v1_products+p_expected_v2_products
    and jsonb_array_length(v_payload->'target_product_ids')=p_expected_v1_references)
  returning backup_id into v_backup_id;
  if not (select verified_restorable and payload_hash=pos.h133_payload_hash(payload)
      from pos.inventory_v3_backups where backup_id=v_backup_id) then raise exception 'INVENTORY_V3_BACKUP_NOT_RESTORABLE'; end if;

  perform set_config('pos.h133_internal','on',true);
  insert into pos.barcode_aliases(alias_code,product_id,contract_version,source,operation_id)
  select e.oldBarcode,e.productId,2,'v2-current-before-v3',p_operation_id
  from jsonb_to_recordset(p_existing)e(productId text,oldBarcode text)
  where nullif(e.oldBarcode,'') is not null;
  update pos.products p set barcode_aliases=jsonb_build_array(e.oldBarcode),barcode_code=e.newBarcode,
    barcode_contract=3,sync_version=p.sync_version+1,sync_base_version=null,
    sync_device_id='inventory-v3:'||p_operation_id,updated_at=v_now
  from jsonb_to_recordset(p_existing)e(productId text,oldBarcode text,newBarcode text)
  where p.id=e.productId;

  insert into pos.products(id,cat,manga,tela,color,cuello,modelo,nombre,orn,orn_colors,precio,costo,pop,
    stock,imagen,sku,barcode_urls,attrs,precios_talla,sync_version,sync_base_version,sync_device_id,deleted_at,
    record_model,size_category_id,size_code,size_scale,stock_quantity,barcode_code,ornament_color_codes,
    physical_signature,physical_identity_locked,reference_family_id,barcode_contract,barcode_aliases)
  select m.targetProductId,p.cat,p.manga,p.tela,p.color,p.cuello,p.modelo,p.nombre,p.orn,p.orn_colors,
    m.listPrice,p.costo,p.pop,jsonb_build_array(jsonb_build_object('talla',m.rawSizeValue,'escala',m.sizeScale,'stock',m.stock)),
    p.imagen,m.visibleSku,'{}'::jsonb,p.attrs||jsonb_build_object('__sizeCategoryId',m.sizeCategoryId,
      '__legacyVisibleSku',m.visibleSku,'__migratedFromV1',p.id),'{}'::jsonb,1,null,
    'inventory-v3:'||p_operation_id,null,'v2',m.sizeCategoryId,m.rawSizeValue,m.sizeScale,m.stock,
    m.barcodeCode,coalesce(m.ornamentColorCodes,'[]'::jsonb),m.physicalSignature,m.stock>0,
    m.referenceFamilyId,3,'[]'::jsonb
  from jsonb_to_recordset(p_manifest)m(sourceProductId text,sizeScale text,rawSizeValue text,stock integer,
    visibleSku text,listPrice numeric,sizeCategoryId text,ornamentColorCodes jsonb,physicalSignature text,
    targetProductId text,referenceFamilyId uuid,barcodeCode text)
  join pos.products p on p.id=m.sourceProductId;

  insert into pos.inventory_v1_v2_map(source_v1_product_id,size_scale,raw_size_value,target_v2_product_id,
    source_stock,historical_only,operation_id)
  select m.sourceProductId,m.sizeScale,m.rawSizeValue,m.targetProductId,m.stock,coalesce(m.historicalOnly,false),p_operation_id
  from jsonb_to_recordset(p_manifest)m(sourceProductId text,sizeScale text,rawSizeValue text,targetProductId text,
    stock integer,historicalOnly boolean);

  update pos.products p set stock=(select jsonb_agg(e.value||jsonb_build_object('stock',0) order by e.ordinality)
      from jsonb_array_elements(p.stock) with ordinality e(value,ordinality)),deleted_at=v_now,
    sync_version=p.sync_version+1,sync_base_version=null,sync_device_id='inventory-v3:'||p_operation_id,updated_at=v_now
  where p.deleted_at is null and p.record_model='v1';

  if exists(select 1 from pos.products where deleted_at is null and record_model='v1')
     or (select count(*) from pos.products where deleted_at is null and record_model='v2')
        <>p_expected_v2_products+p_expected_v1_references
     or (select coalesce(sum(stock_quantity),0) from pos.products where deleted_at is null and record_model='v2')
        <>p_expected_v1_pieces+p_expected_v2_pieces
     or exists(select barcode_code from pos.products where deleted_at is null and record_model='v2'
       group by barcode_code having count(*)>1)
     or exists(select physical_signature from pos.products where deleted_at is null and record_model='v2'
       group by physical_signature having count(*)>1) then raise exception 'INVENTORY_V3_POST_CENSUS_FAILED'; end if;

  alter table pos.products validate constraint products_v2_shape_check;
  update pos.inventory_contract_state set contract_version=3,enforced=true,operation_id=p_operation_id,
    manifest_hash=v_hash,activated_at=v_now,updated_at=v_now where singleton;
  update pos.system_manifest set data_epoch=data_epoch+1,schema_version=greatest(schema_version,20260830017300),
    sync_protocol_min=3,sync_protocol_current=3,updated_at=now() where singleton returning data_epoch into v_after_epoch;
  update pos.sync_devices set status='must_rebootstrap',data_epoch=v_after_epoch,
    queue_pending=0,queue_blocked=0 where device_id is not null and status <> 'revoked';
  v_result:=jsonb_build_object('ok',true,'operation_id',p_operation_id,'backup_id',v_backup_id,
    'manifest_hash',v_hash,'data_epoch_before',v_before_epoch,'data_epoch_after',v_after_epoch,
    'migrated_references',p_expected_v1_references,'existing_v2_rebarcoded',p_expected_v2_products,
    'active_v2',p_expected_v1_references+p_expected_v2_products,
    'pieces',p_expected_v1_pieces+p_expected_v2_pieces,'v1_active',0,'protocol',3,'barcode_contract',3);
  insert into pos.inventory_v3_operations(operation_id,backup_id,manifest_hash,status,
    data_epoch_before,data_epoch_after,result)
  values(p_operation_id,v_backup_id,v_hash,'completed',v_before_epoch,v_after_epoch,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_restore_inventory_v3_backup(p_backup_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos', 'auth'
AS $function$
declare v_backup pos.inventory_v3_backups%rowtype; v_row jsonb; v_epoch bigint;
begin
  if not pos.is_active_admin() or not pos.current_has_capability('settings.manage') then
    raise exception using errcode='42501',message='inventory_restore_requires_admin';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pos.h133-inventory-v3',0));
  select * into strict v_backup from pos.inventory_v3_backups where backup_id=p_backup_id for update;
  if v_backup.payload_hash<>pos.h133_payload_hash(v_backup.payload) or not v_backup.verified_restorable then
    raise exception 'INVENTORY_V3_BACKUP_NOT_RESTORABLE';
  end if;
  perform set_config('pos.h133_internal','on',true);
  update pos.inventory_contract_state set enforced=false,updated_at=now() where singleton;
  delete from pos.barcode_aliases where operation_id=v_backup.operation_id;
  delete from pos.inventory_v1_v2_map where operation_id=v_backup.operation_id;
  delete from pos.products where id in(select jsonb_array_elements_text(v_backup.payload->'target_product_ids'));
  for v_row in select value from jsonb_array_elements(v_backup.payload->'products') loop
    insert into pos.products select (jsonb_populate_record(null::pos.products,v_row)).*
    on conflict(id) do update set
      cat=excluded.cat,manga=excluded.manga,tela=excluded.tela,color=excluded.color,cuello=excluded.cuello,
      modelo=excluded.modelo,nombre=excluded.nombre,orn=excluded.orn,orn_colors=excluded.orn_colors,
      precio=excluded.precio,pop=excluded.pop,stock=excluded.stock,imagen=excluded.imagen,sku=excluded.sku,
      barcode_urls=excluded.barcode_urls,updated_at=excluded.updated_at,costo=excluded.costo,attrs=excluded.attrs,
      sync_version=excluded.sync_version,sync_base_version=excluded.sync_base_version,
      sync_device_id=excluded.sync_device_id,deleted_at=excluded.deleted_at,precios_talla=excluded.precios_talla,
      record_model=excluded.record_model,size_category_id=excluded.size_category_id,size_code=excluded.size_code,
      size_scale=excluded.size_scale,stock_quantity=excluded.stock_quantity,barcode_code=excluded.barcode_code,
      ornament_color_codes=excluded.ornament_color_codes,physical_signature=excluded.physical_signature,
      physical_identity_locked=excluded.physical_identity_locked,reference_family_id=excluded.reference_family_id,
      barcode_contract=excluded.barcode_contract,barcode_aliases=excluded.barcode_aliases;
  end loop;
  update pos.system_manifest s set data_epoch=(v_backup.payload->'system_manifest'->>'data_epoch')::bigint,
    schema_version=(v_backup.payload->'system_manifest'->>'schema_version')::bigint,
    sync_protocol_min=(v_backup.payload->'system_manifest'->>'sync_protocol_min')::integer,
    sync_protocol_current=(v_backup.payload->'system_manifest'->>'sync_protocol_current')::integer,
    updated_at=now() where singleton returning data_epoch into v_epoch;
  update pos.inventory_contract_state set contract_version=2,enforced=false,operation_id=null,
    manifest_hash=null,activated_at=null,updated_at=now() where singleton;
  update pos.inventory_v3_backups set restored_at=now() where backup_id=p_backup_id;
  update pos.inventory_v3_operations set status='restored',data_epoch_after=v_epoch,
    result=result||jsonb_build_object('restored_at',now()) where operation_id=v_backup.operation_id;
  return jsonb_build_object('ok',true,'backup_id',p_backup_id,'operation_id',v_backup.operation_id,
    'data_epoch',v_epoch,'restored_products',jsonb_array_length(v_backup.payload->'products'));
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_operational_items(p_items jsonb, p_exchange boolean, p_source_folio text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_items jsonb; v_out jsonb:='[]'; i jsonb; p pos.products%rowtype; v_matches bigint;
begin
 v_items:=pos.h133_operational_items(p_items,p_exchange);
 for i in select value from jsonb_array_elements(v_items) loop
  select * into p from pos.products where id=i->>'product_id' and record_model='v2' and deleted_at is null;
  if found and (not p_exchange or i->>'lado'='devuelto')
     and nullif(i->>'barcode_code','') is not null
     and i->>'barcode_code'<>p.barcode_code
     and coalesce(p.barcode_aliases,'[]'::jsonb) ? (i->>'barcode_code') then
   select count(*) into v_matches from (
    select s.line_id from pos.sale_items s
     where s.folio=p_source_folio and s.line_id=i->>'source_sale_line_id'
       and s.product_id=p.id and s.talla=i->>'talla' and s.barcode_code=i->>'barcode_code'
    union all
    select s.line_id from pos.exchange_items s join pos.exchanges e on e.id=s.exchange_id
     where e.origen_folio=p_source_folio and s.lado='entregado'
       and s.line_id=i->>'source_sale_line_id' and s.product_id=p.id
       and s.talla=i->>'talla' and s.barcode_code=i->>'barcode_code'
   ) exact_source;
   if v_matches=1 then
    i:=i||jsonb_build_object('source_barcode_code',i->>'barcode_code','barcode_code',p.barcode_code);
   end if;
  end if;
  v_out:=v_out||jsonb_build_array(i);
 end loop;
 return v_out;
end;
$function$

CREATE OR REPLACE FUNCTION pos.require_sale_stock_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  -- Apartados y cancelaciones no retiran inventario todavía.
  if new.estado in ('Apartado', 'Cancelado') then
    return new;
  end if;

  -- Una venta histórica ya existente sin operation_id continúa actualizable.
  if tg_op = 'UPDATE'
     and old.operation_id is null
     and new.operation_id is null then
    return new;
  end if;

  if nullif(trim(new.operation_id), '') is null
     or not exists (
       select 1
         from pos.stock_reservations r
        where r.operation_id = new.operation_id
          and r.folio = new.folio
     ) then
    raise exception 'La venta no tiene una reserva de inventario confirmada'
      using errcode = 'P0001',
            hint = 'Ejecute pos.reserve_sale_stock antes de guardar la venta';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.guard_entity_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare op text;
begin
  if pos.h133_internal_enabled() and tg_table_name='products' then return new; end if;
  if tg_op='INSERT' then
    new.sync_version:=1; new.sync_base_version:=null; new.updated_at:=now(); return new;
  end if;
  op:=case when new.deleted_at is not null and old.deleted_at is null then 'delete' else 'upsert' end;
  if new.sync_base_version is not null and new.sync_base_version<>old.sync_version then
    insert into pos.sync_conflicts(entity,entity_id,operation,expected_version,actual_version,
      attempted,current_row,device_id)
    values(tg_table_name,old.id,op,new.sync_base_version,old.sync_version,
      to_jsonb(new)-'sync_base_version',to_jsonb(old),new.sync_device_id);
    return old;
  end if;
  new.sync_version:=old.sync_version+1; new.sync_base_version:=null; new.updated_at:=now(); return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.soft_delete_entity(p_entity text, p_id text, p_base_version bigint, p_device_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  result jsonb;
begin
  if p_entity not in ('products', 'clients', 'sellers', 'promotions') then
    raise exception 'Entidad no permitida: %', p_entity;
  end if;

  execute format(
    'update pos.%I
       set deleted_at = now(),
           sync_base_version = $2,
           sync_device_id = $3
     where id = $1
     returning to_jsonb(%I.*)',
    p_entity, p_entity
  ) into result using p_id, coalesce(p_base_version, 0), p_device_id;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_legacy_return(p_commit_id text, p_return jsonb, p_items jsonb, p_moves jsonb, p_targets jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_result jsonb;
  v_conflicts jsonb := '[]'::jsonb;
  v_target record;
  v_products jsonb := '[]'::jsonb;
  v_clients jsonb := '[]'::jsonb;
  v_sellers jsonb := '[]'::jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_commit_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para adoptar devoluciones'
      using errcode = '42501';
  end if;

  if not coalesce((p_targets ->> 'complete')::boolean, false)
     or jsonb_typeof(p_targets -> 'products') <> 'array'
     or jsonb_array_length(p_targets -> 'products') = 0
     or jsonb_typeof(coalesce(p_targets -> 'sellers', '[]'::jsonb)) <> 'array' then
    return jsonb_build_object(
      'ok', false, 'error', 'legacy_context_incomplete'
    );
  end if;

  -- Bloqueo estable de todos los objetivos antes de comprobar versiones.
  perform p.id
    from pos.products p
   where p.id in (
     select x.id from jsonb_to_recordset(p_targets -> 'products')
       as x(id text, base_version bigint, stock jsonb)
   )
   order by p.id
   for update;

  for v_target in
    select * from jsonb_to_recordset(p_targets -> 'products')
      as x(id text, base_version bigint, stock jsonb)
  loop
    if not exists (
      select 1 from pos.products p
       where p.id = v_target.id
         and p.deleted_at is null
         and (
           p.sync_version = coalesce(v_target.base_version, 0)
           or (
             p.sync_version = coalesce(v_target.base_version, 0) + 1
             and p.stock = v_target.stock
           )
         )
    ) then
      v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
        'entity', 'products', 'id', v_target.id
      ));
    end if;
  end loop;

  if p_targets -> 'client' is not null
     and jsonb_typeof(p_targets -> 'client') = 'object' then
    perform 1 from pos.clients
     where id = p_targets -> 'client' ->> 'id'
     for update;
    if not exists (
      select 1 from pos.clients c
       where c.id = p_targets -> 'client' ->> 'id'
         and c.deleted_at is null
         and (
           c.sync_version = coalesce((p_targets -> 'client' ->> 'base_version')::bigint, 0)
           or (
             c.sync_version = coalesce((p_targets -> 'client' ->> 'base_version')::bigint, 0) + 1
             and c.total = coalesce((p_targets -> 'client' ->> 'total')::numeric, 0)
           )
         )
    ) then
      v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
        'entity', 'clients', 'id', p_targets -> 'client' ->> 'id'
      ));
    end if;
  end if;

  perform s.id
    from pos.sellers s
   where s.id in (
     select x.id from jsonb_to_recordset(coalesce(p_targets -> 'sellers', '[]'::jsonb))
       as x(id text, base_version bigint, ventas_mes numeric, comision_acum numeric)
   )
   order by s.id
   for update;

  for v_target in
    select * from jsonb_to_recordset(coalesce(p_targets -> 'sellers', '[]'::jsonb))
      as x(id text, base_version bigint, ventas_mes numeric, comision_acum numeric)
  loop
    if not exists (
      select 1 from pos.sellers s
       where s.id = v_target.id
         and s.active is true
         and s.deleted_at is null
         and (
           s.sync_version = coalesce(v_target.base_version, 0)
           or (
             s.sync_version = coalesce(v_target.base_version, 0) + 1
             and s.ventas_mes = v_target.ventas_mes
             and s.comision_acum = v_target.comision_acum
           )
         )
    ) then
      v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
        'entity', 'sellers', 'id', v_target.id
      ));
    end if;
  end loop;

  if jsonb_array_length(v_conflicts) > 0 then
    return jsonb_build_object(
      'ok', false, 'error', 'legacy_version_conflict',
      'conflicts', v_conflicts
    );
  end if;

  -- Cabecera/renglones/movimientos se adoptan mediante el mismo commit
  -- idempotente. Los objetivos se aplican en esta misma transacción.
  v_result := pos.commit_return(
    p_commit_id, p_return, p_items, p_moves,
    '[]'::jsonb, null, '[]'::jsonb, true
  );
  if not coalesce((v_result ->> 'ok')::boolean, false) then
    return v_result;
  end if;

  for v_target in
    select * from jsonb_to_recordset(p_targets -> 'products')
      as x(id text, base_version bigint, stock jsonb)
  loop
    update pos.products
       set stock = v_target.stock,
           sync_base_version = sync_version,
           sync_device_id = 'legacy-return:' || p_commit_id
     where id = v_target.id
       and sync_version = coalesce(v_target.base_version, 0);
  end loop;

  if p_targets -> 'client' is not null
     and jsonb_typeof(p_targets -> 'client') = 'object' then
    update pos.clients
       set total = coalesce((p_targets -> 'client' ->> 'total')::numeric, 0),
           sync_base_version = sync_version,
           sync_device_id = 'legacy-return:' || p_commit_id
     where id = p_targets -> 'client' ->> 'id'
       and sync_version = coalesce((p_targets -> 'client' ->> 'base_version')::bigint, 0);
  end if;

  for v_target in
    select * from jsonb_to_recordset(coalesce(p_targets -> 'sellers', '[]'::jsonb))
      as x(id text, base_version bigint, ventas_mes numeric, comision_acum numeric)
  loop
    update pos.sellers
       set ventas_mes = v_target.ventas_mes,
           comision_acum = v_target.comision_acum,
           sync_base_version = sync_version,
           sync_device_id = 'legacy-return:' || p_commit_id
     where id = v_target.id
       and sync_version = coalesce(v_target.base_version, 0);
  end loop;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
    into v_products from pos.products p
   where p.id in (
     select x.id from jsonb_to_recordset(p_targets -> 'products')
       as x(id text, base_version bigint, stock jsonb)
   );
  if p_targets -> 'client' is not null
     and jsonb_typeof(p_targets -> 'client') = 'object' then
    select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
      into v_clients from pos.clients c
     where c.id = p_targets -> 'client' ->> 'id';
  end if;
  select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
    into v_sellers from pos.sellers s
   where s.id in (
     select x.id from jsonb_to_recordset(coalesce(p_targets -> 'sellers', '[]'::jsonb))
       as x(id text, base_version bigint, ventas_mes numeric, comision_acum numeric)
   );

  return v_result || jsonb_build_object(
    'legacy_adopted', true,
    'products', v_products, 'clients', v_clients, 'sellers', v_sellers
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.reserve_folio_block(p_prefix text, p_business_date date, p_count integer DEFAULT 1, p_floor integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_prefix text;
  v_count integer;
  v_floor integer;
  v_to integer;
begin
  perform pos.assert_device_recovery_write(null::text,array[]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para reservar folios'
      using errcode = '42501';
  end if;

  v_prefix := left(upper(regexp_replace(coalesce(p_prefix, ''), '[^A-Za-z0-9]', '', 'g')), 6);
  if v_prefix = '' then
    return jsonb_build_object('ok', false, 'error', 'invalid_prefix');
  end if;
  if p_business_date is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_business_date');
  end if;

  v_count := least(greatest(coalesce(p_count, 1), 1), 100);
  v_floor := greatest(coalesce(p_floor, 0), 0);

  insert into pos.folio_counters as fc (prefix, business_date, last_seq)
  values (v_prefix, p_business_date, v_floor + v_count)
  on conflict (prefix, business_date) do update
    set last_seq = greatest(fc.last_seq, v_floor) + v_count,
        updated_at = now()
  returning fc.last_seq into v_to;

  return jsonb_build_object(
    'ok', true,
    'prefix', v_prefix,
    'business_date', to_char(p_business_date, 'YYYY-MM-DD'),
    'from', v_to - v_count + 1,
    'to', v_to
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.assert_device_recovery_write(p_device_id text, p_operation_ids text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare r pos.sync_device_recoveries%rowtype;
 device_row pos.sync_devices%rowtype; minimum_build text; actual_build text;
 h jsonb := coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}');
 d text := coalesce(nullif(p_device_id,''),h->>'x-balam-device-id');
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('pos.h149.recovery-fence',0));
 if exists(select 1 from pos.sync_quarantine_cases q where q.discarded_by_cleanup is not null
    and (q.operation_id=any(coalesce(p_operation_ids,'{}'::text[]))
      or coalesce(q.payload_summary->'operationIds','[]'::jsonb) ?| coalesce(p_operation_ids,'{}'::text[]))) then
   raise exception using errcode='P0001',message='Esta operación se descartó al limpiar los datos de prueba.',
     detail='TEST_PENDING_DISCARDED';
 end if;
 -- Legacy finance has no device argument. Resolve a uniquely reported origin,
 -- or the enclosing checked RPC. Missing identity can never bypass a directive.
 if d is null and coalesce(current_setting('pos.h149_rpc',true),'')='on' then
  d:=nullif(current_setting('pos.h149_device',true),'');
 end if;
 if d is null and cardinality(p_operation_ids)>0 then
  select min(device_id) into d from pos.sync_activity
   where operation_id=any(p_operation_ids) and user_id=auth.uid()
   having count(distinct device_id)=1;
 end if;
 if d is null and (exists(select 1 from pos.sync_device_recoveries where owner_id=auth.uid())
    or exists(select 1 from pos.sync_devices where user_id=auth.uid() and status='revoked')) then
  raise exception using errcode='P0001',message='BALAM necesita actualizarse antes de continuar.',
   detail='RECOVERY_DEVICE_ID_REQUIRED';
 end if;
 -- Serialize the administrative decision with this transaction's writes.
 select minimum_client_build into minimum_build from pos.system_manifest where singleton;
 actual_build := h->>'x-balam-client-build';
 if minimum_build is not null and actual_build is distinct from minimum_build then
  if actual_build is null or actual_build !~ '^\d{4}-\d{2}-\d{2}-h\d+$'
     or minimum_build !~ '^\d{4}-\d{2}-\d{2}-h\d+$'
     or row(left(actual_build,10),split_part(actual_build,'-h',2)::numeric)
       < row(left(minimum_build,10),split_part(minimum_build,'-h',2)::numeric) then
   raise exception using errcode='P0001',message='Actualiza BALAM antes de continuar.',detail='SYNC_PROTOCOL_OUTDATED';
  end if;
 end if;
 select * into device_row from pos.sync_devices where device_id=d for share;
 if device_row.status='revoked' then
  raise exception using errcode='P0001',message='Este equipo fue retirado. Un administrador debe reactivarlo.',detail='DEVICE_RETIRED';
 end if;
 if coalesce((device_row.metadata->>'reactivation_requires_sync')::boolean,false) then
  raise exception using errcode='P0001',message='Este equipo debe actualizar su información antes de guardar.',detail='REBOOTSTRAP_REQUIRED';
 end if;
 perform set_config('pos.h149_device',coalesce(d,''),true);
 for r in select * from pos.sync_device_recoveries
  where device_id=d or candidate_ids && coalesce(p_operation_ids,'{}'::text[])
  order by device_id for share
 loop
  if r.candidate_ids && coalesce(p_operation_ids,'{}'::text[]) then
   raise exception using errcode='P0001',message='BALAM necesita actualizarse antes de continuar.',
    detail='TEST_PENDING_DISCARDED';
  end if;
  if r.state<>'completed' or h->>'x-balam-recovery-token' is distinct from r.write_token::text then
   raise exception using errcode='P0001',message='BALAM necesita actualizarse antes de continuar.',
    detail='DEVICE_RECOVERY_REQUIRED';
  end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION pos.resolve_screen_permission(p_user_id uuid, p_screen_key text)
 RETURNS TABLE(allowed boolean, source text, role_code text, effect text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_email text;
  v_role text;
  v_effect text;
  v_allowed boolean;
  v_profile_active boolean := false;
  v_role_configured boolean := false;
begin
  if p_user_id is null or nullif(trim(p_screen_key), '') is null
     or not exists (
       select 1
       from pos.screen_permission_catalog c
       where c.screen_key = p_screen_key
         and c.active
         and c.is_leaf
     ) then
    return query
      select *
      from pos.resolve_screen_permission_precedence(
        false, null, null, null, false
      );
    return;
  end if;

  select u.email into v_email
  from auth.users u
  where u.id = p_user_id;

  v_profile_active := v_email is not null and exists (
    select 1
    from pos.sellers s
    where lower(s.email) = lower(v_email)
      and s.active is true
      and s.deleted_at is null
  );

  if v_profile_active then
    select o.effect into v_effect
    from pos.user_screen_permission_overrides o
    where o.user_id = p_user_id
      and o.screen_key = p_screen_key;

    select a.role_code into v_role
    from pos.user_permission_role_assignments a
    join pos.permission_roles r on r.code = a.role_code and r.active
    where a.user_id = p_user_id
      and a.active;

    if v_role is not null then
      select p.allowed into v_allowed
      from pos.role_screen_permissions p
      where p.role_code = v_role
        and p.screen_key = p_screen_key;
      v_role_configured := found;
    end if;
  end if;

  return query
    select *
    from pos.resolve_screen_permission_precedence(
      v_profile_active, v_effect, v_role, v_allowed, v_role_configured
    );
end;
$function$

CREATE OR REPLACE FUNCTION pos.guard_device_recovery_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare j jsonb; d text;
 h jsonb := coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}');
begin
 if TG_OP='DELETE' then j:=to_jsonb(OLD); else j:=to_jsonb(NEW); end if;
 -- A stored origin is not the identity of a later financial transaction.
 d:=h->>'x-balam-device-id';
 if coalesce(current_setting('pos.h149_rpc',true),'')<>'on' and d is null then
  d:=coalesce(j->>'sync_device_id',j->>'device_id');
 end if;
 perform pos.assert_device_recovery_write(d,array[j->>'operation_id',j->>'commit_id']);
 if TG_OP='DELETE' then return OLD; end if;
 return NEW;
end $function$

CREATE OR REPLACE FUNCTION pos.admin_apply_user_screen_permissions(p_target_user_id uuid, p_role_code text, p_overrides jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_batch uuid := extensions.gen_random_uuid();
  v_old_role text;
  v_key text;
  v_value jsonb;
  v_effect text;
  v_old_effect text;
begin
  if not pos.can_manage_screen_permissions(v_actor) then
    raise exception 'No autorizado para modificar permisos'
      using errcode = '42501';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_target_user_id) then
    raise exception 'La identidad Auth objetivo no existe'
      using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_overrides, '{}'::jsonb)) <> 'object' then
    raise exception 'Los overrides deben ser un objeto JSON'
      using errcode = '22023';
  end if;

  select a.role_code into v_old_role
  from pos.user_permission_role_assignments a
  where a.user_id = p_target_user_id;

  if p_role_code is null then
    delete from pos.user_permission_role_assignments
    where user_id = p_target_user_id;
  else
    if not exists (
      select 1 from pos.permission_roles r
      where r.code = p_role_code and r.active
    ) then
      raise exception 'Rol base inexistente o inactivo: %', p_role_code
        using errcode = '22023';
    end if;
    insert into pos.user_permission_role_assignments (
      user_id, role_code, updated_at, updated_by
    ) values (
      p_target_user_id, p_role_code, now(), v_actor
    )
    on conflict (user_id) do update set
      role_code = excluded.role_code,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by;
  end if;

  if v_old_role is distinct from p_role_code then
    insert into pos.permission_change_audit (
      batch_id, actor_user_id, target_user_id, change_kind,
      old_value, new_value
    ) values (
      v_batch, v_actor, p_target_user_id, 'user_role',
      to_jsonb(v_old_role), to_jsonb(p_role_code)
    );
  end if;

  for v_key, v_value in
    select e.key, e.value from jsonb_each(coalesce(p_overrides, '{}'::jsonb)) e
  loop
    if nullif(trim(v_key), '') is null then
      raise exception 'La clave de pantalla no puede estar vacía'
        using errcode = '22023';
    end if;

    select o.effect into v_old_effect
    from pos.user_screen_permission_overrides o
    where o.user_id = p_target_user_id and o.screen_key = v_key;

    if jsonb_typeof(v_value) = 'null' then
      v_effect := null;
      delete from pos.user_screen_permission_overrides
      where user_id = p_target_user_id and screen_key = v_key;
    else
      v_effect := trim(both '"' from v_value::text);
      if v_effect not in ('allow', 'deny') then
        raise exception 'Override inválido para %: %', v_key, v_effect
          using errcode = '22023';
      end if;
      insert into pos.user_screen_permission_overrides (
        user_id, screen_key, effect, updated_at, updated_by
      ) values (
        p_target_user_id, v_key, v_effect, now(), v_actor
      )
      on conflict (user_id, screen_key) do update set
        effect = excluded.effect,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;
    end if;

    if v_old_effect is distinct from v_effect then
      insert into pos.permission_change_audit (
        batch_id, actor_user_id, target_user_id, screen_key,
        change_kind, old_value, new_value
      ) values (
        v_batch, v_actor, p_target_user_id, v_key,
        'user_override', to_jsonb(v_old_effect), to_jsonb(v_effect)
      );
    end if;
  end loop;

  perform pos.assert_permission_admin_survives();
  return v_batch;
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_apply_role_screen_permissions(p_target_role_code text, p_permissions jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_batch uuid := extensions.gen_random_uuid();
  v_key text;
  v_value jsonb;
  v_allowed boolean;
  v_old_allowed boolean;
begin
  if not pos.can_manage_screen_permissions(v_actor) then
    raise exception 'No autorizado para modificar permisos'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from pos.permission_roles r
    where r.code = p_target_role_code and r.active
  ) then
    raise exception 'Rol base inexistente o inactivo: %', p_target_role_code
      using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_permissions, '{}'::jsonb)) <> 'object' then
    raise exception 'Los permisos deben ser un objeto JSON'
      using errcode = '22023';
  end if;

  for v_key, v_value in
    select e.key, e.value from jsonb_each(coalesce(p_permissions, '{}'::jsonb)) e
  loop
    select p.allowed into v_old_allowed
    from pos.role_screen_permissions p
    where p.role_code = p_target_role_code and p.screen_key = v_key;

    if jsonb_typeof(v_value) = 'null' then
      v_allowed := null;
      delete from pos.role_screen_permissions
      where role_code = p_target_role_code and screen_key = v_key;
    elsif jsonb_typeof(v_value) = 'boolean' then
      v_allowed := v_value::text::boolean;
      insert into pos.role_screen_permissions (
        role_code, screen_key, allowed, updated_at, updated_by
      ) values (
        p_target_role_code, v_key, v_allowed, now(), v_actor
      )
      on conflict (role_code, screen_key) do update set
        allowed = excluded.allowed,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;
    else
      raise exception 'Permiso de rol inválido para %', v_key
        using errcode = '22023';
    end if;

    if v_old_allowed is distinct from v_allowed then
      insert into pos.permission_change_audit (
        batch_id, actor_user_id, role_code, screen_key,
        change_kind, old_value, new_value
      ) values (
        v_batch, v_actor, p_target_role_code, v_key,
        'role_permission', to_jsonb(v_old_allowed), to_jsonb(v_allowed)
      );
    end if;
  end loop;

  perform pos.assert_permission_admin_survives();
  return v_batch;
end;
$function$

CREATE OR REPLACE FUNCTION pos.get_sync_device_recovery(p_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare r pos.sync_device_recoveries%rowtype;
begin
 if auth.uid() is null or not (pos.is_active_admin() or pos.is_active_seller()) then
  raise exception using errcode='42501',message='active_profile_required';
 end if;
 select * into r from pos.sync_device_recoveries where device_id=p_device_id;
 if not found then return null; end if;
 if r.owner_id<>auth.uid() then
  raise exception using errcode='42501',message='recovery_owner_required';
 end if;
 return jsonb_build_object('id',r.id,'device_id',r.device_id,'state',r.state,
  'expected_count',r.expected_count,'source_epoch',r.source_epoch,
  'protocol_version',r.protocol_version,'minimum_build',r.minimum_build,
  'candidate_ids',r.candidate_ids,'discarded_ids',r.discarded_ids,'evidence',r.evidence,
  'write_token',case when r.state='completed' then r.write_token else null end);
end $function$

CREATE OR REPLACE FUNCTION pos.complete_sync_device_recovery(p_device_id text, p_recovery_id uuid, p_cursors jsonb, p_epoch bigint, p_protocol integer, p_pending integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare r pos.sync_device_recoveries%rowtype; m pos.system_manifest%rowtype;
begin
 perform pos.get_sync_device_recovery(p_device_id);
 select * into strict r from pos.sync_device_recoveries where device_id=p_device_id for update;
 if r.id<>p_recovery_id then raise exception 'RECOVERY_ID_MISMATCH'; end if;
 if r.state='completed' then return pos.get_sync_device_recovery(p_device_id); end if;
 select * into strict m from pos.system_manifest where singleton for share;
 if r.state<>'captured' or p_pending is distinct from 0 or p_epoch is distinct from m.data_epoch
  or p_protocol is distinct from r.protocol_version or p_protocol<m.sync_protocol_min
  or p_protocol>m.sync_protocol_current or p_epoch<>r.source_epoch
  or p_cursors is null then raise exception 'RECOVERY_NOT_CONVERGED'; end if;
 if exists(select 1 from pos.sync_domain_versions v where v.domain<>'devices'
  and coalesce(m.domain_modes->>v.domain,'active')='active'
  and (p_cursors->>v.domain)::bigint is distinct from v.version) then
  raise exception 'RECOVERY_NOT_CONVERGED';
 end if;
 update pos.sync_device_recoveries set state='completed',completed_at=now(),
  receipt=jsonb_build_object('pending',0,'epoch',p_epoch,'protocol',p_protocol,'cursors',p_cursors)
  where device_id=p_device_id;
 return pos.get_sync_device_recovery(p_device_id);
end $function$

CREATE OR REPLACE FUNCTION pos.capture_sync_device_recovery(p_device_id text, p_recovery_id uuid, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare r pos.sync_device_recoveries%rowtype; ids text[]; clean jsonb;
begin
 perform pos.get_sync_device_recovery(p_device_id);
 select * into strict r from pos.sync_device_recoveries where device_id=p_device_id for update;
 if r.id<>p_recovery_id then raise exception 'RECOVERY_ID_MISMATCH'; end if;
 if r.state='completed' then return pos.get_sync_device_recovery(p_device_id); end if;
 if coalesce(p_evidence->>'build','') < r.minimum_build
  or coalesce((p_evidence->>'protocol')::integer,0)<>r.protocol_version
  or coalesce((p_evidence->>'epoch')::bigint,0)<>r.source_epoch
  or coalesce(p_evidence->>'queue_hash','') !~ '^[a-f0-9]{64}$'
  or jsonb_typeof(p_evidence->'operations') is distinct from 'array' then
  raise exception 'RECOVERY_EVIDENCE_INVALID';
 end if;
 select array_agg(x->>'id' order by x->>'id'),jsonb_agg(jsonb_build_object(
  'id',x->>'id','type',left(x->>'type',60),'epoch',(x->>'epoch')::bigint,
  'protocol',(x->>'protocol')::integer) order by x->>'id') into ids,clean
 from jsonb_array_elements(p_evidence->'operations') x;
 if cardinality(ids) is distinct from r.expected_count or not ids <@ r.candidate_ids
  or (select count(distinct x) from unnest(ids) x)<>r.expected_count
  or exists(select 1 from jsonb_array_elements(clean) x where
   coalesce((x->>'epoch')::bigint,0) not between 1 and r.source_epoch
   or coalesce((x->>'protocol')::integer,0) not between 1 and r.protocol_version) then
  raise exception 'RECOVERY_SCOPE_MISMATCH';
 end if;
 clean:=jsonb_build_object('build',p_evidence->>'build','protocol',r.protocol_version,
  'epoch',r.source_epoch,'queue_hash',p_evidence->>'queue_hash','operations',clean);
 if r.state='captured' then
  if r.evidence<>clean then raise exception 'RECOVERY_CAPTURE_MISMATCH'; end if;
 else
  update pos.sync_device_recoveries set state='captured',evidence=clean,discarded_ids=ids
   where device_id=p_device_id;
 end if;
 return pos.get_sync_device_recovery(p_device_id);
end $function$

CREATE OR REPLACE FUNCTION pos.prepare_sync_device_recovery(p_device_id text, p_expected_count integer, p_epoch bigint, p_protocol integer, p_minimum_build text, p_authorization text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare d pos.sync_devices%rowtype; ids text[]; result uuid;
begin
 if coalesce(auth.role(),'')<>'service_role' and not pos.is_active_admin() then
  raise exception using errcode='42501',message='admin_required';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pos.h149.recovery-fence',0));
 select * into strict d from pos.sync_devices where device_id=p_device_id for update;
 if d.queue_pending is distinct from p_expected_count or d.data_epoch is distinct from p_epoch
  or d.protocol_version is distinct from p_protocol
  or d.user_id is null or length(coalesce(p_authorization,''))<20 then
  raise exception 'RECOVERY_TARGET_MISMATCH';
 end if;
 if exists(select 1 from pos.sync_device_recoveries where device_id=p_device_id) then
  raise exception 'RECOVERY_ALREADY_PREPARED';
 end if;
 select array_agg(operation_id order by operation_id) into ids from pos.sync_activity
  where device_id=p_device_id and status<>'synced' and completed_at is null;
 if cardinality(ids)<p_expected_count or ids is null then raise exception 'RECOVERY_SCOPE_UNPROVEN'; end if;
 insert into pos.sync_device_recoveries(device_id,owner_id,expected_count,source_epoch,
  protocol_version,minimum_build,candidate_ids,created_by,authorization_reason)
 values(p_device_id,d.user_id,p_expected_count,p_epoch,p_protocol,p_minimum_build,ids,auth.uid(),p_authorization)
 returning id into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION pos.commit_layaway_liquidation_checked(p_commit_id text, p_operation_id text, p_folio text, p_payment jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text,p_commit_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  perform pos.require_current_capability('sales.collect');
  if p_context ? 'commission_rows'
     and p_context -> 'commission_rows' <> 'null'::jsonb
     and jsonb_typeof(p_context -> 'commission_rows') <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_commission_snapshot');
  end if;
  v_result := pos.commit_layaway_liquidation(
    p_commit_id, p_operation_id, p_folio, p_payment, p_seller_effects,
    p_context
  );
  -- H-69: el apartado comisiona AL LIQUIDARSE. El desglose por vendedor viaja en
  -- el contexto y se congela aqui, en la misma transaccion que confirma el pago.
  if coalesce((v_result ->> 'ok')::boolean, false)
     and p_context ? 'commission_rows'
     and jsonb_typeof(p_context -> 'commission_rows') = 'array' then
    update pos.sales
       set comisiones = p_context -> 'commission_rows'
     where folio = p_folio;
  end if;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_sync_screen_permission_catalog(p_entries jsonb, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_current_version bigint;
  v_next_version bigint;
begin
  if not pos.can_manage_screen_permissions(v_actor) then
    raise exception 'PERMISSION_ADMIN_UNAUTHORIZED'
      using errcode = '42501';
  end if;
  if jsonb_typeof(p_entries) <> 'array' then
    raise exception 'SCREEN_CATALOG_INVALID' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_entries) e
    where nullif(e ->> 'screen_key', '') is null
       or e ->> 'screen_key' !~ '^[a-z][a-z0-9_.-]{1,127}$'
       or jsonb_typeof(e -> 'is_leaf') <> 'boolean'
  ) then
    raise exception 'SCREEN_CATALOG_ENTRY_INVALID' using errcode = '22023';
  end if;
  if (
    select count(*) <> count(distinct e ->> 'screen_key')
    from jsonb_array_elements(p_entries) e
  ) then
    raise exception 'SCREEN_KEYS_DUPLICATED' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_entries) e
    where nullif(e ->> 'parent_key', '') is not null
      and not exists (
        select 1
        from jsonb_array_elements(p_entries) parent
        where parent ->> 'screen_key' = e ->> 'parent_key'
          and (parent ->> 'is_leaf')::boolean is false
      )
  ) then
    raise exception 'SCREEN_PARENT_UNKNOWN' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'pos.screen_permission_catalog', 56
  ));
  select s.catalog_version into v_current_version
  from pos.screen_permission_catalog_state s
  where s.singleton
  for update;
  if p_expected_version is distinct from v_current_version then
    raise exception 'SCREEN_CATALOG_VERSION_CONFLICT'
      using errcode = '40001';
  end if;
  v_next_version := v_current_version + 1;

  insert into pos.screen_permission_catalog (
    screen_key, parent_key, is_leaf, active, catalog_version, updated_at
  )
  select
    e ->> 'screen_key',
    nullif(e ->> 'parent_key', ''),
    (e ->> 'is_leaf')::boolean,
    true,
    v_next_version,
    now()
  from jsonb_array_elements(p_entries) e
  on conflict (screen_key) do update set
    parent_key = excluded.parent_key,
    is_leaf = excluded.is_leaf,
    active = true,
    catalog_version = excluded.catalog_version,
    updated_at = excluded.updated_at;

  update pos.screen_permission_catalog c
  set active = false,
      catalog_version = v_next_version,
      updated_at = now()
  where c.active
    and not exists (
      select 1
      from jsonb_array_elements(p_entries) e
      where e ->> 'screen_key' = c.screen_key
    );

  update pos.screen_permission_catalog_state
  set catalog_version = v_next_version,
      updated_at = now(),
      updated_by = v_actor
  where singleton;

  return jsonb_build_object(
    'catalog_version', v_next_version,
    'active_keys', (
      select count(*) from pos.screen_permission_catalog where active
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_apply_user_screen_permissions_checked(p_target_user_id uuid, p_role_code text, p_overrides jsonb, p_expected_version text, p_screen_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_current_version text;
  v_batch_id uuid;
  v_profile_active boolean;
begin
  if not pos.can_manage_screen_permissions(auth.uid()) then
    raise exception 'PERMISSION_ADMIN_UNAUTHORIZED'
      using errcode = '42501';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_target_user_id) then
    raise exception 'TARGET_USER_NOT_FOUND'
      using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_overrides, '{}'::jsonb)) <> 'object' then
    raise exception 'OVERRIDE_PAYLOAD_INVALID' using errcode = '22023';
  end if;
  if cardinality(coalesce(p_screen_keys, array[]::text[]))
     <> (
       select count(distinct k)
       from unnest(coalesce(p_screen_keys, array[]::text[])) k
     ) then
    raise exception 'SCREEN_KEYS_DUPLICATED' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_each(coalesce(p_overrides, '{}'::jsonb)) e
    left join pos.screen_permission_catalog c on c.screen_key = e.key
    where c.screen_key is null
  ) then
    raise exception 'SCREEN_KEY_UNKNOWN' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_each(coalesce(p_overrides, '{}'::jsonb)) e
    join pos.screen_permission_catalog c on c.screen_key = e.key
    where not c.active or not c.is_leaf
  ) then
    raise exception 'SCREEN_KEY_INACTIVE' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_each(coalesce(p_overrides, '{}'::jsonb)) e
    where jsonb_typeof(e.value) <> 'null'
      and trim(both '"' from e.value::text) not in ('allow', 'deny')
  ) then
    raise exception 'OVERRIDE_EFFECT_INVALID' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_target_user_id::text, 56)
  );
  v_current_version :=
    pos.user_screen_permissions_version(p_target_user_id);
  if nullif(p_expected_version, '') is null
     or p_expected_version is distinct from v_current_version then
    raise exception 'PERMISSION_VERSION_CONFLICT'
      using errcode = '40001',
            detail = jsonb_build_object(
              'expected', p_expected_version,
              'current', v_current_version
            )::text;
  end if;

  select exists (
    select 1
    from auth.users u
    join pos.sellers s on lower(s.email) = lower(u.email)
    where u.id = p_target_user_id
      and s.active is true
      and s.deleted_at is null
  ) into v_profile_active;
  if not v_profile_active then
    raise exception 'TARGET_USER_INACTIVE'
      using errcode = '55000';
  end if;

  v_batch_id := pos.admin_apply_user_screen_permissions(
    p_target_user_id,
    p_role_code,
    coalesce(p_overrides, '{}'::jsonb)
  );

  return jsonb_build_object(
    'batch_id', v_batch_id,
    'snapshot', pos.admin_user_permission_snapshot(
      p_target_user_id, p_screen_keys
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.settle_commission_checked(p_operation_id uuid, p_seller_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_hash text := md5(coalesce(p_seller_id, ''));
  v_existing pos.capability_operation_audit%rowtype;
  v_seller pos.sellers%rowtype;
  v_result jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  perform pos.require_current_capability('commissions.settle');
  if p_operation_id is null or nullif(trim(p_seller_id), '') is null then
    raise exception 'COMMISSION_OPERATION_INVALID' using errcode = '22023';
  end if;

  select * into v_existing
  from pos.capability_operation_audit
  where operation_id = p_operation_id;
  if found then
    if v_existing.capability_key <> 'commissions.settle'
       or v_existing.actor_user_id <> v_actor
       or v_existing.payload_hash <> v_hash then
      raise exception 'CAPABILITY_OPERATION_CONFLICT' using errcode = '22023';
    end if;
    return v_existing.result;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_seller_id, 5601));
  select * into v_seller
  from pos.sellers
  where id = p_seller_id and deleted_at is null
  for update;
  if not found then
    raise exception 'COMMISSION_SELLER_NOT_FOUND' using errcode = '22023';
  end if;

  if coalesce(v_seller.comision_acum, 0) > 0 then
    insert into pos.liquidations(id, seller_id, seller, monto, tipo, fecha)
    values (
      'liq-' || p_operation_id::text, v_seller.id, v_seller.nombre,
      round(v_seller.comision_acum, 2), 'liquidacion',
      to_char(statement_timestamp(), 'YYYY-MM-DD HH24:MI')
    );
  end if;
  update pos.sellers
  set comision_acum = 0
  where id = v_seller.id;

  v_result := jsonb_build_object(
    'operation_id', p_operation_id,
    'seller_id', v_seller.id,
    'seller', v_seller.nombre,
    'amount', round(coalesce(v_seller.comision_acum, 0), 2),
    'settled_at', statement_timestamp()
  );
  insert into pos.capability_operation_audit(
    operation_id, capability_key, actor_user_id, subject_key,
    payload_hash, result
  ) values (
    p_operation_id, 'commissions.settle', v_actor, v_seller.id,
    v_hash, v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_user_permission_editor_snapshot(p_target_user_id uuid, p_screen_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_snapshot jsonb;
  v_role_code text;
  v_permissions jsonb;
  v_roles jsonb;
begin
  if not pos.can_manage_screen_permissions(auth.uid()) then
    raise exception 'PERMISSION_ADMIN_UNAUTHORIZED'
      using errcode = '42501';
  end if;

  v_snapshot := pos.admin_user_permission_snapshot(
    p_target_user_id, p_screen_keys
  );
  v_role_code := v_snapshot ->> 'base_role';

  select coalesce(jsonb_agg(
    p || jsonb_build_object(
      'role_configured', rp.screen_key is not null,
      'role_allowed', coalesce(rp.allowed, false)
    )
    order by ordinality
  ), '[]'::jsonb)
  into v_permissions
  from jsonb_array_elements(v_snapshot -> 'permissions')
       with ordinality as item(p, ordinality)
  left join pos.role_screen_permissions rp
    on rp.role_code = v_role_code
   and rp.screen_key = p ->> 'screen_key';

  select coalesce(jsonb_agg(jsonb_build_object(
    'code', r.code, 'name', r.name
  ) order by r.name, r.code), '[]'::jsonb)
  into v_roles
  from pos.permission_roles r
  where r.active;

  return jsonb_set(
    jsonb_set(v_snapshot, '{permissions}', v_permissions),
    '{roles}', v_roles
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_layaway_liquidation(p_commit_id text, p_operation_id text, p_folio text, p_payment jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_sale pos.sales%rowtype;
  v_prior pos.layaway_liquidation_commits%rowtype;
  v_prior_reservation pos.stock_reservations%rowtype;
  v_has_prior_reservation boolean := false;
  v_derived_stock_lines jsonb := '[]'::jsonb;
  v_reserved_canonical_lines jsonb := '[]'::jsonb;
  v_payment jsonb;
  v_payment_id text;
  v_payment_at timestamptz;
  v_amount numeric;
  v_cash numeric;
  v_card numeric;
  v_transfer numeric;
  v_other numeric;
  v_balance numeric;
  v_deadline date;
  v_payload_hash text;
  v_items jsonb := '[]'::jsonb;
  v_payments jsonb := '[]'::jsonb;
  v_moves jsonb := '[]'::jsonb;
  v_stock_lines jsonb := '[]'::jsonb;
  v_sale_payload jsonb;
  v_core jsonb;
  v_before jsonb;
  v_state jsonb;
  v_stock_idempotent boolean := false;
  v_context jsonb;
  v_item_identities jsonb := '[]'::jsonb;
  v_commission_amount numeric := 0;
  v_commission_base text := 'neto';
  v_adopt_operation boolean := false;
  v_adopted_items jsonb := '[]'::jsonb;
  v_item record;
  v_identity_count integer;
  v_identity_product_id text;
  v_identity_sku text;
  v_identity_talla text;
  v_product_count integer;
  v_unique_product_id text;
  v_adopted_count integer := 0;
begin
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para liquidar apartados'
      using errcode = '42501';
  end if;
  if nullif(trim(p_commit_id), '') is null
     or nullif(trim(p_operation_id), '') is null
     or nullif(trim(p_folio), '') is null
     or jsonb_typeof(p_payment) <> 'object'
     or jsonb_typeof(p_seller_effects) <> 'array'
     or jsonb_typeof(coalesce(p_context, '{}'::jsonb)) <> 'object' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;

  v_item_identities := coalesce(p_context -> 'item_identities', '[]'::jsonb);
  if jsonb_typeof(v_item_identities) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_context',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;
  if (p_context ? 'commission_amount'
         and jsonb_typeof(p_context -> 'commission_amount') <> 'number')
     or (p_context ? 'commission_base'
         and jsonb_typeof(p_context -> 'commission_base') <> 'string')
     or exists (
       select 1 from jsonb_array_elements(v_item_identities) x
        where jsonb_typeof(x) <> 'object'
           or nullif(trim(x ->> 'product_id'), '') is null
           or (x ? 'sale_item_id' and x -> 'sale_item_id' <> 'null'::jsonb
               and (jsonb_typeof(x -> 'sale_item_id') <> 'number'
                    or x ->> 'sale_item_id' !~ '^[0-9]+$'))
     ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_context',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;
  select coalesce(jsonb_agg(x order by
      case when x ->> 'sale_item_id' ~ '^[0-9]+$'
        then (x ->> 'sale_item_id')::bigint end nulls last,
      x ->> 'product_id', x ->> 'sku', x ->> 'talla'), '[]'::jsonb)
    into v_item_identities
    from jsonb_array_elements(v_item_identities) x;
  v_commission_amount := coalesce((p_context ->> 'commission_amount')::numeric, 0);
  v_commission_base := coalesce(nullif(trim(p_context ->> 'commission_base'), ''), 'neto');
  if v_commission_amount < 0
     or round(v_commission_amount, 2) <> v_commission_amount
     or v_commission_base not in ('neto', 'bruto') then
    return jsonb_build_object('ok', false, 'error', 'invalid_commission_snapshot',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;
  v_context := jsonb_build_object(
    'item_identities', v_item_identities,
    'commission_amount', v_commission_amount,
    'commission_base', v_commission_base
  );

  v_payment_id := nullif(trim(p_payment ->> 'id'), '');
  if v_payment_id is null
     or nullif(trim(p_payment ->> 'fecha'), '') is null
     or nullif(trim(p_payment ->> 'metodo'), '') is null
     or (nullif(trim(p_payment ->> 'folio'), '') is not null
         and p_payment ->> 'folio' <> p_folio)
     or (nullif(trim(p_payment ->> 'tipo'), '') is not null
         and p_payment ->> 'tipo' <> 'liquidacion') then
    return jsonb_build_object('ok', false, 'error', 'invalid_payment',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;

  v_payment_at := (p_payment ->> 'fecha')::timestamptz;
  v_amount := coalesce((p_payment ->> 'monto')::numeric, 0);
  v_cash := coalesce((p_payment ->> 'efectivo')::numeric, 0);
  v_card := coalesce((p_payment ->> 'tarjeta')::numeric, 0);
  v_transfer := coalesce((p_payment ->> 'transferencia')::numeric, 0);
  v_other := coalesce((p_payment ->> 'otro')::numeric, 0);
  if v_amount <= 0 or least(v_cash, v_card, v_transfer, v_other) < 0
     or round(v_cash + v_card + v_transfer + v_other, 2) <> round(v_amount, 2) then
    return jsonb_build_object('ok', false, 'error', 'invalid_payment_parts',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;

  v_payment := jsonb_build_object(
    'id', v_payment_id, 'folio', p_folio,
    'fecha', p_payment ->> 'fecha', 'tipo', 'liquidacion',
    'metodo', p_payment ->> 'metodo', 'monto', v_amount,
    'efectivo', v_cash, 'tarjeta', v_card,
    'transferencia', v_transfer, 'otro', v_other
  );
  v_payload_hash := md5(jsonb_build_object(
    'contract', 'h65-v2', 'operation_id', p_operation_id,
    'folio', p_folio, 'payment', v_payment,
    'seller_effects', p_seller_effects, 'context', v_context
  )::text);

  -- Usa exactamente el mismo candado que reserve_sale_stock(); la lectura de
  -- idempotencia y el eventual descuento forman una sola seccion critica.
  perform pg_advisory_xact_lock(hashtext(p_operation_id));

  select * into v_prior from pos.layaway_liquidation_commits
   where commit_id = p_commit_id;
  if found then
    if v_prior.operation_id <> p_operation_id
       or v_prior.folio <> p_folio
       or v_prior.payload_hash <> v_payload_hash then
      return jsonb_build_object('ok', false, 'error', 'commit_mismatch',
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
    v_state := pos.sale_commit_authoritative_state(
      v_prior.operation_id, v_prior.folio, v_prior.stock_lines
    );
    return jsonb_build_object(
      'ok', true, 'idempotent', true, 'commit_idempotent', true,
      'liquidation_idempotent', true, 'stock_idempotent', true,
      'adopted_operation_id', v_prior.adopted_operation_id,
      'adopted_item_identities', v_prior.adopted_item_identities,
      'context', v_prior.context
    ) || v_state;
  end if;

  select * into v_prior from pos.layaway_liquidation_commits
   where operation_id = p_operation_id;
  if found then
    if v_prior.folio <> p_folio or v_prior.payload_hash <> v_payload_hash then
      return jsonb_build_object('ok', false, 'error', 'operation_mismatch',
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
    v_state := pos.sale_commit_authoritative_state(
      v_prior.operation_id, v_prior.folio, v_prior.stock_lines
    );
    return jsonb_build_object(
      'ok', true, 'idempotent', true, 'commit_idempotent', true,
      'liquidation_idempotent', true, 'stock_idempotent', true,
      'original_commit_id', v_prior.commit_id,
      'adopted_operation_id', v_prior.adopted_operation_id,
      'adopted_item_identities', v_prior.adopted_item_identities,
      'context', v_prior.context
    ) || v_state;
  end if;

  select * into v_sale from pos.sales
   where folio = p_folio for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'layaway_not_found',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;
  if v_sale.estado is distinct from 'Apartado' then
    return jsonb_build_object('ok', false, 'error', 'layaway_not_pending',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;
  if nullif(trim(v_sale.operation_id), '') is null then
    if exists (
      select 1 from pos.sales
       where operation_id = p_operation_id and folio <> p_folio
    ) or exists (
      select 1 from pos.stock_reservations
       where operation_id = p_operation_id and folio <> p_folio
    ) or exists (
      select 1 from pos.sale_commits
       where operation_id = p_operation_id and folio <> p_folio
    ) then
      return jsonb_build_object('ok', false, 'error', 'operation_id_conflict',
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
    v_adopt_operation := true;
  elsif v_sale.operation_id <> p_operation_id then
    return jsonb_build_object('ok', false, 'error', 'operation_mismatch',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;

  v_balance := round(coalesce(v_sale.saldo,
    v_sale.total - coalesce(v_sale.anticipo, 0)), 2);
  if v_balance <= 0 or round(v_amount, 2) <> v_balance then
    return jsonb_build_object(
      'ok', false, 'error', 'payment_balance_mismatch',
      'expected', v_balance, 'received', v_amount,
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null
    );
  end if;
  if exists (select 1 from pos.sale_payments where id = v_payment_id) then
    return jsonb_build_object('ok', false, 'error', 'payment_id_conflict',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;
  if not exists (select 1 from pos.sale_items where folio = p_folio)
     or exists (
       select 1 from pos.sale_items
        where folio = p_folio
          and (nullif(trim(talla), '') is null or qty <= 0)
     ) then
    return jsonb_build_object('ok', false,
      'error', 'layaway_items_invalid',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;

  -- Un renglon historico sin product_id solo se adopta por su PK remota, con
  -- SKU/talla exactos y cuando ese SKU identifica un solo producto vigente en
  -- el servidor. El contexto del navegador nunca decide entre duplicados.
  for v_item in
    select i.id, i.product_id, i.sku, i.talla
      from pos.sale_items i
     where i.folio = p_folio and nullif(trim(i.product_id), '') is null
     order by i.id
     for update
  loop
    select count(*), min(x.product_id), min(x.sku), min(x.talla)
      into v_identity_count, v_identity_product_id, v_identity_sku, v_identity_talla
      from jsonb_to_recordset(v_item_identities) as x(
        sale_item_id bigint, product_id text, sku text, talla text
      )
     where x.sale_item_id = v_item.id;
    if v_identity_count = 0 then
      return jsonb_build_object('ok', false,
        'error', 'layaway_item_identity_missing', 'sale_item_id', v_item.id,
        'sku', v_item.sku, 'talla', v_item.talla,
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
    if v_identity_count <> 1 then
      return jsonb_build_object('ok', false,
        'error', 'layaway_item_identity_ambiguous', 'sale_item_id', v_item.id,
        'sku', v_item.sku, 'talla', v_item.talla,
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
    if v_identity_sku is distinct from v_item.sku
       or v_identity_talla is distinct from v_item.talla then
      return jsonb_build_object('ok', false,
        'error', 'layaway_item_identity_mismatch', 'sale_item_id', v_item.id,
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;

    select count(*), min(p.id)
      into v_product_count, v_unique_product_id
      from pos.products p
     where p.deleted_at is null and p.sku = v_item.sku;
    if v_product_count = 0 then
      return jsonb_build_object('ok', false,
        'error', 'layaway_item_product_missing', 'sale_item_id', v_item.id,
        'sku', v_item.sku, 'stock_reserved', false,
        'stock_idempotent', false, 'reservation_operation_id', null);
    end if;
    if v_product_count <> 1 then
      return jsonb_build_object('ok', false,
        'error', 'layaway_item_sku_ambiguous', 'sale_item_id', v_item.id,
        'sku', v_item.sku, 'matches', v_product_count,
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
    if v_identity_product_id is distinct from v_unique_product_id then
      return jsonb_build_object('ok', false,
        'error', 'layaway_item_identity_mismatch', 'sale_item_id', v_item.id,
        'expected_product_id', v_unique_product_id,
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
    v_adopted_items := v_adopted_items || jsonb_build_array(jsonb_build_object(
      'sale_item_id', v_item.id, 'product_id', v_unique_product_id,
      'sku', v_item.sku, 'talla', v_item.talla
    ));
  end loop;

  -- El vendedor acreditado debe ser exactamente uno de los vendedores
  -- congelados en el apartado; omitir un efecto o acreditar a un tercero falla
  -- antes de tocar inventario.
  if exists (
    select 1 from jsonb_to_recordset(p_seller_effects) as e(id text)
     where nullif(trim(e.id), '') is null or not (v_sale.vendedores ? e.id)
  ) or (
    select count(*) <> count(distinct e.id)
      from jsonb_to_recordset(p_seller_effects) as e(id text)
  ) or exists (
    select 1 from jsonb_array_elements_text(v_sale.vendedores) sid
     where not exists (
       select 1 from jsonb_to_recordset(p_seller_effects) as e(id text)
        where e.id = sid
     )
  ) then
    return jsonb_build_object('ok', false, 'error', 'seller_effects_mismatch',
      'stock_reserved', false, 'stock_idempotent', false,
      'reservation_operation_id', null);
  end if;

  -- Las adopciones se hacen solo despues de validar toda la intencion y bajo el
  -- lock de la venta. Si el core devuelve un rechazo estructurado se revierten
  -- explicitamente; una excepcion posterior revierte la sentencia completa.
  if v_adopt_operation then
    update pos.sales set operation_id = p_operation_id
     where folio = p_folio and operation_id is null and estado = 'Apartado';
    if not found then
      return jsonb_build_object('ok', false, 'error', 'operation_adoption_conflict',
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
  end if;
  if jsonb_array_length(v_adopted_items) > 0 then
    update pos.sale_items i set product_id = x.product_id
      from jsonb_to_recordset(v_adopted_items) as x(
        sale_item_id bigint, product_id text, sku text, talla text
      )
     where i.id = x.sale_item_id and i.folio = p_folio
       and i.product_id is null and i.sku is not distinct from x.sku
       and i.talla is not distinct from x.talla;
    get diagnostics v_adopted_count = row_count;
    if v_adopted_count <> jsonb_array_length(v_adopted_items) then
      update pos.sale_items i set product_id = null
       where i.folio = p_folio and exists (
         select 1 from jsonb_to_recordset(v_adopted_items) as x(
           sale_item_id bigint, product_id text, sku text, talla text
         ) where x.sale_item_id = i.id and x.product_id = i.product_id
       );
      if v_adopt_operation then
        update pos.sales set operation_id = null
         where folio = p_folio and operation_id = p_operation_id;
      end if;
      return jsonb_build_object('ok', false, 'error', 'item_adoption_conflict',
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null);
    end if;
  end if;

  select coalesce(jsonb_agg(to_jsonb(i) - 'id' order by i.id), '[]'::jsonb)
    into v_items from pos.sale_items i where i.folio = p_folio;

  with requested as (
    select i.product_id, i.talla, sum(i.qty)::integer as qty
      from pos.sale_items i where i.folio = p_folio
     group by i.product_id, i.talla
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'product_id', product_id, 'talla', talla, 'qty', qty
    ) order by product_id, talla), '[]'::jsonb)
    into v_stock_lines from requested;

  v_derived_stock_lines := v_stock_lines;

  -- El advisory lock de operation_id se tomo antes de leer el apartado. La
  -- reserva y todos los productos implicados quedan ahora bloqueados dentro de
  -- esa misma seccion critica y en orden estable.
  select * into v_prior_reservation
    from pos.stock_reservations
   where operation_id = p_operation_id
   for update;
  v_has_prior_reservation := found;

  if v_has_prior_reservation then
    if v_prior_reservation.folio <> p_folio then
      if jsonb_array_length(v_adopted_items) > 0 then
        update pos.sale_items i set product_id = null
         where i.folio = p_folio and exists (
           select 1 from jsonb_to_recordset(v_adopted_items) as x(
             sale_item_id bigint, product_id text, sku text, talla text
           ) where x.sale_item_id = i.id and x.product_id = i.product_id
         );
      end if;
      if v_adopt_operation then
        update pos.sales set operation_id = null
         where folio = p_folio and operation_id = p_operation_id
           and estado = 'Apartado';
      end if;
      return jsonb_build_object(
        'ok', false, 'error', 'operation_mismatch',
        'reason', 'reservation_folio_mismatch',
        'stock_reserved', false, 'stock_idempotent', false,
        'reservation_operation_id', null
      );
    end if;
    if jsonb_typeof(v_prior_reservation.lines) <> 'array'
       or jsonb_array_length(v_prior_reservation.lines) = 0
       or exists (
         select 1 from jsonb_array_elements(v_prior_reservation.lines) x
          where jsonb_typeof(x) <> 'object'
             or jsonb_typeof(x -> 'product_id') <> 'string'
             or nullif(trim(x ->> 'product_id'), '') is null
             or jsonb_typeof(x -> 'talla') <> 'string'
             or nullif(trim(x ->> 'talla'), '') is null
             or not (x ? 'qty')
             or jsonb_typeof(x -> 'qty') <> 'number'
       ) then
      if jsonb_array_length(v_adopted_items) > 0 then
        update pos.sale_items i set product_id = null
         where i.folio = p_folio and exists (
           select 1 from jsonb_to_recordset(v_adopted_items) as x(
             sale_item_id bigint, product_id text, sku text, talla text
           ) where x.sale_item_id = i.id and x.product_id = i.product_id
         );
      end if;
      if v_adopt_operation then
        update pos.sales set operation_id = null
         where folio = p_folio and operation_id = p_operation_id
           and estado = 'Apartado';
      end if;
      return jsonb_build_object(
        'ok', false, 'error', 'operation_mismatch',
        'reason', 'reservation_lines_invalid',
        'stock_reserved', true, 'stock_idempotent', false,
        'reservation_operation_id', p_operation_id
      );
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_prior_reservation.lines) x
       where (x ->> 'qty')::numeric <= 0
          or trunc((x ->> 'qty')::numeric) <> (x ->> 'qty')::numeric
          or (x ->> 'qty')::numeric > 2147483647
    ) then
      if jsonb_array_length(v_adopted_items) > 0 then
        update pos.sale_items i set product_id = null
         where i.folio = p_folio and exists (
           select 1 from jsonb_to_recordset(v_adopted_items) as x(
             sale_item_id bigint, product_id text, sku text, talla text
           ) where x.sale_item_id = i.id and x.product_id = i.product_id
         );
      end if;
      if v_adopt_operation then
        update pos.sales set operation_id = null
         where folio = p_folio and operation_id = p_operation_id
           and estado = 'Apartado';
      end if;
      return jsonb_build_object(
        'ok', false, 'error', 'operation_mismatch',
        'reason', 'reservation_lines_invalid',
        'stock_reserved', true, 'stock_idempotent', false,
        'reservation_operation_id', p_operation_id
      );
    end if;
  end if;

  perform p.id
    from pos.products p
   where p.id in (
     select distinct x.product_id
       from jsonb_to_recordset(v_derived_stock_lines)
         as x(product_id text, talla text, qty integer)
     union
     select distinct x.product_id
       from jsonb_to_recordset(case when v_has_prior_reservation
              then v_prior_reservation.lines else '[]'::jsonb end)
         as x(product_id text, talla text, qty integer)
   )
   order by p.id
   for update;

  if v_has_prior_reservation then
    with canonical as (
      select x.product_id, x.talla, sum(x.qty)::integer as qty
        from jsonb_to_recordset(v_prior_reservation.lines)
          as x(product_id text, talla text, qty integer)
       group by x.product_id, x.talla
    )
    select coalesce(jsonb_agg(jsonb_build_object(
        'product_id', product_id, 'talla', talla, 'qty', qty
      ) order by product_id, talla), '[]'::jsonb)
      into v_reserved_canonical_lines
      from canonical;

    if v_reserved_canonical_lines <> v_derived_stock_lines then
      if jsonb_array_length(v_adopted_items) > 0 then
        update pos.sale_items i set product_id = null
         where i.folio = p_folio and exists (
           select 1 from jsonb_to_recordset(v_adopted_items) as x(
             sale_item_id bigint, product_id text, sku text, talla text
           ) where x.sale_item_id = i.id and x.product_id = i.product_id
         );
      end if;
      if v_adopt_operation then
        update pos.sales set operation_id = null
         where folio = p_folio and operation_id = p_operation_id
           and estado = 'Apartado';
      end if;
      return jsonb_build_object(
        'ok', false, 'error', 'operation_mismatch',
        'reason', 'reservation_lines_mismatch',
        'stock_reserved', true, 'stock_idempotent', false,
        'reservation_operation_id', p_operation_id,
        'reserved_lines', v_prior_reservation.lines,
        'reserved_canonical_lines', v_reserved_canonical_lines,
        'derived_lines', v_derived_stock_lines
      );
    end if;

    -- Igualdad canonica autoriza la adopcion; la representacion no se
    -- normaliza. El core, el ledger y authoritative_state reciben exactamente
    -- el valor JSON que reserve_sale_stock() persiste y compara.
    v_stock_lines := v_prior_reservation.lines;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'fecha', p_payment ->> 'fecha', 'tipo', 'Venta',
      'producto', i.nombre, 'sku', i.sku, 'cant', -i.qty,
      'ref', p_folio, 'product_id', i.product_id, 'talla', i.talla
    ) order by i.id), '[]'::jsonb)
    into v_moves from pos.sale_items i where i.folio = p_folio;

  select coalesce(jsonb_agg(x.payload order by x.fecha, x.id), '[]'::jsonb)
    into v_payments
    from (
      select p.id, p.fecha, to_jsonb(p) - 'created_at' as payload
        from pos.sale_payments p where p.folio = p_folio
      union all
      select v_payment_id, p_payment ->> 'fecha', v_payment
    ) x;

  v_deadline := case
    when v_sale.return_limit_days is null then null
    else (v_payment_at at time zone 'America/Hermosillo')::date
         + v_sale.return_limit_days
  end;
  v_sale_payload := to_jsonb(v_sale) || jsonb_build_object(
    'estado', 'Pagado', 'anticipo', v_sale.total, 'saldo', 0,
    'pago_efectivo', coalesce(v_sale.pago_efectivo, 0) + v_cash,
    'pago_otro', coalesce(v_sale.pago_otro, 0)
      + v_card + v_transfer + v_other,
    'return_expires_at', v_deadline,
    'operation_id', p_operation_id,
    'comision', v_commission_amount,
    'comision_base', v_commission_base
  );

  v_before := pos.sale_commit_authoritative_state(
    p_operation_id, p_folio, v_stock_lines
  );
  v_stock_idempotent := coalesce((v_before ->> 'stock_reserved')::boolean, false);

  -- Misma transaccion SQL: reserva, venta, renglones, movimiento, pagos y
  -- efectos. Una excepcion posterior revierte tambien la reserva y el stock.
  v_core := pos.commit_sale(
    p_commit_id, p_operation_id, v_sale_payload, v_items, v_moves, v_payments,
    v_stock_lines, true, null, p_seller_effects
  );
  if not coalesce((v_core ->> 'ok')::boolean, false) then
    if jsonb_array_length(v_adopted_items) > 0 then
      update pos.sale_items i set product_id = null
       where i.folio = p_folio and exists (
         select 1 from jsonb_to_recordset(v_adopted_items) as x(
           sale_item_id bigint, product_id text, sku text, talla text
         ) where x.sale_item_id = i.id and x.product_id = i.product_id
       );
    end if;
    if v_adopt_operation then
      update pos.sales set operation_id = null
       where folio = p_folio and operation_id = p_operation_id
         and estado = 'Apartado';
    end if;
    v_state := pos.sale_commit_authoritative_state(
      p_operation_id, p_folio, v_stock_lines
    );
    return v_core || v_state || jsonb_build_object(
      'stock_idempotent', v_stock_idempotent,
      'commit_idempotent', coalesce((v_core ->> 'idempotent')::boolean, false)
    );
  end if;

  -- Preserve the complete frozen line snapshot through liquidation (H-148).
  -- No new pricing, identity resolution or physical-card consumption occurs here.
  delete from pos.sale_items where folio = p_folio;
  insert into pos.sale_items (
    folio, product_id, sku, nombre, talla, qty, precio,
    precio_base, precio_original, promos, descuento_adicional,
    line_id, barcode_code, physical_attrs, list_price, effective_price,
    discount_snapshot, ornamento, orn_colors
  )
  select p_folio, x.product_id, x.sku, x.nombre, x.talla, x.qty, x.precio,
         x.precio_base, x.precio_original, x.promos, x.descuento_adicional,
         x.line_id, x.barcode_code, x.physical_attrs, x.list_price, x.effective_price,
         x.discount_snapshot, x.ornamento, x.orn_colors
    from jsonb_to_recordset(v_items) as x(
      folio text, product_id text, sku text, nombre text, talla text,
      qty integer, precio numeric, precio_base numeric,
      precio_original numeric, promos jsonb, descuento_adicional numeric,
      line_id text, barcode_code text, physical_attrs jsonb, list_price numeric,
      effective_price numeric, discount_snapshot jsonb, ornamento text, orn_colors jsonb
    );
  update pos.sales set
    descuento_adicional = v_sale.descuento_adicional,
    total_antes_descuento_adicional = v_sale.total_antes_descuento_adicional,
    descuentos_adicionales = v_sale.descuentos_adicionales,
    comision = v_commission_amount,
    comision_base = v_commission_base
  where folio = p_folio;

  -- El core historico ignora las dos columnas nuevas. El reemplazo exacto se
  -- hace con el mismo payload ya incluido en su hash y en la misma transaccion.
  delete from pos.movements where ref = p_folio and tipo = 'Venta';
  insert into pos.movements (
    fecha, tipo, producto, sku, cant, ref, product_id, talla
  )
  select x.fecha::timestamptz, 'Venta', x.producto, x.sku, x.cant,
         p_folio, x.product_id, x.talla
    from jsonb_to_recordset(v_moves) as x(
      fecha text, tipo text, producto text, sku text, cant integer, ref text,
      product_id text, talla text
    );

  insert into pos.layaway_liquidation_commits (
    commit_id, operation_id, folio, payment_id, payload_hash,
    stock_lines, context, adopted_operation_id, adopted_item_identities,
    actor_email
  ) values (
    p_commit_id, p_operation_id, p_folio, v_payment_id, v_payload_hash,
    v_stock_lines, v_context, v_adopt_operation, v_adopted_items,
    auth.jwt() ->> 'email'
  );

  v_state := pos.sale_commit_authoritative_state(
    p_operation_id, p_folio, v_stock_lines
  );
  return v_core || v_state || jsonb_build_object(
    'idempotent', coalesce((v_core ->> 'idempotent')::boolean, false),
    'commit_idempotent', coalesce((v_core ->> 'idempotent')::boolean, false),
    'liquidation_idempotent', false,
    'stock_idempotent', v_stock_idempotent,
    'adopted_operation_id', v_adopt_operation,
    'adopted_item_identities', v_adopted_items,
    'context', v_context
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.close_commission_period_internal(p_operation_id uuid, p_seller_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_hash text := md5(coalesce(array_to_string(p_seller_ids, ','), '*'));
  v_existing pos.capability_operation_audit%rowtype;
  v_seller pos.sellers%rowtype;
  v_total numeric := 0;
  v_count integer := 0;
  v_result jsonb;
begin
  perform pos.require_current_capability('commissions.close_period');
  if p_operation_id is null then
    raise exception 'COMMISSION_OPERATION_INVALID' using errcode = '22023';
  end if;

  select * into v_existing
  from pos.capability_operation_audit
  where operation_id = p_operation_id;
  if found then
    if v_existing.capability_key <> 'commissions.close_period'
       or v_existing.actor_user_id <> v_actor
       or v_existing.payload_hash <> v_hash then
      raise exception 'CAPABILITY_OPERATION_CONFLICT' using errcode = '22023';
    end if;
    return v_existing.result;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('commissions.close_period', 56));
  perform 1
  from pos.sellers s
  where s.deleted_at is null
    and (p_seller_ids is null or s.id = any(p_seller_ids))
  order by s.id
  for update;

  for v_seller in
    select s.*
    from pos.sellers s
    where s.deleted_at is null
      and (p_seller_ids is null or s.id = any(p_seller_ids))
    order by s.id
  loop
    if coalesce(v_seller.comision_acum, 0) > 0 then
      insert into pos.liquidations(id, seller_id, seller, monto, tipo, fecha)
      values (
        'cut-' || p_operation_id::text || '-' || v_seller.id,
        v_seller.id, v_seller.nombre, round(v_seller.comision_acum, 2),
        'corte', to_char(statement_timestamp(), 'YYYY-MM-DD HH24:MI')
      );
      v_total := v_total + v_seller.comision_acum;
      v_count := v_count + 1;
    end if;
    update pos.sellers
    set comision_acum = 0, ventas_mes = 0, ventas_num = 0
    where id = v_seller.id;
  end loop;

  v_result := jsonb_build_object(
    'operation_id', p_operation_id,
    'total', round(v_total, 2),
    'sellers', v_count,
    'period_started', current_date,
    'closed_at', statement_timestamp()
  );
  insert into pos.capability_operation_audit(
    operation_id, capability_key, actor_user_id, subject_key,
    payload_hash, result
  ) values (
    p_operation_id, 'commissions.close_period', v_actor, null,
    v_hash, v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.restrict_direct_commission_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if current_user in ('authenticated', 'anon')
     and (
       new.comision_acum is distinct from old.comision_acum
       or new.ventas_mes is distinct from old.ventas_mes
       or new.ventas_num is distinct from old.ventas_num
     ) then
    raise exception 'COMMISSION_RPC_REQUIRED' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.close_commission_period_checked(p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  return pos.close_commission_period_internal(p_operation_id, null);
end;
$function$

CREATE OR REPLACE FUNCTION pos.protect_sync_device_retirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
begin
 if current_user not in ('postgres','service_role') and (
   (old.status='revoked' and new.status is distinct from old.status)
   or (new.status='revoked' and old.status is distinct from new.status)
   or (new.metadata - array['last_heartbeat_error']) is distinct from (old.metadata - array['last_heartbeat_error'])
 ) then raise exception using errcode='42501',message='La administración del equipo requiere el Centro de equipos.'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION pos.require_sale_commit_capabilities(p_sale jsonb, p_payments jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_folio text := p_sale->>'folio';
  v_existing_layaway boolean;
  v_has_money boolean;
begin
  select coalesce(estado = 'Apartado', false) into v_existing_layaway
  from pos.sales where folio=v_folio;
  v_existing_layaway := coalesce(v_existing_layaway,false);
  v_has_money := jsonb_typeof(p_payments)='array'
    and jsonb_array_length(p_payments)>0
    and exists(
      select 1 from jsonb_array_elements(p_payments) p
      where coalesce((p->>'monto')::numeric,0)>0
    );
  if v_existing_layaway then
    perform pos.require_current_capability('sales.collect');
  else
    perform pos.require_current_capability('sales.create');
    if v_has_money then
      perform pos.require_current_capability('sales.collect');
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION pos.delete_product_checked(p_operation_id uuid, p_id text, p_base_version bigint, p_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_hash text := md5(jsonb_build_array(p_id,p_base_version,p_device_id)::text);
  v_result jsonb;
begin
  perform pos.require_current_capability('inventory.delete');
  if p_operation_id is null or nullif(trim(p_id), '') is null then
    raise exception 'INVALID_INVENTORY_DELETE' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtext(p_operation_id::text));
  select result into v_result from pos.capability_operation_audit
   where operation_id=p_operation_id and capability_key='inventory.delete'
     and payload_hash=v_hash;
  if found then return v_result; end if;
  if exists(select 1 from pos.capability_operation_audit where operation_id=p_operation_id) then
    raise exception 'INVENTORY_OPERATION_CONFLICT' using errcode='40001';
  end if;
  update pos.products set deleted_at=now(), sync_base_version=coalesce(p_base_version,0),
         sync_device_id=p_device_id where id=p_id returning to_jsonb(pos.products.*) into v_result;
  if v_result is null then raise exception 'PRODUCT_NOT_FOUND' using errcode='P0002'; end if;
  insert into pos.capability_operation_audit(
    operation_id, capability_key, actor_user_id, subject_key, payload_hash, result
  ) values (p_operation_id,'inventory.delete',v_actor,p_id,v_hash,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_loan_operation(p_operation_id uuid, p_action text, p_loan jsonb, p_expected_version bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
 v_actor uuid:=auth.uid(); v_id text:=p_loan->>'id'; v_folio text:=p_loan->>'folio';
 v_new_state text:=p_loan->>'estado'; v_old pos.loan_documents%rowtype;
 v_cap text:='inventory.loan.'||p_action; v_hash text;
 v_result jsonb; v_has_events boolean;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
 if p_action not in('deliver','return','shortage','edit','delete','reopen')
 or p_operation_id is null or nullif(trim(v_id),'') is null then
  raise exception 'INVALID_LOAN_OPERATION' using errcode='22023';
 end if;
 perform pos.require_current_capability(v_cap);
 perform pg_advisory_xact_lock(hashtext(v_id));
 v_hash:=md5(jsonb_build_array(p_action,p_loan,p_expected_version)::text);
 select result into v_result from pos.capability_operation_audit
  where operation_id=p_operation_id and capability_key=v_cap and payload_hash=v_hash;
 if found then return v_result; end if;
 if exists(select 1 from pos.capability_operation_audit where operation_id=p_operation_id)
 then raise exception 'LOAN_OPERATION_CONFLICT' using errcode='40001'; end if;
 select * into v_old from pos.loan_documents where id=v_id for update;

 if p_action='deliver' then
  -- H-62: la entrega admite los TRES estados del contrato, no sólo `pendiente`.
  -- La migración de los préstamos que vivían sólo en una terminal debe poder
  -- adoptar documentos ya cerrados —devueltos o dados por no devueltos—
  -- conservando su estado, sus devoluciones y sus fechas originales. Un
  -- documento adoptado con devoluciones nace con `has_events`, de modo que las
  -- guardas de edición y baja lo protegen igual que si hubiera nacido aquí.
  if found or v_new_state not in('pendiente','devuelto','no_devuelto')
  or nullif(trim(v_folio),'') is null
  or jsonb_typeof(p_loan->'lineas')<>'array'
  or jsonb_array_length(p_loan->'lineas')=0 then
   raise exception 'INVALID_LOAN_DELIVERY' using errcode='22023'; end if;
  v_has_events:=v_new_state<>'pendiente'
   or coalesce(jsonb_array_length(nullif(p_loan->'devoluciones','null'::jsonb)),0)>0;
  -- Choque de folio entre terminales. Se captura la violación de unicidad en
  -- lugar de comprobar antes con un `select`, porque así queda cubierta también
  -- la carrera entre dos entregas simultáneas: el candado de arriba serializa
  -- por `id`, no por folio.
  begin
   insert into pos.loan_documents(id,folio,state,document,has_events)
   values(v_id,v_folio,v_new_state,p_loan,v_has_events);
  exception when unique_violation then
   return jsonb_build_object('ok',false,'error','folio_conflict');
  end;
 else
  if not found or v_old.deleted_at is not null
  then raise exception 'LOAN_NOT_FOUND' using errcode='P0002'; end if;
  if v_old.version<>coalesce(p_expected_version,0)
  then raise exception 'LOAN_VERSION_CONFLICT' using errcode='40001'; end if;
  if p_action in('edit','delete') and
    (v_old.has_events or v_old.state<>'pendiente') then
   raise exception 'LOAN_ALREADY_HAS_EFFECTS' using errcode='23514'; end if;
  if p_action='return' then
   if v_old.state='devuelto' or v_new_state not in('pendiente','devuelto')
   then raise exception 'INVALID_LOAN_RETURN' using errcode='23514'; end if;
   if v_old.state='no_devuelto' then
    perform pos.require_current_capability('inventory.loan.reopen');
   end if;
   if v_new_state='devuelto' then
    perform pos.require_current_capability('inventory.loan.close');
   end if;
   v_has_events:=true;
  elsif p_action='shortage' then
   if v_old.state<>'pendiente' or v_new_state<>'no_devuelto'
   then raise exception 'INVALID_LOAN_SHORTAGE' using errcode='23514'; end if;
   perform pos.require_current_capability('inventory.loan.close');
   v_has_events:=true;
  elsif p_action='reopen' then
   if v_old.state<>'no_devuelto' or v_new_state<>'pendiente'
   then raise exception 'INVALID_LOAN_REOPEN' using errcode='23514'; end if;
   v_has_events:=true;
  elsif p_action='delete' then
   update pos.loan_documents set deleted_at=now(),version=version+1,updated_at=now()
    where id=v_id returning jsonb_build_object('id',id,'version',version,
      'deleted_at',deleted_at) into v_result;
  end if;
  if p_action<>'delete' then
   update pos.loan_documents set document=p_loan,state=v_new_state,
    has_events=coalesce(v_has_events,has_events),version=version+1,updated_at=now()
   where id=v_id returning document||jsonb_build_object('_loanVersion',version)
    into v_result;
  end if;
 end if;
 if p_action='deliver' then
  select document||jsonb_build_object('_loanVersion',version) into v_result
  from pos.loan_documents where id=v_id;
 end if;
 insert into pos.capability_operation_audit(operation_id,capability_key,
  actor_user_id,subject_key,payload_hash,result)
 values(p_operation_id,v_cap,v_actor,v_id,v_hash,v_result);
 return v_result;
end; $function$

CREATE OR REPLACE FUNCTION pos.sale_commit_authoritative_state(p_operation_id text, p_folio text, p_stock_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_reservation jsonb;
  v_products jsonb := '[]'::jsonb;
  v_sale jsonb;
  v_items jsonb := '[]'::jsonb;
  v_payments jsonb := '[]'::jsonb;
  v_movements jsonb := '[]'::jsonb;
begin
  select to_jsonb(r)
    into v_reservation
    from pos.stock_reservations r
   where r.operation_id = p_operation_id
     and r.folio = p_folio
     and r.lines = coalesce(p_stock_lines, '[]'::jsonb);

  if v_reservation is not null then
    select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
      into v_products
      from pos.products p
     where p.id in (
       select distinct x.product_id
         from jsonb_to_recordset(v_reservation -> 'lines')
           as x(product_id text, talla text, qty integer)
     );
  end if;

  select to_jsonb(s) into v_sale
    from pos.sales s where s.folio = p_folio;
  select coalesce(jsonb_agg(to_jsonb(i) order by i.id), '[]'::jsonb)
    into v_items from pos.sale_items i where i.folio = p_folio;
  select coalesce(jsonb_agg(to_jsonb(p) order by p.fecha, p.id), '[]'::jsonb)
    into v_payments from pos.sale_payments p where p.folio = p_folio;
  select coalesce(jsonb_agg(to_jsonb(m) order by m.id), '[]'::jsonb)
    into v_movements
    from pos.movements m
   where m.ref = p_folio and m.tipo = 'Venta';

  return jsonb_build_object(
    'stock_reserved', v_reservation is not null,
    'reservation_operation_id',
      case when v_reservation is null then null else p_operation_id end,
    'reservation', v_reservation,
    'products', v_products,
    'sale', v_sale,
    'items', v_items,
    'payments', v_payments,
    'movements', v_movements
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.h83_commit_sale_delegate(p_commit_id text, p_operation_id text, p_sale jsonb, p_items jsonb, p_moves jsonb, p_payments jsonb, p_stock_lines jsonb, p_reserve_stock boolean, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_folio text := p_sale ->> 'folio';
  v_result jsonb;
  v_before jsonb;
  v_state jsonb;
  v_prior_reserved boolean := false;
  v_existing_commit boolean := false;
  v_should_reserve boolean := false;
  v_effective_reserve boolean := false;
begin
  perform pos.require_sale_commit_capabilities(p_sale, p_payments);
  if p_sale ? 'comision' and p_sale -> 'comision' <> 'null'::jsonb then
    if jsonb_typeof(p_sale -> 'comision') <> 'number' then
      return jsonb_build_object('ok', false, 'error', 'invalid_commission_snapshot');
    end if;
    if (p_sale ->> 'comision')::numeric < 0
       or round((p_sale ->> 'comision')::numeric, 2)
          <> (p_sale ->> 'comision')::numeric then
      return jsonb_build_object('ok', false, 'error', 'invalid_commission_snapshot');
    end if;
  end if;
  if p_sale ? 'comision_base' and p_sale -> 'comision_base' <> 'null'::jsonb then
    if jsonb_typeof(p_sale -> 'comision_base') <> 'string'
       or nullif(trim(p_sale ->> 'comision_base'), '') is null
       or p_sale ->> 'comision_base' not in ('neto', 'bruto') then
      return jsonb_build_object('ok', false, 'error', 'invalid_commission_snapshot');
    end if;
  end if;
  if p_sale ? 'comisiones' and p_sale -> 'comisiones' <> 'null'::jsonb then
    if jsonb_typeof(p_sale -> 'comisiones') <> 'array' then
      return jsonb_build_object('ok', false, 'error', 'invalid_commission_snapshot');
    end if;
  end if;
  if p_sale ? 'comisiones_revertidas' and p_sale->'comisiones_revertidas'<>'null'::jsonb and jsonb_typeof(p_sale->'comisiones_revertidas')<>'array' then return jsonb_build_object('ok',false,'error','invalid_commission_snapshot'); end if;
  if nullif(trim(p_operation_id), '') is not null then
    perform pg_advisory_xact_lock(hashtext(p_operation_id));
  end if;
  v_should_reserve := coalesce(p_sale ->> 'estado', '')
      not in ('Apartado', 'Cancelado')
    and jsonb_typeof(p_stock_lines) = 'array'
    and jsonb_array_length(p_stock_lines) > 0;
  select exists(select 1 from pos.sale_commits where commit_id = p_commit_id)
    into v_existing_commit;
  v_effective_reserve := v_should_reserve;
  v_before := pos.sale_commit_authoritative_state(
    p_operation_id, v_folio, p_stock_lines
  );
  v_prior_reserved := coalesce((v_before ->> 'stock_reserved')::boolean, false);

  v_result := pos.commit_sale(
    p_commit_id, p_operation_id, p_sale, p_items, p_moves, p_payments,
    p_stock_lines, v_effective_reserve, p_client_effect, p_seller_effects
  );
  -- Compatibilidad con commits creados por el wrapper anterior: su hash podia
  -- contener la bandera cliente false aunque la reserva ya existiera. La
  -- primera llamada solo leyo el commit y devolvio commit_mismatch, por lo que
  -- es seguro probar el payload historico sin duplicar efectos.
  if v_existing_commit
     and v_result ->> 'error' = 'commit_mismatch'
     and v_effective_reserve is distinct from coalesce(p_reserve_stock, false) then
    v_result := pos.commit_sale(
      p_commit_id, p_operation_id, p_sale, p_items, p_moves, p_payments,
      p_stock_lines, coalesce(p_reserve_stock, false),
      p_client_effect, p_seller_effects
    );
  end if;
  if coalesce((v_result ->> 'ok')::boolean, false) then
    update pos.sales set
      comision = case when p_sale ? 'comision'
        then (p_sale ->> 'comision')::numeric else comision end,
      comision_base = case when p_sale ? 'comision_base'
        then nullif(trim(p_sale ->> 'comision_base'), '') else comision_base end,
      comisiones = case when p_sale ? 'comisiones'
        then p_sale -> 'comisiones' else comisiones end,
        comisiones_revertidas = case when p_sale ? 'comisiones_revertidas'
        then p_sale -> 'comisiones_revertidas' else comisiones_revertidas end
     where folio = v_folio and operation_id = p_operation_id;
  end if;
  v_state := pos.sale_commit_authoritative_state(
    p_operation_id, v_folio, p_stock_lines
  );
  return v_result || v_state || jsonb_build_object(
    'commit_idempotent', coalesce((v_result ->> 'idempotent')::boolean, false),
    'stock_idempotent', v_prior_reserved
      and coalesce((v_state ->> 'stock_reserved')::boolean, false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.reject_purged_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_kind text := tg_argv[0];
  v_identity text;
begin
  if v_kind = 'sale' then v_identity := new.operation_id;
  else v_identity := new.id;
  end if;
  if nullif(trim(coalesce(v_identity, '')), '') is null then
    return new;
  end if;
  if exists (
    select 1 from pos.purged_documents t
     where t.kind = v_kind and t.identity = v_identity
  ) then
    raise exception 'operation_purged'
      using errcode = 'P0001',
            detail = format('%s %s fue eliminado por una limpieza de datos de prueba', v_kind, v_identity),
            hint = 'Ese documento ya no existe: la terminal debe descartar la operacion pendiente';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.purge_test_data(p_purge_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_prior       pos.test_data_purges%rowtype;
  v_now         timestamptz := now();
  v_epoch       bigint;
  v_plan        jsonb;
  v_unapplied   jsonb;
  v_deleted     jsonb;
  v_kept        jsonb;
  v_left        jsonb;
  v_report      jsonb;
  v_fp_before   text;
  v_fp_after    text;
  v_pieces_before bigint;
  v_pieces_after  bigint;
  -- Plan de borrado: la identidad EXACTA de cada fila que se va a eliminar.
  v_sale_folios      text[];
  v_sale_ops         text[];
  v_sale_item_ids    bigint[];
  v_payment_ids      text[];
  v_return_ids       text[];
  v_return_item_ids  bigint[];
  v_exchange_ids     text[];
  v_exchange_item_ids bigint[];
  v_loan_ids         text[];
  v_liq_ids          text[];
  v_reservation_ops  text[];
  v_card_folios      text[];
  v_sale_commits     text[];
  v_return_commits   text[];
  v_exchange_commits text[];
  v_layaway_commits  text[];
  v_movement_ids     bigint[];
  v_client_ids       text[];
  v_folio_counters   jsonb;
  v_rows             bigint;
  v_ventas      bigint;
  v_apartados   bigint;
  v_cierres     bigint;
  v_comisiones  bigint;
  v_rec         record;
begin
  if not pos.is_active_admin() then
    raise exception 'purge_requires_admin'
      using errcode = '42501',
            detail = 'Solo un administrador activo puede borrar los datos de prueba';
  end if;
  if nullif(trim(coalesce(p_purge_id, '')), '') is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_purge_id');
  end if;

  perform pg_advisory_xact_lock(hashtext('pos.purge_test_data'));

  select * into v_prior from pos.test_data_purges where purge_id = p_purge_id;
  if found then
    return v_prior.report || jsonb_build_object(
      'ok', true, 'idempotent', true, 'purge_id', v_prior.purge_id,
      'epoch', v_prior.epoch, 'purged_at', v_prior.purged_at
    );
  end if;

  -- ── Plan de restauracion de existencias ───────────────────────────────────
  with sku_unique as (
    select p.sku, min(p.id) as product_id, count(*) as n
      from pos.products p
     where p.sku is not null and p.deleted_at is null
     group by p.sku
  ),
  doc_lines as (
    select 'venta'::text as origen, r.folio as ref,
           x.product_id as raw_id, null::text as sku, x.talla,
           x.qty::bigint as delta
      from pos.stock_reservations r
      cross join lateral jsonb_to_recordset(r.lines)
        as x(product_id text, talla text, qty integer)
    union all
    select 'venta', s.folio, i.product_id, i.sku, i.talla, i.qty::bigint
      from pos.sales s
      join pos.sale_items i on i.folio = s.folio
     where s.estado not in ('Apartado', 'Cancelado')
       and not exists (
         select 1 from pos.stock_reservations r where r.folio = s.folio
       )
    union all
    select 'devolucion', t.folio, ri.product_id, ri.sku, ri.talla,
           -ri.qty::bigint
      from pos.returns t
      join pos.return_items ri on ri.return_id = t.id
    union all
    select 'cambio', e.folio, null::text, xi.sku, xi.talla,
           case when xi.lado = 'devuelto' then -xi.qty::bigint else xi.qty::bigint end
      from pos.exchanges e
      join pos.exchange_items xi on xi.exchange_id = e.id
  ),
  resolved as (
    select d.origen, d.ref, d.sku, d.talla, d.delta,
           case
             when d.raw_id is not null
               and exists (select 1 from pos.products p where p.id = d.raw_id)
               then d.raw_id
             when u.n = 1 then u.product_id
             else null
           end as product_id,
           case
             when d.raw_id is not null
               and exists (select 1 from pos.products p where p.id = d.raw_id)
               then null
             when u.n = 1 then null
             when u.n > 1 then 'sku_ambiguo'
             else 'producto_inexistente'
           end as issue
      from doc_lines d
      left join sku_unique u on u.sku = d.sku
  ),
  deltas as (
    select product_id, talla, sum(delta)::bigint as delta
      from resolved
     where product_id is not null and nullif(trim(coalesce(talla, '')), '') is not null
     group by product_id, talla
    having sum(delta) <> 0
  )
  select jsonb_build_object(
    'deltas', coalesce((
      select jsonb_agg(jsonb_build_object(
               'product_id', product_id, 'talla', talla, 'delta', delta
             ) order by product_id, talla) from deltas), '[]'::jsonb),
    'ambiguos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'origen', origen, 'ref', ref, 'sku', sku, 'talla', talla
             ) order by ref, sku) from resolved where issue = 'sku_ambiguo'), '[]'::jsonb),
    'sin_producto', coalesce((
      select jsonb_agg(jsonb_build_object(
               'origen', origen, 'ref', ref, 'sku', sku, 'talla', talla
             ) order by ref, sku) from resolved
       where issue = 'producto_inexistente'), '[]'::jsonb)
  ) into v_plan;

  if jsonb_array_length(v_plan -> 'ambiguos') > 0 then
    return jsonb_build_object(
      'ok', false, 'error', 'identity_ambiguous',
      'message', 'Hay renglones cuyo SKU resuelve a mas de un producto',
      'ambiguos', v_plan -> 'ambiguos'
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'product_id', d.product_id, 'talla', d.talla, 'delta', d.delta)), '[]'::jsonb)
    into v_unapplied
    from jsonb_to_recordset(v_plan -> 'deltas')
      as d(product_id text, talla text, delta bigint)
   where not exists (
     select 1 from pos.products p
      cross join lateral jsonb_array_elements(p.stock) as e(value)
      where p.id = d.product_id and e.value ->> 'talla' = d.talla
   );

  -- ── Plan de BORRADO ───────────────────────────────────────────────────────
  -- Cada arreglo es la lista cerrada de filas que esta limpieza puede tocar.
  -- Ningun DELETE de abajo mira la tabla entera: todos preguntan por esta lista.
  select array_agg(s.folio order by s.folio),
         array_remove(array_agg(s.operation_id order by s.folio), null),
         count(*) filter (where s.estado <> 'Apartado'),
         count(*) filter (where s.estado = 'Apartado')
    into v_sale_folios, v_sale_ops, v_ventas, v_apartados
    from pos.sales s;
  v_sale_folios := coalesce(v_sale_folios, '{}'::text[]);
  v_sale_ops := coalesce(v_sale_ops, '{}'::text[]);

  select coalesce(array_agg(i.id order by i.id), '{}'::bigint[]) into v_sale_item_ids
    from pos.sale_items i;
  select coalesce(array_agg(p.id order by p.id), '{}'::text[]) into v_payment_ids
    from pos.sale_payments p;
  select coalesce(array_agg(t.id order by t.id), '{}'::text[]) into v_return_ids
    from pos.returns t;
  select coalesce(array_agg(ri.id order by ri.id), '{}'::bigint[]) into v_return_item_ids
    from pos.return_items ri;
  select coalesce(array_agg(e.id order by e.id), '{}'::text[]) into v_exchange_ids
    from pos.exchanges e;
  select coalesce(array_agg(xi.id order by xi.id), '{}'::bigint[]) into v_exchange_item_ids
    from pos.exchange_items xi;
  select coalesce(array_agg(l.id order by l.id), '{}'::text[]) into v_loan_ids
    from pos.loan_documents l;
  select coalesce(array_agg(q.id order by q.id), '{}'::text[]),
         count(*) filter (where q.tipo <> 'corte'),
         count(*) filter (where q.tipo = 'corte')
    into v_liq_ids, v_comisiones, v_cierres
    from pos.liquidations q;
  v_liq_ids := coalesce(v_liq_ids, '{}'::text[]);
  select coalesce(array_agg(r.operation_id order by r.operation_id), '{}'::text[])
    into v_reservation_ops from pos.stock_reservations r;
  select coalesce(array_agg(c.folio order by c.folio), '{}'::text[])
    into v_card_folios from pos.physical_card_redemptions c;
  select coalesce(array_agg(c.commit_id order by c.commit_id), '{}'::text[])
    into v_sale_commits from pos.sale_commits c;
  select coalesce(array_agg(c.commit_id order by c.commit_id), '{}'::text[])
    into v_return_commits from pos.return_commits c;
  select coalesce(array_agg(c.commit_id order by c.commit_id), '{}'::text[])
    into v_exchange_commits from pos.exchange_commits c;
  select coalesce(array_agg(c.commit_id order by c.commit_id), '{}'::text[])
    into v_layaway_commits from pos.layaway_liquidation_commits c;
  select coalesce(array_agg(m.id order by m.id), '{}'::bigint[])
    into v_movement_ids from pos.movements m
   where m.tipo in ('Venta', 'Devolución', 'Cambio (entra)', 'Cambio (sale)');
  select coalesce(array_agg(c.id order by c.id), '{}'::text[])
    into v_client_ids from pos.clients c
   where c.generic is not true and c.deleted_at is null;
  select coalesce(jsonb_agg(jsonb_build_object(
           'prefix', f.prefix, 'business_date', f.business_date)), '[]'::jsonb)
    into v_folio_counters from pos.folio_counters f;

  -- ── Snapshot ANTES ────────────────────────────────────────────────────────
  v_fp_before := pos.config_fingerprint();
  v_pieces_before := pos.total_stock_pieces();

  -- ── Restauracion de existencias ───────────────────────────────────────────
  for v_rec in
    select d.product_id, d.talla, d.delta,
           (e.value ->> 'stock')::bigint as actual,
           (e.ordinality - 1)::int as idx,
           count(*) over (partition by d.product_id, d.talla) as matches
      from jsonb_to_recordset(v_plan -> 'deltas')
        as d(product_id text, talla text, delta bigint)
      join pos.products p on p.id = d.product_id
      cross join lateral jsonb_array_elements(p.stock)
        with ordinality as e(value, ordinality)
     where e.value ->> 'talla' = d.talla
     order by d.product_id, d.talla
  loop
    if v_rec.matches > 1 then
      raise exception 'talla_ambigua'
        using errcode = 'P0001',
              detail = format('El producto %s tiene %s entradas con la talla %s',
                              v_rec.product_id, v_rec.matches, v_rec.talla);
    end if;
    update pos.products p
       set stock = jsonb_set(
             p.stock, array[v_rec.idx::text, 'stock'],
             to_jsonb(greatest(0, v_rec.actual + v_rec.delta)), false
           ),
           sync_base_version = null,
           sync_device_id = 'purge:' || p_purge_id
     where p.id = v_rec.product_id;
  end loop;

  -- ── Lapidas antes de borrar ───────────────────────────────────────────────
  insert into pos.purged_documents (kind, identity, purge_id)
  select 'sale', x, p_purge_id from unnest(v_sale_ops) as x
  on conflict (kind, identity) do nothing;
  insert into pos.purged_documents (kind, identity, purge_id)
  select 'return', x, p_purge_id from unnest(v_return_ids) as x
  on conflict (kind, identity) do nothing;
  insert into pos.purged_documents (kind, identity, purge_id)
  select 'exchange', x, p_purge_id from unnest(v_exchange_ids) as x
  on conflict (kind, identity) do nothing;
  insert into pos.purged_documents (kind, identity, purge_id)
  select 'loan', x, p_purge_id from unnest(v_loan_ids) as x
  on conflict (kind, identity) do nothing;

  -- ── Vaciado de lo operativo, fila por fila declarada ──────────────────────
  -- Cada sentencia pregunta por su plan y comprueba cuantas filas toco. Un
  -- descuadre aborta la transaccion entera: la condicion es explicita Y verificable.

  -- Va primero: `sale_folio` referencia la venta con ON DELETE RESTRICT.
  delete from pos.physical_card_redemptions c where c.folio = any(v_card_folios);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_card_folios) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('physical_card_redemptions: %s de %s', v_rows, cardinality(v_card_folios));
  end if;

  delete from pos.exchange_items xi where xi.id = any(v_exchange_item_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_exchange_item_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('exchange_items: %s de %s', v_rows, cardinality(v_exchange_item_ids));
  end if;

  delete from pos.exchanges e where e.id = any(v_exchange_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_exchange_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('exchanges: %s de %s', v_rows, cardinality(v_exchange_ids));
  end if;

  delete from pos.return_items ri where ri.id = any(v_return_item_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_return_item_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('return_items: %s de %s', v_rows, cardinality(v_return_item_ids));
  end if;

  delete from pos.returns t where t.id = any(v_return_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_return_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('returns: %s de %s', v_rows, cardinality(v_return_ids));
  end if;

  delete from pos.sale_payments p where p.id = any(v_payment_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_payment_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('sale_payments: %s de %s', v_rows, cardinality(v_payment_ids));
  end if;

  delete from pos.sale_items i where i.id = any(v_sale_item_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_sale_item_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('sale_items: %s de %s', v_rows, cardinality(v_sale_item_ids));
  end if;

  delete from pos.sales s where s.folio = any(v_sale_folios);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_sale_folios) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('sales: %s de %s', v_rows, cardinality(v_sale_folios));
  end if;

  delete from pos.loan_documents l where l.id = any(v_loan_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_loan_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('loan_documents: %s de %s', v_rows, cardinality(v_loan_ids));
  end if;

  delete from pos.liquidations q where q.id = any(v_liq_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_liq_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('liquidations: %s de %s', v_rows, cardinality(v_liq_ids));
  end if;

  delete from pos.stock_reservations r where r.operation_id = any(v_reservation_ops);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_reservation_ops) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('stock_reservations: %s de %s', v_rows, cardinality(v_reservation_ops));
  end if;

  delete from pos.sale_commits c where c.commit_id = any(v_sale_commits);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_sale_commits) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('sale_commits: %s de %s', v_rows, cardinality(v_sale_commits));
  end if;

  delete from pos.return_commits c where c.commit_id = any(v_return_commits);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_return_commits) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('return_commits: %s de %s', v_rows, cardinality(v_return_commits));
  end if;

  delete from pos.exchange_commits c where c.commit_id = any(v_exchange_commits);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_exchange_commits) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('exchange_commits: %s de %s', v_rows, cardinality(v_exchange_commits));
  end if;

  delete from pos.layaway_liquidation_commits c
   where c.commit_id = any(v_layaway_commits);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_layaway_commits) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('layaway_liquidation_commits: %s de %s', v_rows, cardinality(v_layaway_commits));
  end if;

  -- Consecutivo diario del folio (H-33): sin ventas no hay folio que reutilizar.
  delete from pos.folio_counters f
   where exists (
     select 1 from jsonb_to_recordset(v_folio_counters)
       as x(prefix text, business_date date)
      where x.prefix = f.prefix and x.business_date = f.business_date
   );
  get diagnostics v_rows = row_count;
  if v_rows <> jsonb_array_length(v_folio_counters) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('folio_counters: %s de %s', v_rows, jsonb_array_length(v_folio_counters));
  end if;

  -- Kardex: por IDENTIDAD de fila, no por tipo. 'Entrada', 'Ajuste' y
  -- 'Transferencia' nunca entraron al plan y por tanto no pueden tocarse.
  delete from pos.movements m where m.id = any(v_movement_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_movement_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('movements: %s de %s', v_rows, cardinality(v_movement_ids));
  end if;

  -- Clientes de prueba: lapida H-06, no borrado fisico.
  update pos.clients c
     set deleted_at = v_now, sync_base_version = null,
         sync_device_id = 'purge:' || p_purge_id
   where c.id = any(v_client_ids);
  get diagnostics v_rows = row_count;
  if v_rows <> cardinality(v_client_ids) then
    raise exception 'purge_delete_mismatch'
      using errcode = 'P0001', detail = format('clients: %s de %s', v_rows, cardinality(v_client_ids));
  end if;

  update pos.clients c
     set compras = 0, total = 0, ultima = null, sync_base_version = null,
         sync_device_id = 'purge:' || p_purge_id
   where c.generic is true;

  update pos.sellers s
     set ventas_mes = 0, ventas_num = 0, comision_acum = 0,
         sync_base_version = null, sync_device_id = 'purge:' || p_purge_id
   where s.ventas_mes <> 0 or s.ventas_num <> 0 or s.comision_acum <> 0;

  -- ── Verificacion DENTRO de la transaccion ─────────────────────────────────
  v_fp_after := pos.config_fingerprint();
  v_pieces_after := pos.total_stock_pieces();

  select jsonb_build_object(
    'ventas', (select count(*) from pos.sales),
    'renglones_venta', (select count(*) from pos.sale_items),
    'abonos', (select count(*) from pos.sale_payments),
    'devoluciones', (select count(*) from pos.returns),
    'cambios', (select count(*) from pos.exchanges),
    'prestamos', (select count(*) from pos.loan_documents),
    'comisiones', (select count(*) from pos.liquidations),
    'reservas', (select count(*) from pos.stock_reservations),
    'clientes', (select count(*) from pos.clients
                  where generic is not true and deleted_at is null),
    'movimientos_operativos', (select count(*) from pos.movements
      where tipo in ('Venta', 'Devolución', 'Cambio (entra)', 'Cambio (sale)')),
    'vendedores_con_acumulado', (select count(*) from pos.sellers
      where ventas_mes <> 0 or ventas_num <> 0 or comision_acum <> 0)
  ) into v_left;

  if (select bool_or(x.v <> '0')
        from jsonb_each_text(v_left) as x(k, v)) then
    raise exception 'purge_incomplete'
      using errcode = 'P0001', detail = v_left::text;
  end if;

  if v_fp_before is distinct from v_fp_after then
    raise exception 'purge_changed_configuration'
      using errcode = 'P0001',
            detail = format('huella antes=%s despues=%s', v_fp_before, v_fp_after);
  end if;

  -- ── Sello de la epoca ─────────────────────────────────────────────────────
  select greatest(
           (extract(epoch from v_now) * 1000)::bigint,
           coalesce(max(epoch), 0) + 1
         ) into v_epoch
    from pos.test_data_purges;

  v_deleted := jsonb_build_object(
    'ventas', v_ventas, 'apartados', v_apartados,
    'abonos', cardinality(v_payment_ids),
    'devoluciones', cardinality(v_return_ids),
    'cambios', cardinality(v_exchange_ids),
    'prestamos', cardinality(v_loan_ids),
    'clientes', cardinality(v_client_ids),
    'movimientos', cardinality(v_movement_ids),
    'comisiones', v_comisiones, 'cierres', v_cierres,
    'reservas', cardinality(v_reservation_ops)
  );
  v_kept := jsonb_build_object(
    'productos', (select count(*) from pos.products where deleted_at is null),
    'descuentos', (select count(*) from pos.promotions where deleted_at is null),
    'vendedores', (select count(*) from pos.sellers where deleted_at is null),
    'catalogos', (select count(*) from pos.lookup),
    'ajustes', (select count(*) from pos.settings where key <> '_resetMark'),
    'movimientos_inventario', (select count(*) from pos.movements),
    'permisos_por_rol', (select count(*) from pos.role_screen_permissions),
    'diagnosticos_sincronizacion', (select count(*) from pos.sync_conflicts)
  );

  v_report := jsonb_build_object(
    'ok', true, 'idempotent', false, 'purge_id', p_purge_id,
    'epoch', v_epoch, 'purged_at', v_now,
    'eliminados', v_deleted,
    'conservados', v_kept,
    'piezas_antes', v_pieces_before,
    'piezas_despues', v_pieces_after,
    'ajustes_inventario', v_plan -> 'deltas',
    'lineas_sin_producto', v_plan -> 'sin_producto',
    'tallas_sin_entrada', v_unapplied,
    'config_huella_antes', v_fp_before,
    'config_huella_despues', v_fp_after,
    'config_intacta', true,
    'verificacion', v_left
  );

  insert into pos.test_data_purges (purge_id, epoch, purged_at, actor_email, report)
  values (p_purge_id, v_epoch, v_now, auth.jwt() ->> 'email', v_report);

  insert into pos.settings (key, value, updated_at)
  values ('_resetMark', to_jsonb(v_epoch), v_now)
  on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at;

  return v_report;
end;
$function$

CREATE OR REPLACE FUNCTION pos.apply_commission_adjustment_checked(p_operation_id uuid, p_rows jsonb, p_motivo text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_hash text := md5(coalesce(p_rows::text, '[]'));
  v_existing pos.capability_operation_audit%rowtype;
  v_row record;
  v_total numeric := 0;
  v_count integer := 0;
  v_result jsonb;
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text]::text[]);
  perform pos.assert_device_recovery_write(x->>'sync_device_id',array[p_operation_id::text]::text[]) from jsonb_array_elements(p_rows) x;
  perform set_config('pos.h149_rpc','on',true);
  perform pos.require_current_capability('commissions.settle');
  if p_operation_id is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'COMMISSION_ADJUSTMENT_INVALID' using errcode = '22023';
  end if;

  -- Idempotencia por (operacion, actor, huella del payload), igual que el resto
  -- de capacidades de H-56: repetir la llamada devuelve el mismo resultado y no
  -- vuelve a acreditar.
  select * into v_existing
  from pos.capability_operation_audit
  where operation_id = p_operation_id;
  if found then
    if v_existing.capability_key <> 'commissions.adjust'
       or v_existing.actor_user_id <> v_actor
       or v_existing.payload_hash <> v_hash then
      raise exception 'CAPABILITY_OPERATION_CONFLICT' using errcode = '22023';
    end if;
    return v_existing.result;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('commissions.adjust', 69));

  for v_row in
    select x.seller_id, x.monto, x.ventas
      from jsonb_to_recordset(p_rows)
        as x(seller_id text, monto numeric, ventas integer)
  loop
    if nullif(trim(v_row.seller_id), '') is null or coalesce(v_row.monto, 0) <= 0 then
      continue;
    end if;
    update pos.sellers
       set comision_acum = round(coalesce(comision_acum, 0) + v_row.monto, 2)
     where id = v_row.seller_id and deleted_at is null;
    if not found then
      raise exception 'COMMISSION_SELLER_NOT_FOUND' using errcode = '22023';
    end if;
    insert into pos.liquidations(id, seller_id, seller, monto, tipo, fecha)
    select 'adj-' || p_operation_id::text || '-' || v_row.seller_id,
           s.id, s.nombre, round(v_row.monto, 2), 'ajuste',
           to_char(statement_timestamp(), 'YYYY-MM-DD HH24:MI')
      from pos.sellers s where s.id = v_row.seller_id
    on conflict (id) do nothing;
    v_total := v_total + v_row.monto;
    v_count := v_count + 1;
  end loop;

  insert into pos.commission_adjustments(
    operation_id, actor_user_id, motivo, total, vendedores, detalle
  ) values (
    p_operation_id, v_actor, nullif(trim(coalesce(p_motivo, '')), ''),
    round(v_total, 2), v_count, p_rows
  );

  v_result := jsonb_build_object(
    'operation_id', p_operation_id,
    'total', round(v_total, 2),
    'sellers', v_count,
    'applied_at', statement_timestamp()
  );
  insert into pos.capability_operation_audit(
    operation_id, capability_key, actor_user_id, subject_key, payload_hash, result
  ) values (
    p_operation_id, 'commissions.adjust', v_actor, null, v_hash, v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.assert_sync_write_context(p_protocol_version integer, p_data_epoch bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_manifest pos.system_manifest%rowtype;
begin
  select * into v_manifest from pos.system_manifest where singleton for share;
  if not found then raise exception 'sync_manifest_missing'; end if;
  if p_protocol_version < v_manifest.sync_protocol_min
     or p_protocol_version > v_manifest.sync_protocol_current then
    raise exception 'sync_protocol_incompatible';
  end if;
  if p_data_epoch <> v_manifest.data_epoch then
    raise exception 'sync_epoch_mismatch';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_config(p_operation_id text, p_expected_version bigint, p_device_id text, p_lookup jsonb, p_settings jsonb, p_protocol_version integer, p_data_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'auth', 'pg_temp'
AS $function$
declare
  v_manifest pos.system_manifest%rowtype;
  v_version bigint;
  v_hash text;
  v_prior pos.config_commits%rowtype;
begin
  perform pos.assert_device_recovery_write(p_device_id,array[p_operation_id::text]::text[]);
  perform set_config('pos.h149_rpc','on',true);
  if not pos.is_active_admin()
     or not pos.current_has_capability('settings.manage') then
    raise exception using errcode='42501', message='settings_manage_required';
  end if;
  if p_operation_id is null or p_operation_id='' then
    raise exception using errcode='22023', message='operation_id_required';
  end if;
  if jsonb_typeof(p_lookup) <> 'array' or jsonb_array_length(p_lookup)=0
     or jsonb_typeof(p_settings) <> 'array' then
    raise exception using errcode='22023', message='invalid_config_snapshot';
  end if;

  select * into v_manifest from pos.system_manifest where singleton for share;
  if p_protocol_version < v_manifest.sync_protocol_min
     or p_protocol_version > v_manifest.sync_protocol_current then
    raise exception using errcode='P0001', message='sync_protocol_outdated';
  end if;
  if p_data_epoch <> v_manifest.data_epoch then
    raise exception using errcode='P0001', message='rebootstrap_required';
  end if;

  v_hash := md5(p_lookup::text || E'\n' || p_settings::text);
  select * into v_prior from pos.config_commits where operation_id=p_operation_id;
  if found then
    if v_prior.payload_hash <> v_hash then
      raise exception using errcode='P0001', message='config_commit_mismatch';
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,
      'version',v_prior.committed_version,'data_epoch',v_manifest.data_epoch);
  end if;

  perform pg_advisory_xact_lock(hashtextextended('pos.config',0));
  select version into v_version from pos.config_sync_state where singleton for update;
  if coalesce(p_expected_version,0) <> v_version then
    return jsonb_build_object('ok',false,'error','config_version_conflict',
      'version',v_version,'data_epoch',v_manifest.data_epoch);
  end if;

  insert into pos.lookup(kind,code,label,active,meta,sort_order,updated_at)
  select x.kind,x.code,x.label,coalesce(x.active,true),coalesce(x.meta,'{}'::jsonb),
    coalesce(x.sort_order,0),now()
  from jsonb_to_recordset(p_lookup) as x(
    kind text, code text, label text, active boolean, meta jsonb, sort_order integer)
  on conflict(kind,code) do update set label=excluded.label, active=excluded.active,
    meta=excluded.meta, sort_order=excluded.sort_order, updated_at=now();

  delete from pos.lookup l where not exists(
    select 1 from jsonb_to_recordset(p_lookup) as x(kind text,code text)
    where x.kind=l.kind and x.code=l.code
  );

  insert into pos.settings(key,value,updated_at)
  select x.key,x.value,now()
  from jsonb_to_recordset(p_settings) as x(key text,value jsonb)
  on conflict(key) do update set value=excluded.value,updated_at=now();

  update pos.config_sync_state set version=version+1,updated_at=now()
  where singleton returning version into v_version;
  insert into pos.config_commits(operation_id,payload_hash,committed_version,device_id)
  values(p_operation_id,v_hash,v_version,p_device_id);
  return jsonb_build_object('ok',true,'idempotent',false,'version',v_version,
    'data_epoch',v_manifest.data_epoch);
end;
$function$

CREATE OR REPLACE FUNCTION pos.save_products_checked_v2(p_operation_id uuid, p_rows jsonb, p_protocol_version integer, p_data_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
begin
  perform pos.assert_device_recovery_write(null::text,array[p_operation_id::text]::text[]);
  perform pos.assert_device_recovery_write(x->>'sync_device_id',array[p_operation_id::text]::text[]) from jsonb_array_elements(p_rows) x;
  perform set_config('pos.h149_rpc','on',true);
  perform pos.assert_sync_write_context(p_protocol_version,p_data_epoch);
  return pos.save_products_checked(p_operation_id,p_rows);
end;
$function$

CREATE OR REPLACE FUNCTION pos.delete_product_checked_v2(p_operation_id uuid, p_id text, p_base_version bigint, p_device_id text, p_protocol_version integer, p_data_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare v_family uuid; v_result jsonb;
begin
  perform pos.assert_device_recovery_write(p_device_id,array[p_operation_id::text]::text[]);
