CREATE OR REPLACE FUNCTION pos.establish_sync_point_zero(p_protocol_version integer, p_expected_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_epoch bigint; v_products bigint; v_pieces numeric; v_fingerprint text;
begin
  if not pos.is_active_admin() or not pos.current_has_capability('settings.manage') then
    raise exception 'sync_point_zero_forbidden';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pos.sync.point-zero',0));
  perform pos.assert_sync_write_context(p_protocol_version,p_expected_epoch);
  select count(distinct p.id), coalesce(sum(case when p.record_model='v2'
      then coalesce(p.stock_quantity,0) else coalesce((s.item->>'stock')::numeric,0) end),0)
    into v_products,v_pieces from pos.products p
    left join lateral jsonb_array_elements(case when p.record_model='v2' then '[]'::jsonb else coalesce(p.stock,'[]'::jsonb) end) s(item) on true
    where p.deleted_at is null;
  select md5(coalesce(string_agg(to_jsonb(p)::text,'|' order by p.id),''))
    into v_fingerprint from pos.products p where p.deleted_at is null;
  update pos.system_manifest set data_epoch=data_epoch+1,updated_at=now()
    where singleton returning data_epoch into v_epoch;
  insert into pos.inventory_sync_baselines(data_epoch,product_count,piece_count,fingerprint,created_by)
  values(v_epoch,v_products,v_pieces,v_fingerprint,auth.uid());
  update pos.sync_devices set status='must_rebootstrap' where device_id is not null and status <> 'revoked';
  perform pos.bump_sync_domain('products','point-zero');
  perform pos.bump_sync_domain('config','point-zero');
  return jsonb_build_object('ok',true,'data_epoch',v_epoch,'product_count',v_products,
    'piece_count',v_pieces,'fingerprint',v_fingerprint);
end;
$function$

CREATE OR REPLACE FUNCTION pos.admin_update_sync_device(p_device_id text, p_display_name text, p_device_type text)
 RETURNS pos.sync_devices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare v_row pos.sync_devices;
begin
  if not pos.is_active_admin() then raise exception 'admin_required' using errcode='42501'; end if;
  if nullif(btrim(p_display_name),'') is null then raise exception 'device_name_required'; end if;
  if p_device_type not in ('pc','laptop','tablet','other') then raise exception 'invalid_device_type'; end if;
  update pos.sync_devices set
    display_name = left(btrim(p_display_name), 80),
    device_type = p_device_type,
    metadata = metadata || jsonb_build_object('named_at', now(), 'named_by', auth.uid())
  where device_id = p_device_id
  returning * into v_row;
  if not found then raise exception 'device_not_found'; end if;
  perform pos.bump_sync_domain('devices', p_device_id);
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION pos.complete_sync_command(p_device_id text, p_operation_id text, p_ok boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if auth.uid() is null or not exists(
    select 1 from pos.sync_devices d where d.device_id=p_device_id and d.user_id=auth.uid()
  ) then raise exception 'device_owner_required' using errcode='42501'; end if;
  update pos.sync_activity set action_status=case when p_ok then 'completed' else 'failed' end,
    updated_at=now()
  where device_id=p_device_id and operation_id=p_operation_id
    and admin_action='retry' and action_status='delivered';
  return found;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h83_assert_ornament_items(p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_item jsonb;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'invalid_ornament_snapshot_items';
  end if;
  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if v_item ? 'ornamento'
       and v_item -> 'ornamento' <> 'null'::jsonb
       and jsonb_typeof(v_item -> 'ornamento') <> 'string' then
      raise exception 'invalid_ornament_snapshot';
    end if;
    if v_item ? 'orn_colors' and v_item -> 'orn_colors' <> 'null'::jsonb then
      if jsonb_typeof(v_item -> 'orn_colors') <> 'array' then
        raise exception 'invalid_ornament_color_snapshot';
      end if;
      if exists(select 1
        from jsonb_array_elements(v_item -> 'orn_colors') as color(value)
        where jsonb_typeof(color.value) <> 'string') then
        raise exception 'invalid_ornament_color_snapshot';
      end if;
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h83_commit_return_delegate(p_commit_id text, p_return jsonb, p_items jsonb, p_moves jsonb, p_stock_lines jsonb, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb, p_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
